QT_ISI(30,{"5673":["(Tentang apakah) mengenai apakah (mereka saling bertanya-tanya?) yakni orang-orang Quraisy sebagian di antara mereka bertanya-tanya kepada sebagian yang lainnya.",[["عَمَّ","About what"],["يَتَسَآءَلُونَ","are they asking one another"]]],"5674":["(Tentang berita yang besar) ayat ini merupakan penjelasan bagi sesuatu yang dipertanyakan mereka itu. Sedangkan Istifham atau kata tanya pada ayat yang pertama tadi mengandung makna yang mengagungkannya. Hal yang dimaksud adalah Alquran yang disampaikan oleh Nabi saw. yang di dalamnya terkandung berita mengenai adanya hari berbangkit dan hal-hal lainnya.",[["عَنِ","About"],["ٱلنَّبَإِ","the News"],["ٱلْعَظِيمِ","the Great"]]],"5675":["(Yang mereka perselisihkan tentang ini) orang-orang yang beriman mempercayainya, sedangkan orang-orang kafir mengingkarinya.",[["ٱلَّذِى","(About) which"],["هُمْ","they"],["فِيهِ","(are) concerning it"],["مُخْتَلِفُونَ","(in) disagreement"]]],"5676":["(Sekali-kali tidak) kata ini merupakan sanggahan yang ditujukan kepada orang-orang kafir tadi (kelak mereka mengetahui) apa yang bakal menimpa mereka sebagai akibat daripada keingkaran mereka kepada Alquran.",[["كَلَّا","Nay"],["سَيَعْلَمُونَ","(soon) they will know"]]],"5677":["(Kemudian sekali-kali tidak; kelak mereka mengetahui) ayat ini merupakan pengukuh dari ayat sebelumnya; dan pada ayat ini dipakai kata Tsumma untuk memberikan pengertian, bahwa ancaman yang kedua lebih keras dan lebih berat daripada ancaman yang dikandung pada ayat sebelumnya. Selanjutnya Allah swt. memberikan isyarat yang menunjukkan tentang kekuasaan-Nya untuk membangkitkan makhluk semuanya; untuk itu Dia berfirman:",[["ثُمَّ","Then"],["كَلَّا","Nay"],["سَيَعْلَمُونَ","(soon) they will know"]]],"5678":["(Bukankah Kami telah menjadikan bumi itu sebagai hamparan) yakni terhampar bagaikan permadani.",[["أَلَمْ","Have not"],["نَجْعَلِ","We made"],["ٱلْأَرْضَ","the earth"],["مِهَـٰدًۭا","a resting place"]]],"5679":["(Dan gunung-gunung sebagai pasak) yang menstabilkan bumi, sebagaimana halnya kemah yang berdiri dengan mantapnya berkat patok-patok yang menyangganya. Istifham atau kata tanya di sini mengandung makna Taqrir atau menetapkan.",[["وَٱلْجِبَالَ","And the mountains"],["أَوْتَادًۭا","(as) pegs"]]],"5680":["(Dan Kami jadikan kalian berpasang-pasangan) yaitu terdiri dari jenis laki-laki dan perempuan.",[["وَخَلَقْنَـٰكُمْ","And We created you"],["أَزْوَٰجًۭا","(in) pairs"]]],"5681":["(Dan Kami jadikan tidur kalian untuk istirahat) untuk istirahat bagi tubuh kalian.",[["وَجَعَلْنَا","And We made"],["نَوْمَكُمْ","your sleep"],["سُبَاتًۭا","(for) rest"]]],"5682":["(Dan Kami jadikan malam sebagai pakaian) sebagai penutup karena kegelapannya.",[["وَجَعَلْنَا","And We made"],["ٱلَّيْلَ","the night"],["لِبَاسًۭا","(as) covering"]]],"5683":["(Dan Kami jadikan siang untuk mencari penghidupan) yaitu waktu untuk mencari penghidupan.",[["وَجَعَلْنَا","And We made"],["ٱلنَّهَارَ","the day"],["مَعَاشًۭا","(for) livelihood"]]],"5684":["(Dan Kami bina di atas kalian tujuh lapis) maksudnya langit yang berlapis tujuh (yang kokoh) lafal Syidaadan adalah bentuk jamak dari lafal Syadidatun, artinya sangat kuat lagi sangat rapi yang tidak terpengaruh oleh berlalunya zaman.",[["وَبَنَيْنَا","And We constructed"],["فَوْقَكُمْ","over you"],["سَبْعًۭا","seven"],["شِدَادًۭا","strong"]]],"5685":["(Dan Kami jadikan pelita) yang menerangi (yang amat terang) yang dimaksud adalah matahari.",[["وَجَعَلْنَا","And We placed"],["سِرَاجًۭا","a lamp"],["وَهَّاجًۭا","burning"]]],"5686":["(Dan Kami turunkan dari awan yang tebal) yaitu awan yang banyak mengandung air dan sudah saatnya menurunkan air yang dikandungnya, sebagaimana halnya seorang gadis yang sudah masanya untuk berhaid (air yang tercurah) artinya bagaikan air yang dicurahkan.",[["وَأَنزَلْنَا","And We sent down"],["مِنَ","from"],["ٱلْمُعْصِرَٰتِ","the rain clouds"],["مَآءًۭ","water"],["ثَجَّاجًۭا","pouring abundantly"]]],"5687":["(Supaya Kami tumbuhkan dengan air itu biji-bijian) seperti biji gandum (dan tumbuh-tumbuhan) seperti buah Tin.",[["لِّنُخْرِجَ","That We may bring forth"],["بِهِۦ","thereby"],["حَبًّۭا","grain"],["وَنَبَاتًۭا","and vegetation"]]],"5688":["(Dan kebun-kebun) atau taman-taman (yang lebat) tumbuh-tumbuhannya; lafal Alfaafan bentuk jamak dari lafal Lafiifun, wazannya sama dengan lafal Syariifun yang bentuk jamaknya adalah Asyraafun.",[["وَجَنَّـٰتٍ","And gardens"],["أَلْفَافًا","(of) thick foliage"]]],"5689":["(Sesungguhnya hari keputusan) di antara semua makhluk (adalah suatu waktu yang ditetapkan) waktu yang ditentukan untuk memberi pahala dan menimpakan siksaan.",[["إِنَّ","Indeed"],["يَوْمَ","(the) Day"],["ٱلْفَصْلِ","(of) the Judgment"],["كَانَ","is"],["مِيقَـٰتًۭا","an appointed time"]]],"5690":["(Yaitu hari ditiup sangkakala) menjadi Badal dari lafal Yaumal Fashl; atau merupakan Bayan daripadanya; yang meniupnya adalah malaikat Israfil (lalu kalian datang) dari kuburan kalian menuju ke Mauqif atau tempat penantian (berkelompok-kelompok) secara bergelombang yang masing-masing gelombang berbeda dari gelombang yang lainnya.",[["يَوْمَ","(The) Day"],["يُنفَخُ","(in which) shall be blown"],["فِى","in"],["ٱلصُّورِ","the trumpet"],["فَتَأْتُونَ","and you will come forth"],["أَفْوَاجًۭا","(in) crowds"]]],"5691":["(Dan dibukalah langit) dapat dibaca Futtihat dan Futihat, artinya langit terbelah karena para malaikat turun (maka terdapatlah beberapa pintu) yakni langit itu membentuk beberapa pintu.",[["وَفُتِحَتِ","And is opened"],["ٱلسَّمَآءُ","the heaven"],["فَكَانَتْ","and becomes"],["أَبْوَٰبًۭا","gateways"]]],"5692":["(Dan dijalankanlah gunung-gunung) maksudnya, lenyap dari tempat-tempatnya (maka menjadi fatamorganalah ia) menjadi debu yang beterbangan, atau dengan kata lain gunung-gunung itu menjadi sangat ringan jalannya bagaikan debu yang diterbangkan.",[["وَسُيِّرَتِ","And are moved"],["ٱلْجِبَالُ","the mountains"],["فَكَانَتْ","and become"],["سَرَابًا","a mirage"]]],"5693":["(Sesungguhnya neraka Jahanam itu padanya ada tempat pengintaian) artinya, selalu mengintai atau ada tempat pengintaian.",[["إِنَّ","Indeed"],["جَهَنَّمَ","Hell"],["كَانَتْ","is"],["مِرْصَادًۭا","lying in wait"]]],"5694":["(Bagi orang-orang yang melampaui batas) karena itu mereka tidak akan dapat menyelamatkan diri daripadanya (sebagai tempat kembali) bagi mereka, karena mereka akan dimasukkan ke dalamnya.",[["لِّلطَّـٰغِينَ","For the transgressors"],["مَـَٔابًۭا","a place of return"]]],"5695":["(Mereka tinggal) lafal Laabitsiina adalah Haal bagi lafal yang tidak disebutkan, yakni telah dipastikan penempatan mereka (di dalamnya berabad-abad) yakni untuk selama-lamanya tanpa ada batasnya; lafal Ahqaaban bentuk jamak dari lafal Huqban.",[["لَّـٰبِثِينَ","(They will) be remaining"],["فِيهَآ","therein"],["أَحْقَابًۭا","(for) ages"]]],"5696":["(Mereka tidak merasakan kesejukan di dalamnya) mereka tidak pernah merasakan tidur di dalamnya (dan tidak pula mendapat minuman) minuman yang lezat.",[["لَّا","Not"],["يَذُوقُونَ","they will taste"],["فِيهَا","therein"],["بَرْدًۭا","coolness"],["وَلَا","and not"],["شَرَابًا","any drink"]]],"5697":["(Kecuali) atau selain (air yang mendidih) yaitu air yang panasnya tak terperikan (dan nanah) dapat dibaca Ghasaaqan dan Ghassaaqan artinya nanah yang keluar dari tubuh penghuni-penghuni neraka; mereka diperbolehkan untuk meminumnya.",[["إِلَّا","Except"],["حَمِيمًۭا","scalding water"],["وَغَسَّاقًۭا","and purulence"]]],"5698":["(Sebagai pembalasan yang setimpal) atau sesuai dengan amal perbuatan mereka, karena tiada suatu dosa pun yang lebih besar daripada kekafiran, dan tiada azab yang lebih besar daripada azab neraka.",[["جَزَآءًۭ","A recompense"],["وِفَاقًا","appropriate"]]],"5699":["(Sesungguhnya mereka tidak mengharapkan) artinya, mereka tidak takut (kepada hisab) karena mereka ingkar kepada adanya hari berbangkit.",[["إِنَّهُمْ","Indeed, they"],["كَانُوا۟","were"],["لَا","not"],["يَرْجُونَ","expecting"],["حِسَابًۭا","an account"]]],"5700":["(Dan mereka mendustakan ayat-ayat Kami) mendustakan Alquran (dengan sesungguh-sungguhnya) maksudnya, dengan kedustaan yang sesungguhnya.",[["وَكَذَّبُوا۟","And they denied"],["بِـَٔايَـٰتِنَا","Our Signs"],["كِذَّابًۭا","(with) denial"]]],"5701":["(Dan segala sesuatu) dari amal-amal perbuatan (telah Kami hitung) telah Kami catat (dalam suatu kitab) yaitu dalam catatan-catatan di Lohmahfuz supaya Kami memberikan balasan kepadanya, antara lain karena kedustaan mereka terhadap Alquran.",[["وَكُلَّ","And every"],["شَىْءٍ","thing"],["أَحْصَيْنَـٰهُ","We have enumerated it"],["كِتَـٰبًۭا","(in) a Book"]]],"5702":["(Karena itu rasakanlah) artinya, lalu dikatakan kepada mereka sewaktu azab menimpa mereka, \"Rasakanlah pembalasan kalian ini.\" (Dan Kami sekali-kali tidak akan menambah kepada kalian selain daripada azab) di samping azab yang kalian rasakan sekarang.",[["فَذُوقُوا۟","So taste"],["فَلَن","and never"],["نَّزِيدَكُمْ","We will increase you"],["إِلَّا","except"],["عَذَابًا","(in) punishment"]]],"5703":["(Sesungguhnya orang-orang yang bertakwa mendapat kemenangan) maksudnya, mendapat tempat kemenangan di surga.",[["إِنَّ","Indeed"],["لِلْمُتَّقِينَ","for the righteous"],["مَفَازًا","(is) success"]]],"5704":["(Yaitu kebun-kebun) lafal ayat ini menjadi Badal dari lafal Mafaazan, atau sebagai penjelasan daripadanya (dan buah anggur) di'athafkan kepada lafal Mafaazan.",[["حَدَآئِقَ","Gardens"],["وَأَعْنَـٰبًۭا","and grapevines"]]],"5705":["(Dan gadis-gadis remaja) yaitu gadis-gadis yang buah dadanya sedang ranum-ranumnya. Lafal Kawaa'ib bentuk jamak dari lafal Kaa'ib (yang sebaya) umurnya, lafal Atraaban bentuk jamak dari lafal Tirbun.",[["وَكَوَاعِبَ","And splendid companions"],["أَتْرَابًۭا","well-matched"]]],"5706":["(Dan gelas-gelas yang penuh) berisi khamar; dan di dalam surah Muhammad disebutkan pada salah satu ayat-Nya, \"... sungai-sungai dari khamar (arak).\" (Q.S. Muhammad, 15)",[["وَكَأْسًۭا","And a cup"],["دِهَاقًۭا","full"]]],"5707":["(Di dalamnya mereka tidak mendengar) yakni di dalam surga itu sewaktu mereka sedang meminum khamar dan merasakan kelezatan-kelezatan lainnya (perkataan yang sia-sia) perkataan yang batil (dan tidak pula dusta) jika dibaca Kidzaaban artinya dusta, jika dibaca Kidzdzaaban artinya kedustaan yang dilakukan oleh seseorang kepada yang lainnya, keadaannya berbeda dengan apa yang terjadi di dunia sewaktu khamar diminum.",[["لَّا","Not"],["يَسْمَعُونَ","they will hear"],["فِيهَا","therein"],["لَغْوًۭا","any vain talk"],["وَلَا","and not"],["كِذَّٰبًۭا","any falsehood"]]],"5708":["(Sebagai balasan dari Rabbmu) dari Allah swt. memberikan hal tersebut kepada penghuni-penghuni surga sebagai pembalasan dari-Nya (dan pemberian) menjadi Badal daripada lafal Jazaa-an (yang cukup banyak) sebagai pembalasan yang banyak; pengertian ini diambil dari perkataan orang-orang Arab: A'thaanii Fa'ahsabanii, arti-Nya, \"Dia memberiku dengan pemberian yang cukup banyak.\" Atau dengan kata lain bahwa memberikan pemberian yang banyak kepadaku sehingga aku mengatakan, \"Cukuplah!\"",[["جَزَآءًۭ","(As) a reward"],["مِّن","from"],["رَّبِّكَ","your Lord"],["عَطَآءً","a gift"],["حِسَابًۭا","(according to) account"]]],"5709":["(Rabb langit dan bumi) dapat dibaca Rabbis Samaawaati Wal Ardhi dan Rabus Samaawaati Wal Ardhi (dan apa yang ada di antara keduanya; Yang Maha Pemurah) demikian pula lafal Ar-Rahmaan dapat dibaca Ar-Rahmaanu dan Ar-Rahmaani disesuaikan dengan lafal Rabbun tadi. (Mereka tiada memiliki) yakni makhluk semuanya (di hadapan-Nya) di hadapan Allah swt. (sepatah kata pun) yaitu tiada seseorang pun yang dapat berbicara kepada-Nya karena takut kepada-Nya.",[["رَّبِّ","Lord"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَمَا","and whatever"],["بَيْنَهُمَا","(is) between both of them"],["ٱلرَّحْمَـٰنِ ۖ","the Most Gracious"],["لَا","not"],["يَمْلِكُونَ","they have power"],["مِنْهُ","from Him"],["خِطَابًۭا","(to) address"]]],"5710":["(Pada hari itu) lafal Yauma merupakan Zharaf bagi lafal Laa Yamlikuuna (ketika ruh berdiri) yakni malaikat Jibril atau bala tentara Allah swt. (dan para malaikat dengan bershaf-shaf) lafal Shaffan menjadi Haal artinya dalam keadaan berbaris bershaf-shaf (mereka tidak berkata-kata) yakni makhluk semuanya (kecuali siapa yang telah diberi izin kepadanya oleh Tuhan Yang Maha Pemurah) untuk berbicara (dan ia mengucapkan) perkataan (yang benar) mereka terdiri dari orang-orang yang beriman dan para Malaikat, seumpamanya mereka memberikan syafaat kepada orang-orang yang diridai oleh-Nya untuk mendapatkan syafaat.",[["يَوْمَ","(The) Day"],["يَقُومُ","will stand"],["ٱلرُّوحُ","the Spirit"],["وَٱلْمَلَـٰٓئِكَةُ","and the Angels"],["صَفًّۭا ۖ","(in) rows"],["لَّا","not"],["يَتَكَلَّمُونَ","they will speak"],["إِلَّا","except"],["مَنْ","(one) who "],["أَذِنَ","permits"],["لَهُ","[for] him"],["ٱلرَّحْمَـٰنُ","the Most Gracious"],["وَقَالَ","and he (will) say"],["صَوَابًۭا","(what is) correct"]]],"5711":["(Itulah hari yang pasti terjadi) hari yang pasti kejadiannya, yaitu hari kiamat. (Maka barang siapa yang menghendaki, niscaya ia menempuh jalan kembali kepada Rabbnya) yakni, kembali kepada Allah dengan mengerjakan ketaatan kepada-Nya, supaya ia selamat dari azab-Nya pada hari kiamat itu.",[["ذَٰلِكَ","That"],["ٱلْيَوْمُ","(is) the Day"],["ٱلْحَقُّ ۖ","the True"],["فَمَن","So whoever"],["شَآءَ","wills"],["ٱتَّخَذَ","let him take"],["إِلَىٰ","towards"],["رَبِّهِۦ","his Lord"],["مَـَٔابًا","a return"]]],"5712":["(Sesungguhnya Kami telah memperingatkan kepada kalian) hai orang-orang kafir Mekah (siksa yang dekat) yakni siksa pada hari kiamat yang akan datang nanti; dan setiap sesuatu yang akan datang itu berarti masa terjadinya sudah dekat (pada hari) menjadi Zharaf dari lafal 'Adzaaban berikut sifatnya yakni berikut lafal Qariiban (manusia melihat) setiap manusia melihat (apa yang telah diperbuat oleh kedua tangannya) yakni perbuatan baik dan perbuatan buruk yang telah dikerjakannya semasa di dunia (dan orang kafir berkata, \"Alangkah baiknya) huruf Ya di sini bermakna Tanbih (sekiranya aku dahulu adalah tanah\") maka aku tidak akan disiksa. Ia mengatakan demikian sewaktu Allah berfirman kepada binatang-binatang semuanya sesudah Dia melakukan hukum kisas sebagian dari mereka terhadap sebagian yang lain: \"Jadilah kamu sekalian tanah!\"",[["إِنَّآ","Indeed We"],["أَنذَرْنَـٰكُمْ","[We] have warned you"],["عَذَابًۭا","(of) a punishment"],["قَرِيبًۭا","near"],["يَوْمَ","(the) Day"],["يَنظُرُ","will see"],["ٱلْمَرْءُ","the man"],["مَا","what"],["قَدَّمَتْ","have sent forth"],["يَدَاهُ","his hands"],["وَيَقُولُ","and will say"],["ٱلْكَافِرُ","the disbeliever"],["يَـٰلَيْتَنِى","O I wish"],["كُنتُ","I were"],["تُرَٰبًۢا","dust"]]],"5713":["(Demi yang mencabut nyawa) atau demi malaikat-malaikat yang mencabut nyawa orang-orang kafir (dengan keras) atau mencabutnya dengan kasar.",[["وَٱلنَّـٰزِعَـٰتِ","By those who extract"],["غَرْقًۭا","violently"]]],"5714":["(Dan demi yang mencabut nyawa dengan lemah lembut) maksudnya, demi malaikat-malaikat yang mencabut nyawa orang-orang mukmin secara pelan-pelan.",[["وَٱلنَّـٰشِطَـٰتِ","And those who draw out"],["نَشْطًۭا","gently"]]],"5715":["(Dan demi yang turun dari langit dengan cepat) yakni demi malaikat-malaikat yang melayang turun dari langit dengan membawa perintah-Nya.",[["وَٱلسَّـٰبِحَـٰتِ","And those who glide"],["سَبْحًۭا","swimming"]]],"5716":["(Dan demi yang mendahului dengan kencang) yaitu malaikat-malaikat yang mendahului dengan kencang membawa arwah orang-orang yang beriman ke surga.",[["فَٱلسَّـٰبِقَـٰتِ","And those who race each other"],["سَبْقًۭا","(in) a race"]]],"5717":["(Dan yang mengatur urusan) dunia, yaitu malaikat-malaikat yang mengatur urusan dunia. Dengan kata lain, demi malaikat-malaikat yang turun untuk mengaturnya. Jawab daripada semua qasam yang telah disebutkan di atas tidak disebutkan, lengkapnya, benar-benar kalian, hai penduduk Mekah yang kafir, akan dibangkitkan. Jawab inilah yang menjadi Amil terhadap ayat berikutnya yaitu:",[["فَٱلْمُدَبِّرَٰتِ","And those who arrange"],["أَمْرًۭا","(the) matter"]]],"5718":["(Pada hari ketika terjadinya guncangan yang hebat) yakni tiupan pertama malaikat Israfil yang mengguncangkan segala sesuatu dengan hebatnya. Kemudian pengertian ini diungkapkan ke dalam bentuk kejadian yang timbul dari tiupan tersebut.",[["يَوْمَ","(The) Day"],["تَرْجُفُ","will quake"],["ٱلرَّاجِفَةُ","the quaking one"]]],"5719":["(Kemudian ia diiringi dengan yang mengikutinya) dengan tiupan yang kedua dari malaikat Israfil; jarak di antara kedua tiupan itu empat puluh tahun; dan jumlah ayat ini berkedudukan menjadi Haal atau kata keterangan keadaan daripada lafal Ar-Raajifah. Dan lafal Al-Yauma dapat mencakup kedua tiupan tersebut, karena itu maka kedudukan Zharafnya dianggap sah. Tiupan yang kedua ini untuk membangkitkan semua makhluk yang mati menjadi hidup kembali, maka setelah tiupan yang kedua, mereka bangkit hidup kembali.",[["تَتْبَعُهَا","Follows it"],["ٱلرَّادِفَةُ","the subsequent"]]],"5720":["(Hati manusia pada waktu itu sangat takut) amat takut dan cemas.",[["قُلُوبٌۭ","Hearts"],["يَوْمَئِذٍۢ","that Day"],["وَاجِفَةٌ","will palpitate"]]],"5721":["(Pandangannya tunduk) yakni hina karena kedahsyatan apa yang disaksikannya.",[["أَبْصَـٰرُهَا","Their eyes"],["خَـٰشِعَةٌۭ","humbled"]]],"5722":["(Mereka berkata) yakni orang-orang kafir yang mempunyai hati dan pandangan itu mengatakan dengan nada yang memperolok-olokkan karena ingkar dan tidak percaya terhadap adanya hari berbangkit (\"Apakah sesungguhnya kami) dapat dibaca secara Tahqiq dan Tas-hil, demikian pula lafal berikutnya yang sama (benar-benar dikembalikan kepada kehidupan yang semula?\") maksudnya, apakah kami sesudah mati akan dikembalikan menjadi hidup seperti semula. Lafal Al-Haafirah menunjukkan makna permulaan sesuatu, antara lain dikatakan: Raja'a Fulaanun Fii Haafiratihi, artinya, si Polan kembali lagi ke arah dia datang.",[["يَقُولُونَ","They say"],["أَءِنَّا","Will we"],["لَمَرْدُودُونَ","indeed be returned"],["فِى","to"],["ٱلْحَافِرَةِ","the former state"]]],"5723":["(\"Apakah apabila kami telah menjadi tulang belulang yang hancur lumat) juga akan dihidupkan kembali?\" Menurut suatu qiraat lafal Nakhiratun dibaca Naahiratun, artinya yang lapuk dan hancur.",[["أَءِذَا","What! When"],["كُنَّا","we are"],["عِظَـٰمًۭا","bones"],["نَّخِرَةًۭ","decayed"]]],"5724":["(Mereka berkata, \"Hal itu) maksudnya, dihidupkan-Nya kami kembali (kalau begitu) atau seandainya hal itu benar terjadi (adalah pengembalian) suatu pengembalian (yang merugikan\") diri kami. Lalu Allah berfirman:",[["قَالُوا۟","They say"],["تِلْكَ","This"],["إِذًۭا","then"],["كَرَّةٌ","(would be) a return"],["خَاسِرَةٌۭ","losing"]]],"5725":["(Sesungguhnya pengembalian itu hanyalah) maksudnya, tiupan yang kedua untuk membangkitkan semua makhluk (dengan tiupan) dengan hardikan (sekali saja) apabila tiupan yang kedua ini telah dilakukan.",[["فَإِنَّمَا","Then only"],["هِىَ","it"],["زَجْرَةٌۭ","(will be) a shout"],["وَٰحِدَةٌۭ","single"]]],"5726":["(Maka dengan serta-merta mereka) yakni semua makhluk (bangun) berada di permukaan bumi dalam keadaan hidup, yang sebelumnya mereka berada di perut bumi dalam keadaan mati.",[["فَإِذَا","And behold"],["هُم","They"],["بِٱلسَّاهِرَةِ","(will be) awakened"]]],"5727":["(Sudahkah sampai kepadamu) hai Muhammad (kisah Musa) lafal ayat ini menjadi Amil bagi lafal berikutnya, yaitu:",[["هَلْ","Has"],["أَتَىٰكَ","(there) come to you"],["حَدِيثُ","(the) story"],["مُوسَىٰٓ","(of) Musa"]]],"5728":["(Tatkala Rabbnya memanggilnya di lembah suci ialah lembah Thuwa) dapat dibaca dengan memakai Tanwin, yaitu Thuwan, dapat pula dibaca tanpa Tanwin, yaitu Thuwa, artinya nama sebuah lembah. Lalu Rabb berkata kepadanya:",[["إِذْ","When"],["نَادَىٰهُ","called him"],["رَبُّهُۥ","his Lord"],["بِٱلْوَادِ","in the valley"],["ٱلْمُقَدَّسِ","the sacred"],["طُوًى","(of) Tuwa"]]],"5729":["(\"Pergilah kamu kepada Firaun sesungguhnya dia telah melampaui batas) kekafirannya telah melampaui batas.",[["ٱذْهَبْ","Go"],["إِلَىٰ","to"],["فِرْعَوْنَ","Firaun"],["إِنَّهُۥ","Indeed, he"],["طَغَىٰ","(has) transgressed"]]],"5730":["(Dan katakanlah, \"Adakah keinginan bagimu) artinya, aku mengajakmu (untuk membersihkan diri\") dari kemusyrikan, seumpamanya kamu bersaksi bahwa tidak ada Tuhan selain Allah. Menurut suatu qiraat lafal Tazakkaa dibaca Tazzakkaa, yang asalnya adalah Tatazakka, kemudian huruf Ta yang kedua diidgamkan kepada huruf Za, sehingga jadilah Tazzakkaa.",[["فَقُلْ","And say"],["هَل","Would"],["لَّكَ","[for] you"],["إِلَىٰٓ","[to]"],["أَن","[that]"],["تَزَكَّىٰ","purify yourself"]]],"5731":["(\"Dan kamu akan kupimpin kepada Rabbmu) maksudnya, aku akan tunjukkan kamu jalan untuk mengetahui-Nya melalui bukti-bukti yang ada (supaya kamu takut kepada-Nya\") karena itu lalu kamu takut kepada-Nya.",[["وَأَهْدِيَكَ","And I will guide you"],["إِلَىٰ","to"],["رَبِّكَ","your Lord"],["فَتَخْشَىٰ","so you would fear"]]],"5732":["(Lalu Musa memperlihatkan kepadanya mukjizat yang besar) di antara mukjizat-mukjizat yang dimilikinya, yang ada tujuh macam itu. Mukjizat yang diperlihatkan kepadanya pada saat itu ialah tangan atau tongkatnya.",[["فَأَرَىٰهُ","Then he showed him"],["ٱلْـَٔايَةَ","the sign"],["ٱلْكُبْرَىٰ","the great"]]],"5733":["(Tetapi Firaun mendustakan) Nabi Musa (dan mendurhakai) Allah swt.",[["فَكَذَّبَ","But he denied"],["وَعَصَىٰ","and disobeyed"]]],"5734":["(Kemudian dia berpaling) dari iman (seraya berjalan) di muka bumi dengan menimbulkan kerusakan.",[["ثُمَّ","Then"],["أَدْبَرَ","he turned his back"],["يَسْعَىٰ","striving"]]],"5735":["(Maka dia mengumpulkan) para ahli sihir dan bala tentaranya (lalu berseru.)",[["فَحَشَرَ","And he gathered"],["فَنَادَىٰ","and called out"]]],"5736":["(Seraya berkata, \"Akulah tuhan kalian yang paling tinggi\") tiada tuhan di atasku.",[["فَقَالَ","Then he said"],["أَنَا۠","I am"],["رَبُّكُمُ","your Lord"],["ٱلْأَعْلَىٰ","the Most High"]]],"5737":["(Maka Allah membinasakannya) yakni menenggelamkannya hingga binasa (sebagai pembalasan) atau siksaan (atas yang terakhir ini) disebabkan perkataannya yang terakhir tadi (dan yang pertama) yaitu sebagaimana yang telah disitir oleh firman-Nya, \"... aku tidak mengetahui tuhan bagi kamu sekalian selain aku.\" (Q.S. Al-Qashash, 38) Jarak antara kedua perkataan yang telah dikatakannya itu empat puluh tahun.",[["فَأَخَذَهُ","So seized him"],["ٱللَّهُ","Allah"],["نَكَالَ","(with) an exemplary punishment"],["ٱلْـَٔاخِرَةِ","(for) the last"],["وَٱلْأُولَىٰٓ","and the first"]]],"5738":["(Sesungguhnya pada yang demikian itu) hal yang telah disebutkan itu (terdapat pelajaran bagi orang yang takut) kepada Allah swt.",[["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَعِبْرَةًۭ","surely (is) a lesson"],["لِّمَن","for whoever"],["يَخْشَىٰٓ","fears"]]],"5739":["(Apakah kalian) hai orang-orang yang ingkar terhadap adanya hari berbangkit; lafal ayat ini dapat dibaca Tahqiq dan Tas-hil (yang lebih sulit penciptaannya ataukah langit?) yang lebih rumit penciptaannya. (Allah telah membinanya) lafal ayat ini menjelaskan tentang cara penciptaan langit.",[["ءَأَنتُمْ","Are you"],["أَشَدُّ","a more difficult"],["خَلْقًا","creation"],["أَمِ","or"],["ٱلسَّمَآءُ ۚ","the heaven"],["بَنَىٰهَا","He constructed it"]]],"5740":["(Dia meninggikan bangunannya) ayat ini menafsirkan pengertian yang terkandung di dalam lafal Banaahaa; artinya, Dia menjadikan bangunannya berada di atas, maksudnya, dalam ketinggian yang sangat. Tetapi menurut pendapat lain dikatakan, bahwa yang dimaksud dengan Samkahaa adalah atapnya (lalu menyempurnakannya) yakni, Dia menjadikannya dengan sempurna tanpa cacat.",[["رَفَعَ","He raised"],["سَمْكَهَا","its ceiling"],["فَسَوَّىٰهَا","and proportioned it"]]],"5741":["(Dan Dia menjadikan malamnya gelap gulita) membuatnya gelap (dan menjadikan siangnya terang benderang) Dia menampakkan cahaya matahari. Di dalam ungkapan ini lafal Al-Lail atau malam hari dimudhafkan kepada As-Samaa', karena malam hari merupakan kegelapan baginya. Dan dimudhafkan pula kepada matahari, karena matahari merupakan cahaya baginya.",[["وَأَغْطَشَ","And He darkened"],["لَيْلَهَا","its night"],["وَأَخْرَجَ","and brought out"],["ضُحَىٰهَا","its brightness"]]],"5742":["(Dan bumi sesudah itu dihamparkan-Nya) yakni dijadikan-Nya dalam bentuk terhampar, sebenarnya penciptaan bumi itu sebelum penciptaan langit, tetapi masih belum terhamparkan.",[["وَٱلْأَرْضَ","And the earth"],["بَعْدَ","after"],["ذَٰلِكَ","that"],["دَحَىٰهَآ","He spread it"]]],"5743":["(Ia memancarkan) berkedudukan menjadi Haal dengan memperkirakan adanya lafal Qad sebelumnya; artinya Ia mengeluarkan (daripadanya mata air) yakni dengan mengalirkan air dari sumber-sumbernya (dan menumbuhkan tumbuh-tumbuhannya) yakni, pohon-pohon dan rumput-rumputan yang menjadi makanan ternak, dan demikian pula tumbuh-tumbuhan yang menjadi makanan pokok manusia, serta buah-buahannya. Dikaitkannya istilah Al-Mar'aa kepada bumi hanyalah merupakan ungkapan Isti'arah,",[["أَخْرَجَ","He brought forth"],["مِنْهَا","from it"],["مَآءَهَا","its water"],["وَمَرْعَىٰهَا","and its pasture"]]],"5744":["(Dan gunung-gunung dipancangkan-Nya dengan teguh) yakni dipancangkan di atas bumi supaya bumi stabil dan tidak berguncang.",[["وَٱلْجِبَالَ","And the mountains"],["أَرْسَىٰهَا","He made them firm"]]],"5745":["(Untuk kesenangan) lafal Mataa'an berkedudukan menjadi Maf'ul Lah bagi lafal yang tidak disebutkan, lengkapnya, Dia melakukan hal tersebut untuk kesenangan. Atau lafal Mataa'an ini dianggap sebagai Mashdar, artinya memberikan kesenangan (buat kalian dan buat binatang-binatang ternak kalian) lafal An'aam ini adalah jamak dari lafal Na'amun artinya binatang ternak mencakup unta, sapi, dan kambing.",[["مَتَـٰعًۭا","(As) a provision"],["لَّكُمْ","for you"],["وَلِأَنْعَـٰمِكُمْ","and for your cattle"]]],"5746":["(Maka apabila malapetaka yang sangat besar telah datang) yaitu tiupan sangkakala malaikat Israfil yang kedua.",[["فَإِذَا","But when"],["جَآءَتِ","comes"],["ٱلطَّآمَّةُ","the Overwhelming Calamity"],["ٱلْكُبْرَىٰ","the great"]]],"5747":["(Pada hari ketika manusia teringat) lafal Yauma berkedudukan menjadi Badal daripada lafal Idzaa (akan apa yang telah dikerjakannya) sewaktu ia masih di dunia, apakah itu perbuatan baik atau perbuatan buruk.",[["يَوْمَ","(The) Day"],["يَتَذَكَّرُ","will remember"],["ٱلْإِنسَـٰنُ","man"],["مَا","what"],["سَعَىٰ","he strove (for)"]]],"5748":["(Dan diperlihatkan dengan jelas) ditampakkan dengan seterang-terangnya (neraka) yakni neraka Jahim yang membakar itu (kepada setiap orang yang melihat) kepada setiap orang yang melihatnya. Jawab dari lafal Idzaa ialah:",[["وَبُرِّزَتِ","And will be made manifest"],["ٱلْجَحِيمُ","the Hellfire"],["لِمَن","to (him) who"],["يَرَىٰ","sees"]]],"5749":["(Adapun orang yang melampaui batas) yakni orang kafir.",[["فَأَمَّا","Then as for"],["مَن","(him) who"],["طَغَىٰ","transgressed"]]],"5750":["(Dan lebih mengutamakan kehidupan dunia) dengan cara selalu mengikuti kemauan hawa nafsunya.",[["وَءَاثَرَ","And preferred"],["ٱلْحَيَوٰةَ","the life"],["ٱلدُّنْيَا","(of) the world"]]],"5751":["(Maka sesungguhnya nerakalah tempat tinggal) bagi dia.",[["فَإِنَّ","Then indeed"],["ٱلْجَحِيمَ","the Hellfire"],["هِىَ","it"],["ٱلْمَأْوَىٰ","(is) the refuge"]]],"5752":["(Dan adapun orang yang takut kepada kebesaran Rabbnya) di kala ia berdiri di hadapan-Nya (dan menahan diri) menahan nafsu amarahnya (dari keinginan hawa nafsunya) yang menjerumuskan ke dalam kebinasaan disebabkan memperturutkan kemauannya.",[["وَأَمَّا","But as for"],["مَنْ","(him) who"],["خَافَ","feared"],["مَقَامَ","standing"],["رَبِّهِۦ","(before) his Lord"],["وَنَهَى","and restrained"],["ٱلنَّفْسَ","his soul"],["عَنِ","from"],["ٱلْهَوَىٰ","the vain desires"]]],"5753":["(Maka sesungguhnya surgalah tempat tinggalnya) kesimpulan makna yang terkandung di dalam Jawab syarat ini ialah, bahwasanya orang yang durhaka akan dimasukkan ke dalam neraka, dan orang yang taat akan dimasukkan ke dalam surga.",[["فَإِنَّ","Then indeed"],["ٱلْجَنَّةَ","Paradise "],["هِىَ","it (is)"],["ٱلْمَأْوَىٰ","the refuge"]]],"5754":["(Mereka bertanya kepadamu) yakni orang-orang kafir Mekah itu (tentang hari kiamat, kapan terjadinya) kapankah saat terjadinya.",[["يَسْـَٔلُونَكَ","They ask you"],["عَنِ","about"],["ٱلسَّاعَةِ","the Hour"],["أَيَّانَ","when"],["مُرْسَىٰهَا","(is) its arrival"]]],"5755":["(Tentang apakah) atau mengenai apakah (hingga kamu dapat menyebutkan waktunya?) maksudnya, kamu tidak memiliki ilmu mengenai kejadiannya sehingga kamu dapat menyebutkan waktunya.",[["فِيمَ","In what"],["أَنتَ","(are) you"],["مِن","[of]"],["ذِكْرَىٰهَآ","(to) mention it"]]],"5756":["(Kepada Rabbmulah dikembalikan kesudahannya) yaitu mengenai ketentuan waktunya, tiada seseorang pun yang mengetahuinya selain Dia.",[["إِلَىٰ","To"],["رَبِّكَ","your Lord"],["مُنتَهَىٰهَآ","(is) its finality"]]],"5757":["(Kamu hanyalah pemberi peringatan), maksudnya sesungguhnya peringatanmu itu hanyalah bermanfaat (bagi siapa yang takut kepadanya) yakni takut kepada hari kiamat.",[["إِنَّمَآ","Only"],["أَنتَ","you"],["مُنذِرُ","(are) a warner"],["مَن","(for him) who"],["يَخْشَىٰهَا","fears it"]]],"5758":["(Pada hari mereka melihat hari itu, mereka merasa seakan-akan tidak tinggal) di dalam kubur mereka (melainkan sebentar saja di waktu sore atau pagi hari) artinya, pada suatu sore hari atau pada suatu pagi hari. Di sini dianggap sah mengidhafahkan lafal Adh-Dhuhaa kepada lafal Al-'Asyiyyah, disebabkan di antara keduanya terdapat kaitan yang amat erat, sebab kedua-duanya merupakan permulaan dan penghujung suatu hari, dan Idhafah di sini dianggap baik karena kedua kalimatnya terpisah.",[["كَأَنَّهُمْ","As though they"],["يَوْمَ","(the) Day"],["يَرَوْنَهَا","they see it"],["لَمْ","not"],["يَلْبَثُوٓا۟","they had remained"],["إِلَّا","except"],["عَشِيَّةً","an evening"],["أَوْ","or"],["ضُحَىٰهَا","a morning thereof"]]],"5759":["(Dia telah bermuka masam) yakni Nabi Muhammad telah bermuka masam (dan berpaling) yaitu memalingkan mukanya karena,",[["عَبَسَ","He frowned"],["وَتَوَلَّىٰٓ","and turned away"]]],"5760":["(telah datang seorang buta kepadanya) yaitu Abdullah bin Umi Maktum. Nabi saw. tidak melayaninya karena pada saat itu ia sedang sibuk menghadapi orang-orang yang diharapkan untuk dapat masuk Islam, mereka terdiri dari orang-orang terhormat kabilah Quraisy, dan ia sangat menginginkan mereka masuk Islam. Sedangkan orang yang buta itu atau Abdullah bin Umi Maktum tidak mengetahui kesibukan Nabi saw. pada waktu itu, karena ia buta. Maka Abdullah bin Umi Maktum langsung menghadap dan berseru, \"Ajarkanlah kepadaku apa-apa yang telah Allah ajarkan kepadamu.\" Akan tetapi Nabi saw. pergi berpaling darinya menuju ke rumah, maka turunlah wahyu yang menegur sikapnya itu, yaitu sebagaimana yang disebutkan dalam surat ini. Nabi saw. setelah itu, apabila datang Abdullah bin Umi Maktum berkunjung kepadanya, beliau selalu mengatakan, \"Selamat datang orang yang menyebabkan Rabbku menegurku karenanya,\" lalu beliau menghamparkan kain serbannya sebagai tempat duduk Abdullah bin Umi Maktum.",[["أَن","Because"],["جَآءَهُ","came to him"],["ٱلْأَعْمَىٰ","the blind man"]]],"5761":["(Tahukah kamu) artinya, mengertikah kamu (barangkali ia ingin membersihkan dirinya) dari dosa-dosa setelah mendengar dari kamu; lafal Yazzakkaa bentuk asalnya adalah Yatazakkaa, kemudian huruf Ta diidgamkan kepada huruf Za sehingga jadilah Yazzakkaa.",[["وَمَا","But what"],["يُدْرِيكَ","would make you know"],["لَعَلَّهُۥ","that he might"],["يَزَّكَّىٰٓ","purify himself"]]],"5762":["(Atau dia ingin mendapatkan pelajaran) lafal Yadzdzakkaru bentuk asalnya adalah Yatadzakkaru, kemudian huruf Ta diidgamkan kepada huruf Dzal sehingga jadilah Yadzdzakkaru, artinya mengambil pelajaran dan nasihat (lalu pengajaran itu memberi manfaat kepadanya) atau nasihat yang telah didengarnya dari kamu bermanfaat bagi dirinya. Menurut suatu qiraat lafal Fatanfa'ahu dibaca Fatanfa'uhu, yaitu dibaca Nashab karena menjadi Jawab dari Tarajji atau lafal La'allahuu tadi.",[["أَوْ","Or"],["يَذَّكَّرُ","be reminded"],["فَتَنفَعَهُ","so would benefit him"],["ٱلذِّكْرَىٰٓ","the reminder"]]],"5763":["(Adapun orang yang merasa dirinya serba cukup) karena memiliki harta.",[["أَمَّا","As for"],["مَنِ","(him) who"],["ٱسْتَغْنَىٰ","considers himself free from need"]]],"5764":["(Maka kamu melayaninya) atau menerima dan mengajukan tawaranmu; menurut suatu qiraat lafal Tashaddaa dibaca Tashshaddaa yang bentuk asalnya adalah Tatashaddaa, kemudian huruf Ta kedua diidgamkan kepada huruf Shad, sehingga jadilah Tashshaddaa.",[["فَأَنتَ","So you"],["لَهُۥ","to him"],["تَصَدَّىٰ","give attention"]]],"5765":["(Padahal tidak ada celaan atasmu kalau dia tidak membersihkan diri) yakni orang yang serba berkecukupan itu tidak beriman.",[["وَمَا","And not"],["عَلَيْكَ","upon you"],["أَلَّا","that not"],["يَزَّكَّىٰ","he purifies himself"]]],"5766":["(Dan adapun orang yang datang kepadamu dengan bersegera) lafal Yas'aa berkedudukan sebagai Haal atau kata keterangan keadaan bagi Fa'il atau subjek yang terkandung di dalam lafal Jaa-a.",[["وَأَمَّا","But as for"],["مَن","(he) who"],["جَآءَكَ","came to you"],["يَسْعَىٰ","striving"]]],"5767":["(Sedangkan ia takut) kepada Allah swt.; lafal Yakhsyaa menjadi Haal dari fa'il yang terdapat di dalam lafal Yas'aa, yang dimaksud adalah si orang buta itu atau Abdullah bin Umi Maktum.",[["وَهُوَ","While he"],["يَخْشَىٰ","fears"]]],"5768":["(Maka kamu mengabaikannya) artinya, tiada memperhatikannya sama sekali; lafal Talahhaa asalnya Tatalahhaa, kemudian salah satu dari kedua huruf Ta dibuang, sehingga jadilah Talahhaa.",[["فَأَنتَ","But you"],["عَنْهُ","from him"],["تَلَهَّىٰ","(are) distracted"]]],"5769":["(Sekali-kali jangan) berbuat demikian, yakni janganlah kamu berbuat hal yang serupa lagi. (Sesungguhnya hal ini) maksudnya, surat ini atau ayat-ayat ini (adalah suatu peringatan) suatu pelajaran bagi makhluk semuanya.",[["كَلَّآ","Nay"],["إِنَّهَا","Indeed, it"],["تَذْكِرَةٌۭ","(is) a reminder"]]],"5770":["(Maka barang siapa yang menghendaki, tentulah ia memperhatikannya) atau tentu ia menghafalnya kemudian menjadikannya sebagai nasihat bagi dirinya.",[["فَمَن","So whosoever"],["شَآءَ","wills"],["ذَكَرَهُۥ","may remember it"]]],"5771":["(Di dalam kitab-kitab) menjadi Khabar yang kedua, karena sesungguhnya ia dan yang sebelumnya berkedudukan sebagai jumlah Mu'taridhah atau kalimat sisipan (yang dimuliakan) di sisi Allah.",[["فِى","In"],["صُحُفٍۢ","sheets"],["مُّكَرَّمَةٍۢ","honored"]]],"5772":["(Yang ditinggikan) di langit (lagi disucikan) dari sentuhan setan.",[["مَّرْفُوعَةٍۢ","Exalted"],["مُّطَهَّرَةٍۭ","purified"]]],"5773":["(Di tangan para penulis) yakni malaikat-malaikat yang menukilnya dari Lohmahfuz.",[["بِأَيْدِى","In (the) hands"],["سَفَرَةٍۢ","(of) scribes"]]],"5774":["(Yang mulia lagi berbakti) artinya, semuanya taat kepada Allah swt.; mereka itu adalah malaikat-malaikat.",[["كِرَامٍۭ","Noble"],["بَرَرَةٍۢ","dutiful"]]],"5775":["(Binasalah manusia) maksudnya, terlaknatlah orang kafir itu (alangkah sangat kekafirannya) Istifham atau kata tanya pada ayat ini mengandung makna celaan; makna yang dimaksud, apakah gerangan yang mendorongnya berlaku kafir?",[["قُتِلَ","Is destroyed"],["ٱلْإِنسَـٰنُ","[the] man"],["مَآ","how"],["أَكْفَرَهُۥ","ungrateful is he"]]],"5776":["(Dari apakah Allah menciptakannya?) Istifham atau kata tanya di sini mengandung makna Taqrir. Kemudian Allah menjelaskannya melalui firman berikutnya:",[["مِنْ","From"],["أَىِّ","what"],["شَىْءٍ","thing"],["خَلَقَهُۥ","He created him"]]],"5777":["(Dari setetes mani, Allah menciptakannya lalu menentukannya) menjadi 'alaqah, kemudian menjadi segumpal daging hingga akhir penciptaannya.",[["مِن","From"],["نُّطْفَةٍ","a semen-drop"],["خَلَقَهُۥ","He created him"],["فَقَدَّرَهُۥ","then He proportioned him"]]],"5778":["(Kemudian untuk menempuh jalannya) yakni jalan ia keluar dari perut ibunya (Dia memudahkannya.)",[["ثُمَّ","Then"],["ٱلسَّبِيلَ","the way"],["يَسَّرَهُۥ","He made easy for him"]]],"5779":["(Kemudian Dia mematikannya dan memasukkannya ke dalam kubur) artinya, Dia menjadikannya berada di dalam kubur yang menutupinya.",[["ثُمَّ","Then"],["أَمَاتَهُۥ","He causes him to die"],["فَأَقْبَرَهُۥ","and provides a grave for him"]]],"5780":["(Kemudian bila Dia menghendaki, Dia membangkitkannya kembali) menjadi hidup kembali pada hari berbangkit nanti.",[["ثُمَّ","Then"],["إِذَا","when"],["شَآءَ","He wills"],["أَنشَرَهُۥ","He will resurrect him"]]],"5781":["(Tidaklah demikian) artinya, benarlah (manusia itu belum melaksanakan) belum mengerjakan (apa yang diperintahkan Allah kepadanya) yakni apa yang telah diperintahkan oleh Rabbnya supaya ia mengerjakannya.",[["كَلَّا","Nay"],["لَمَّا","Not"],["يَقْضِ","he has accomplished"],["مَآ","what"],["أَمَرَهُۥ","He commanded him"]]],"5782":["(Maka hendaklah manusia itu memperhatikan) dengan memasang akalnya (kepada makanannya) bagaimanakah makanan itu diciptakan dan diatur untuknya?",[["فَلْيَنظُرِ","Then let look"],["ٱلْإِنسَـٰنُ","the man"],["إِلَىٰ","at"],["طَعَامِهِۦٓ","his food"]]],"5783":["(Sesungguhnya Kami telah mencurahkan air) dari awan (dengan sebenar-benarnya.)",[["اَنَّا","That [We]"],["صَبَبْنَا","[We] poured"],["ٱلْمَآءَ","the water"],["صَبًّۭا","(in) abundance"]]],"5784":["(Kemudian Kami belah bumi) dengan tumbuh-tumbuhan yang tumbuh dari dalamnya (dengan sebaik-baiknya.)",[["ثُمَّ","Then"],["شَقَقْنَا","We cleaved"],["ٱلْأَرْضَ","the earth"],["شَقًّۭا","splitting"]]],"5785":["(Lalu Kami tumbuhkan biji-bijian di bumi itu) seperti biji gandum dan biji jawawut.",[["فَأَنۢبَتْنَا","Then We caused to grow"],["فِيهَا","therein"],["حَبًّۭا","grain"]]],"5786":["(Anggur dan sayur-sayuran) atau sayur-mayur.",[["وَعِنَبًۭا","And grapes"],["وَقَضْبًۭا","and green fodder"]]],"5787":["(Zaitun dan pohon kurma),",[["وَزَيْتُونًۭا","And olive"],["وَنَخْلًۭا","and date-palms"]]],"5788":["(dan kebun-kebun yang lebat) yakni kebun-kebun yang banyak pepohonannya.",[["وَحَدَآئِقَ","And gardens"],["غُلْبًۭا","(of) thick foliage"]]],"5789":["(Dan buah-buahan serta rumput-rumputan) yaitu tumbuh-tumbuhan yang menjadi makanan binatang ternak; tetapi menurut suatu pendapat \"Abban\" artinya makanan ternak yang berasal dari tangkai atau bulir gandum atau padi dan lain sebagainya yang sejenis.",[["وَفَـٰكِهَةًۭ","And fruits"],["وَأَبًّۭا","and grass"]]],"5790":["(Untuk kesenangan) sebagai kesenangan atau untuk menyenangkan, penafsirannya sebagaimana yang telah disebutkan tadi pada surat sebelumnya (bagi kalian dan bagi binatang-binatang ternak kalian) penafsirannya sama dengan yang terdahulu pada surat sebelumnya.",[["مَّتَـٰعًۭا","(As) a provision"],["لَّكُمْ","for you"],["وَلِأَنْعَـٰمِكُمْ","and for your cattle"]]],"5791":["(Dan apabila datang suara yang memekakkan) yakni tiupan sangkakala yang kedua.",[["فَإِذَا","But when"],["جَآءَتِ","comes"],["ٱلصَّآخَّةُ","the Deafening Blast"]]],"5792":["(Pada hari ketika manusia lari dari saudaranya.)",[["يَوْمَ","(The) Day"],["يَفِرُّ","will flee"],["ٱلْمَرْءُ","a man"],["مِنْ","from"],["أَخِيهِ","his brother"]]],"5793":["(Dari ibu dan bapaknya.)",[["وَأُمِّهِۦ","And his mother"],["وَأَبِيهِ","and his father"]]],"5794":["(Dari teman hidupnya) yakni istrinya (dan anak-anaknya) lafal Yauma merupakan Badal dari lafal Idzaa, sebagai Jawabnya disimpulkan dari berikut ini.",[["وَصَـٰحِبَتِهِۦ","And his wife"],["وَبَنِيهِ","and his children"]]],"5795":["(Setiap orang dari mereka pada hari itu mempunyai urusan yang cukup menyibukkannya) yakni keadaan yang membuatnya tidak mengindahkan hal-hal lainnya, atau dengan kata lain setiap orang pada hari itu sibuk dengan urusannya masing-masing.",[["لِكُلِّ","For every"],["ٱمْرِئٍۢ","man"],["مِّنْهُمْ","among them"],["يَوْمَئِذٍۢ","that Day"],["شَأْنٌۭ","(will be) a matter"],["يُغْنِيهِ","occupying him"]]],"5796":["(Banyak muka pada hari itu berseri-seri) yakni tampak cerah ceria.",[["وُجُوهٌۭ","Faces"],["يَوْمَئِذٍۢ","that Day"],["مُّسْفِرَةٌۭ","(will be) bright"]]],"5797":["(Tertawa dan gembira) atau bergembira, mereka itu adalah orang-orang yang beriman.",[["ضَاحِكَةٌۭ","Laughing"],["مُّسْتَبْشِرَةٌۭ","rejoicing at good news"]]],"5798":["(Dan banyak pula muka pada hari itu tertutup debu) artinya, penuh dengan debu.",[["وَوُجُوهٌۭ","And faces"],["يَوْمَئِذٍ","that Day"],["عَلَيْهَا","upon them"],["غَبَرَةٌۭ","(will be) dust"]]],"5799":["(Dan ditutup pula) diselimuti pula (oleh kegelapan) dan kepekatan yang menghitam.",[["تَرْهَقُهَا","Will cover them"],["قَتَرَةٌ","darkness"]]],"5800":["(Mereka itulah) maksudnya, orang-orang yang keadaannya demikian adalah (orang-orang kafir lagi durhaka) yakni orang-orang yang di dalam dirinya berkumpul kekafiran dan kedurhakaan.",[["أُو۟لَـٰٓئِكَ","Those"],["هُمُ","[they]"],["ٱلْكَفَرَةُ","(are) the disbelievers"],["ٱلْفَجَرَةُ","the wicked ones"]]],"5801":["(Apabila matahari digulung) dilipat dan sinarnya menjadi lenyap.",[["إِذَا","When"],["ٱلشَّمْسُ","the sun"],["كُوِّرَتْ","is wrapped up"]]],"5802":["(Dan apabila bintang-bintang berjatuhan) menukik berjatuhan ke bumi.",[["وَإِذَا","And when"],["ٱلنُّجُومُ","the stars"],["ٱنكَدَرَتْ","fall, losing their luster"]]],"5803":["(Dan apabila gunung-gunung dihancurkan) dilenyapkan dari muka bumi dan menjadi debu yang beterbangan.",[["وَإِذَا","And when"],["ٱلْجِبَالُ","the mountains"],["سُيِّرَتْ","are moved away"]]],"5804":["(Dan apabila unta-unta yang bunting) unta-unta yang sedang bunting (ditinggalkan) dibiarkan begitu saja tanpa penggembala atau tanpa diperah susunya, karena mereka disibukkan oleh peristiwa yang dahsyat, sehingga mereka lupa akan segala-galanya. Sesungguhnya unta yang sedang bunting itu merupakan harta yang paling berharga di kalangan mereka.",[["وَإِذَا","And when"],["ٱلْعِشَارُ","the full-term she-camels"],["عُطِّلَتْ","(are) left untended"]]],"5805":["(Dan apabila binatang-binatang liar dikumpulkan) yakni dikumpulkan sesudah dibangkitkan; dimaksud untuk diadakan pembalasan hukum kisas; sebagian di antara mereka mengkisas sebagian yang lain, kemudian setelah selesai, menjadi tanah semuanya.",[["وَإِذَا","And when"],["ٱلْوُحُوشُ","the wild beasts"],["حُشِرَتْ","are gathered"]]],"5806":["(Dan apabila lautan dinyalakan) lafal ini dapat dibaca Sujjirat, dan Sujirat, artinya dinyalakan sehingga lautan itu menjadi api.",[["وَإِذَا","And when"],["ٱلْبِحَارُ","the seas"],["سُجِّرَتْ","are made to overflow"]]],"5807":["(Dan apabila ruh-ruh dipertemukan) dengan jasadnya masing-masing.",[["وَإِذَا","And when"],["ٱلنُّفُوسُ","the souls"],["زُوِّجَتْ","are paired"]]],"5808":["(Apabila bayi-bayi perempuan yang dikubur hidup-hidup) karena takut tercela mempunyai anak perempuan dan takut jatuh miskin (ditanya) untuk menjelek-jelekkan pelakunya.",[["وَإِذَا","And when"],["ٱلْمَوْءُۥدَةُ","the female infant buried alive"],["سُئِلَتْ","is asked"]]],"5809":["(Karena dosa apakah dia dibunuh) dibaca Qutilat karena mengisahkan suatu dialog, jawab bayi-bayi perempuan itu; kami dibunuh tanpa dosa.",[["بِأَىِّ","For what"],["ذَنۢبٍۢ","sin"],["قُتِلَتْ","she was killed"]]],"5810":["(Dan apabila catatan-catatan) yakni, catatan-catatan amal perbuatan (dibuka) dapat dibaca Nusyirat dan Nusysyirat; artinya dibuka dan dibeberkan.",[["وَإِذَا","And when"],["ٱلصُّحُفُ","the pages"],["نُشِرَتْ","are laid open"]]],"5811":["(Dan apabila langit dilenyapkan) yakni dicabut dari tempatnya sebagaimana dicabutnya kulit domba.",[["وَإِذَا","And when"],["ٱلسَّمَآءُ","the sky"],["كُشِطَتْ","is stripped away"]]],"5812":["(Dan apabila Jahim) yaitu neraka (dinyalakan) apinya dibesarkan; dapat dibaca Su''irat dan Su'irat.",[["وَإِذَا","And when"],["ٱلْجَحِيمُ","the Hellfire"],["سُعِّرَتْ","is set ablaze"]]],"5813":["(Dan apabila surga didekatkan) didekatkan dan diperlihatkan kepada calon-calon penghuninya supaya mereka masuk ke dalamnya. Jawab dari Idzaa pada awal surat ini beserta lafal-lafal lainnya yang di'athafkan kepadanya ialah:",[["وَإِذَا","And when"],["ٱلْجَنَّةُ","Paradise"],["أُزْلِفَتْ","is brought near"]]],"5814":["(Maka tiap-tiap jiwa akan mengetahui) artinya setiap jiwa akan mengetahui waktu terjadinya hal-hal tersebut, yaitu hari kiamat (apa yang telah dikerjakannya) yaitu perbuatan baik dan perbuatan buruknya.",[["عَلِمَتْ","Will know"],["نَفْسٌۭ","a soul"],["مَّآ","what"],["أَحْضَرَتْ","it has brought"]]],"5815":["(Sungguh, Aku bersumpah) huruf Laa di sini adalah huruf Zaidah (dengan bintang-bintang)",[["فَلَآ","But nay"],["أُقْسِمُ","I swear"],["بِٱلْخُنَّسِ","by the retreating planets"]]],"5816":["(yang beredar dan yang terbenam) yang dimaksud adalah bintang-bintang yang lima, yaitu: Uranus, Yupiter, Mars, Venus dan Pluto. Takhnusu artinya kembali beredar pada garis edarnya ke belakang, terlihat bintang-bintang itu berada di akhir garis edarnya, lalu kembali ke belakang yaitu tempat semula. Lafal Taknisu artinya yang masuk ke dalam kandangnya; maksudnya bintang-bintang tersebut terbenam ke tempat biasa terbenamnya.",[["ٱلْجَوَارِ","Those that run"],["ٱلْكُنَّسِ","(and) disappear"]]],"5817":["(Dan demi malam apabila hampir meninggalkan gelapnya) maksudnya, hampir berpisah dengan kegelapannya, atau pergi meninggalkan kegelapannya.",[["وَٱلَّيْلِ","And the night"],["إِذَا","when"],["عَسْعَسَ","it departs"]]],"5818":["(Dan demi subuh apabila fajarnya mulai menyingsing) yakni mulai menampakkan sinarnya hingga menjadi terang-benderang siang hari.",[["وَٱلصُّبْحِ","And the dawn"],["إِذَا","when"],["تَنَفَّسَ","it breathes"]]],"5819":["(Sesungguhnya ia) yakni Alquran itu (benar-benar firman Allah yang dibawa oleh utusan yang mulia) yakni, dimuliakan oleh Allah, dia adalah malaikat Jibril. Lafal Al-Qaul dimudhafkan kepada lafal Rasuulin karena Al-Qaul atau firman itu dibawa turun olehnya.",[["إِنَّهُۥ","Indeed, it"],["لَقَوْلُ","(is) surely a word"],["رَسُولٍۢ","(of) a Messenger"],["كَرِيمٍۢ","noble"]]],"5820":["(Yang mempunyai kekuatan) yang sangat kuat (di sisi Yang mempunyai 'Arasy) yakni Allah swt. (dia mempunyai kedudukan yang tinggi) lafal 'Inda Dzil 'Arsyi berta'alluq kepada lafal ayat ini. Jelasnya, dia mempunyai kedudukan tinggi di sisi Allah Yang mempunyai Arasy.",[["ذِى","Possessor of"],["قُوَّةٍ","power"],["عِندَ","with"],["ذِى","(the) Owner of"],["ٱلْعَرْشِ","the Throne"],["مَكِينٍۢ","secure"]]],"5821":["(Yang ditaati di sana) yakni dia ditaati oleh semua malaikat yang di langit (lagi dipercaya) untuk menurunkan wahyu.",[["مُّطَاعٍۢ","One to be obeyed"],["ثَمَّ","and"],["أَمِينٍۢ","trustworthy"]]],"5822":["(Dan teman kalian itu sekali-kali bukanlah) yakni Nabi Muhammad saw. Di'athafkan kepada lafal Innahuu hingga seterusnya (orang yang gila) sebagaimana yang kalian tuduhkan kepadanya.",[["وَمَا","And not"],["صَاحِبُكُم","(is) your companion"],["بِمَجْنُونٍۢ","mad"]]],"5823":["(Dan sesungguhnya dia telah melihatnya) yakni, Nabi Muhammad saw. telah melihat malaikat Jibril dalam bentuk aslinya (di ufuk yang terang) yang jelas yaitu, di ketinggian ufuk sebelah timur.",[["وَلَقَدْ","And certainly"],["رَءَاهُ","he saw him"],["بِٱلْأُفُقِ","in the horizon"],["ٱلْمُبِينِ","the clear"]]],"5824":["(Dan bukanlah dia) Nabi Muhammad saw. (terhadap perkara yang gaib) hal-hal yang gaib berupa wahyu dan berita dari langit (sebagai seseorang yang dituduh) membuat-buatnya, ini berdasarkan qiraat yang membacanya Zhaniin dengan memakai huruf Zha. Menurut suatu qiraat dibaca Dhaniin dengan memakai huruf Dhadh; artinya seorang yang bakhil untuk menerangkannya, lalu karenanya ia mengurangi sesuatu daripada wahyu dan berita dari langit tersebut.",[["وَمَا","And not"],["هُوَ","he (is)"],["عَلَى","on"],["ٱلْغَيْبِ","the unseen"],["بِضَنِينٍۢ","a withholder"]]],"5825":["(Dan dia itu bukanlah) yakni, Alquran itu (perkataan setan) artinya hasil curiannya (yang terkutuk) yang dirajam.",[["وَمَا","And not"],["هُوَ","it"],["بِقَوْلِ","(is the) word"],["شَيْطَـٰنٍۢ","(of) Shaitaan"],["رَّجِيمٍۢ","accursed"]]],"5826":["(Maka ke manakah kalian akan pergi?) maksudnya jalan apakah yang kalian tempuh untuk ingkar kepada Alquran dan berpaling daripadanya?",[["فَأَيْنَ","So where"],["تَذْهَبُونَ","are you going"]]],"5827":["(Tiada lain) tidak lain (Alquran itu hanyalah peringatan) atau pelajaran (bagi semesta alam) yakni, manusia dan jin.",[["إِنْ","Not"],["هُوَ","it"],["إِلَّا","(is) except"],["ذِكْرٌۭ","a reminder"],["لِّلْعَـٰلَمِينَ","to the worlds"]]],"5828":["(Yaitu bagi siapa di antara kalian yang mau) lafal ayat ini berkedudukan menjadi Badal dari lafal Al-'Aalamiina dengan mengulangi huruf Jarr-nya (menempuh jalan yang lurus) yaitu mengikuti perkara yang hak.",[["لِمَن","For whoever"],["شَآءَ","wills"],["مِنكُمْ","among you"],["أَن","to"],["يَسْتَقِيمَ","take a straight way"]]],"5829":["(Dan kalian tidak dapat menghendaki) menempuh jalan yang hak itu (kecuali apabila dikehendaki Allah, Rabb semesta alam) barulah kalian dapat menempuh jalan itu. Lafal Al-'Aalamiina artinya mencakup semua makhluk.",[["وَمَا","And not"],["تَشَآءُونَ","you will"],["إِلَّآ","except"],["أَن","that"],["يَشَآءَ","wills"],["ٱللَّهُ","Allah"],["رَبُّ","Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"5830":["(Apabila langit terbelah) atau menjadi belah.",[["إِذَا","When"],["ٱلسَّمَآءُ","the sky"],["ٱنفَطَرَتْ","(is) cleft asunder"]]],"5831":["(Dan apabila bintang-bintang jatuh berserakan) artinya menukik dan berjatuhan.",[["وَإِذَا","And when"],["ٱلْكَوَاكِبُ","the stars"],["ٱنتَثَرَتْ","scatter"]]],"5832":["(Dan apabila laut-laut dijadikan meluap) maksudnya sebagian bertemu dengan sebagian lainnya sehingga seakan-akan menjadi satu lautan, maka bercampurlah air yang tawar dengan air yang asin.",[["وَإِذَا","And when"],["ٱلْبِحَارُ","the seas"],["فُجِّرَتْ","are made to gush forth"]]],"5833":["(Dan apabila kuburan-kuburan dibongkar) maksudnya tanahnya dibalik lalu orang-orang mati yang ada di dalamnya dibangunkan hidup kembali. Sebagai Jawab dari lafal Idzaa berikut lafal-lafal lain yang di'athafkan kepadanya ialah:",[["وَإِذَا","And when"],["ٱلْقُبُورُ","the graves"],["بُعْثِرَتْ","are overturned"]]],"5834":["(Maka tiap-tiap jiwa akan mengetahui) waktu terjadinya hal-hal tersebut, yaitu hari kiamat (apa yang telah dikerjakannya) yaitu amal perbuatan yang telah dikerjakannya (dan) apa (yang dilalaikannya) yang tidak dikerjakannya.",[["عَلِمَتْ","Will know"],["نَفْسٌۭ","a soul"],["مَّا","what"],["قَدَّمَتْ","it has sent forth"],["وَأَخَّرَتْ","and left behind"]]],"5835":["(Hai manusia) yakni orang kafir (apakah yang telah memperdayakan kamu terhadap Rabbmu Yang Maha Mulia) sehingga kamu berbuat durhaka kepada-Nya?",[["يَـٰٓأَيُّهَا","O"],["ٱلْإِنسَـٰنُ","man"],["مَا","What"],["غَرَّكَ","has deceived you"],["بِرَبِّكَ","concerning your Lord"],["ٱلْكَرِيمِ","the Most Noble"]]],"5836":["(Yang telah menciptakan kamu) padahal sebelumnya kamu tidak ada (lalu menyempurnakan kejadianmu) yakni Dia menjadikan kamu dalam bentuk yang sempurna, lengkap dengan anggota-anggota tubuhmu (dan menjadikan kamu seimbang) artinya Dia menjadikan bentukmu seimbang, semua anggota tubuhmu disesuaikan-Nya; tiada tangan atau kaki yang lebih panjang atau lebih pendek dari yang lainnya; dapat dibaca Fa'adalak dan Fa'addalak.",[["ٱلَّذِى","Who"],["خَلَقَكَ","created you"],["فَسَوَّىٰكَ","then fashioned you"],["فَعَدَلَكَ","then balanced you"]]],"5837":["(Dalam bentuk apa saja) huruf Ma di sini adalah huruf Shilah atau kata penghubung (yang Dia kehendaki. Dia menyusun tubuhmu.)",[["فِىٓ","In"],["أَىِّ","whatever"],["صُورَةٍۢ","form"],["مَّا","what"],["شَآءَ","He willed"],["رَكَّبَكَ","He assembled you"]]],"5838":["(Bukan hanya durhaka saja) kalimat ini mengandung makna cegahan atau larangan bersikap lupa daratan terhadap kemurahan Allah swt. (bahkan kalian mendustakan) hai orang-orang kafir Mekah (hari pembalasan) yakni pembalasan amal perbuatan.",[["كَلَّا","Nay"],["بَلْ","But"],["تُكَذِّبُونَ","you deny"],["بِٱلدِّينِ","the Judgment"]]],"5839":["(Padahal sesungguhnya bagi kalian ada yang mengawasi) yaitu malaikat-malaikat yang mengawasi semua amal perbuatan kalian.",[["وَإِنَّ","And indeed"],["عَلَيْكُمْ","over you"],["لَحَـٰفِظِينَ","(are) surely guardians"]]],"5840":["(Yang mulia) artinya mereka dimuliakan di sisi Allah (dan yang mencatat) maksudnya menjadi juru tulis amal perbuatan kalian.",[["كِرَامًۭا","Noble"],["كَـٰتِبِينَ","recording"]]],"5841":["(Mereka mengetahui semua apa yang kalian kerjakan) tanpa kecuali.",[["يَعْلَمُونَ","They know"],["مَا","whatever"],["تَفْعَلُونَ","you do"]]],"5842":["(Sesungguhnya orang-orang yang banyak berbakti) yakni orang-orang mukmin yang benar-benar mantap dalam keimanannya, (benar-benar berada dalam surga yang penuh kenikmatan.)",[["إِنَّ","Indeed"],["ٱلْأَبْرَارَ","the righteous"],["لَفِى","(will be) surely in"],["نَعِيمٍۢ","bliss"]]],"5843":["(Dan sesungguhnya orang-orang yang durhaka) yakni orang-orang kafir (benar-benar berada dalam neraka) yang apinya sangat membakar.",[["وَإِنَّ","And indeed"],["ٱلْفُجَّارَ","the wicked"],["لَفِى","(will be) surely in"],["جَحِيمٍۢ","Hellfire"]]],"5844":["(Mereka masuk ke dalamnya) atau menjadi penghuninya, ia merasakan panas api yang membakar itu (pada hari pembalasan) yaitu di saat mereka menerima pembalasan.",[["يَصْلَوْنَهَا","They will burn (in) it"],["يَوْمَ","(on the) Day"],["ٱلدِّينِ","(of) the Judgment"]]],"5845":["(Dan mereka sekali-kali tidak dapat keluar dari neraka itu) artinya tidak bisa melepaskan diri darinya.",[["وَمَا","And not"],["هُمْ","they"],["عَنْهَا","from it"],["بِغَآئِبِينَ","(will be) absent"]]],"5846":["(Tahukah kamu) lafal Adraaka maknanya sama dengan lafal A'lamaka, yakni tahukah kamu (apakah hari pembalasan itu?)",[["وَمَآ","And what"],["أَدْرَىٰكَ","can make you know"],["مَا","what"],["يَوْمُ","(is the) Day"],["ٱلدِّينِ","(of) the Judgment"]]],"5847":["(Sekali lagi, tahukah kamu apakah hari pembalasan itu?) ayat ini mengungkapkan tentang kedudukan hari pembalasan yang agung itu.",[["ثُمَّ","Then"],["مَآ","what"],["أَدْرَىٰكَ","can make you know"],["مَا","what"],["يَوْمُ","(is the) Day"],["ٱلدِّينِ","(of) the Judgment"]]],"5848":["(Yaitu pada hari) yakni hari itu adalah hari (seseorang tidak berdaya sedikit pun untuk menolong orang lain) atau seseorang tidak dapat memberikan manfaat kepada orang lain. (Dan segala urusan pada hari itu dalam kekuasaan Allah) artinya tiada suatu urusan pun pada hari itu selain-Nya. Dengan kata lain, pada hari itu tiada seorang pun yang dapat menjadi perantara atau penengah, berbeda halnya dengan di dunia.",[["يَوْمَ","(The) Day"],["لَا","not"],["تَمْلِكُ","will have power"],["نَفْسٌۭ","a soul"],["لِّنَفْسٍۢ","for a soul"],["شَيْـًۭٔا ۖ","anything"],["وَٱلْأَمْرُ","and the Command"],["يَوْمَئِذٍۢ","that Day"],["لِّلَّهِ","(will be) with Allah"]]],"5849":["(Kecelakaan besarlah) lafal Wailun merupakan kalimat yang mengandung makna azab; atau merupakan nama sebuah lembah di dalam neraka Jahanam (bagi orang-orang yang curang.)",[["وَيْلٌۭ","Woe"],["لِّلْمُطَفِّفِينَ","to those who give less"]]],"5850":["(Yaitu orang-orang yang apabila menerima takaran dari) atau mereka menerimanya dari (orang lain, mereka minta dipenuhi) minta supaya takaran itu dipenuhi.",[["ٱلَّذِينَ","Those who"],["إِذَا","when"],["ٱكْتَالُوا۟","they take a measure"],["عَلَى","from"],["ٱلنَّاسِ","the people"],["يَسْتَوْفُونَ","they take in full"]]],"5851":["(Dan apabila mereka menakar untuk orang lain) atau menakarkan buat orang lainnya (atau menimbang buat orang lain) artinya mereka menimbang buat orang lain (mereka mengurangi) takaran atau timbangan.",[["وَإِذَا","But when"],["كَالُوهُمْ","they give by measure (to) them"],["أَو","or"],["وَّزَنُوهُمْ","they weigh (for) them"],["يُخْسِرُونَ","they give less"]]],"5852":["(Tidakkah) Istifham atau kata tanya di sini mengandung makna celaan (mempunyai sangkaan) artinya merasa yakin (mereka itu, bahwa sesungguhnya mereka akan dibangkitkan.)",[["أَلَا","Do not"],["يَظُنُّ","think"],["أُو۟لَـٰٓئِكَ","those"],["أَنَّهُم","that they"],["مَّبْعُوثُونَ","(will be) resurrected"]]],"5853":["(Pada suatu hari yang besar) maksudnya pada hari itu mereka dibangkitkan, yaitu pada hari kiamat.",[["لِيَوْمٍ","For a Day"],["عَظِيمٍۢ","Great"]]],"5854":["(Yaitu hari) lafal Yauma menjadi Badal dari lafal Yaumin secara Mahall, yang dinashabkannya adalah lafal Mab'uutsuuna. Lengkapnya pada hari mereka dibangkitkan (manusia berdiri) dari kuburan mereka (menghadap Rabb semesta alam) artinya, semua makhluk dihidupkan kembali untuk memenuhi perintah, hisab dan pembalasan-Nya.",[["يَوْمَ","(The) Day"],["يَقُومُ","will stand"],["ٱلنَّاسُ","mankind"],["لِرَبِّ","before (the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"5855":["(sekali-kali tidak) maksudnya, benarlah (karena sesungguhnya kitab orang-orang yang durhaka) yakni kitab catatan amal perbuatan orang-orang kafir (tersimpan dalam sijjiin) menurut suatu pendapat; sijjiin itu adalah nama sebuah kitab yang mencatat semua amal perbuatan setan dan orang kafir. Menurut suatu pendapat lagi sijjiin itu adalah nama tempat yang berada di lapisan bumi yang ketujuh; tempat itu merupakan pangkalan iblis dan bala tentaranya.",[["كَلَّآ","Nay"],["إِنَّ","Indeed"],["كِتَـٰبَ","(the) record"],["ٱلْفُجَّارِ","(of) the wicked"],["لَفِى","(is) surely in"],["سِجِّينٍۢ","Sijjin"]]],"5856":["(Tahukah kamu apakah sijjiin itu?) maksudnya apakah kitab sijjiin itu?",[["وَمَآ","And what"],["أَدْرَىٰكَ","can make you know"],["مَا","what"],["سِجِّينٌۭ","(is) Sijjin"]]],"5857":["(Ialah kitab yang bertulis) yakni yang mempunyai catatan.",[["كِتَـٰبٌۭ","A book"],["مَّرْقُومٌۭ","written"]]],"5858":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","Woe"],["يَوْمَئِذٍۢ","that Day"],["لِّلْمُكَذِّبِينَ","to the deniers"]]],"5859":["(Yaitu-orang-orang yang mendustakan hari pembalasan) lafal ayat ini berkedudukan sebagai Badal atau Bayan dari lafal Al-Mukadzdzibiin pada ayat sebelumnya.",[["ٱلَّذِينَ","Those who"],["يُكَذِّبُونَ","deny"],["بِيَوْمِ","(the) Day"],["ٱلدِّينِ","(of) the Judgment"]]],"5860":["(Dan tidak ada yang mendustakan hari pembalasan itu melainkan setiap orang yang melampaui batas) atau melanggar batas (lagi berdosa) maksudnya banyak dosanya; lafal Atsiim adalah bentuk Mubalaghah dari lafal Aatsim.",[["وَمَا","And not"],["يُكَذِّبُ","can deny"],["بِهِۦٓ","[of] it"],["إِلَّا","except"],["كُلُّ","every"],["مُعْتَدٍ","transgressor"],["أَثِيمٍ","sinful"]]],"5861":["(Yang apabila dibacakan kepadanya ayat-ayat Kami) yakni Alquran (ia berkata, \"Itu adalah dongengan-dongengan orang-orang yang dahulu\") atau cerita-cerita yang dibuat di masa silam. Lafal Asaathiir bentuk jamak dari lafal Usthuurah atau Isthaarah.",[["إِذَا","When"],["تُتْلَىٰ","are recited"],["عَلَيْهِ","to him"],["ءَايَـٰتُنَا","Our Verses"],["قَالَ","he says"],["أَسَـٰطِيرُ","Stories"],["ٱلْأَوَّلِينَ","(of) the former (people)"]]],"5862":["(Sekali-kali tidak demikian) lafal ini mengandung makna hardikan dan cegahan terhadap perkataan mereka yang demikian itu (sebenarnya telah menodai) telah menutupi (atas hati mereka) sehingga hati mereka tertutup oleh noda itu (apa yang selalu mereka usahakan itu) yakni kedurhakaan-kedurhakaan yang selalu mereka kerjakan, sehingga mirip dengan karat yang menutupi hati mereka.",[["كَلَّا ۖ","Nay"],["بَلْ ۜ","But"],["رَانَ","(the) stain has covered"],["عَلَىٰ","[over]"],["قُلُوبِهِم","their hearts"],["مَّا","(for) what"],["كَانُوا۟","they used to"],["يَكْسِبُونَ","earn"]]],"5863":["(Sekali-kali tidak) artinya benarlah (sesungguhnya mereka pada hari itu terhadap Rabb mereka) pada hari kiamat (benar-benar tertutup) sehingga mereka tidak dapat melihat-Nya.",[["كَلَّآ","Nay"],["إِنَّهُمْ","Indeed, they"],["عَن","from"],["رَّبِّهِمْ","their Lord"],["يَوْمَئِذٍۢ","that Day"],["لَّمَحْجُوبُونَ","surely will be partitioned"]]],"5864":["(Kemudian, sesungguhnya mereka benar-benar masuk Jahim) yakni mereka memasuki neraka yang membakar.",[["ثُمَّ","Then"],["إِنَّهُمْ","indeed, they"],["لَصَالُوا۟","(surely) will burn"],["ٱلْجَحِيمِ","(in) the Hellfire"]]],"5865":["(Kemudian dikatakan) kepada mereka (\"Inilah) maksudnya azab ini (yang dahulu selalu kalian dustakan.\")",[["ثُمَّ","Then"],["يُقَالُ","it will be said"],["هَـٰذَا","This"],["ٱلَّذِى","(is) what"],["كُنتُم","you used to"],["بِهِۦ","[of it]"],["تُكَذِّبُونَ","deny"]]],"5866":["(Sekali-kali tidak) artinya benarlah (sesungguhnya kitab orang-orang berbakti itu) yaitu kitab catatan amal perbuatan orang-orang mukmin yang imannya benar-benar ikhlas (berada dalam 'Illiyyiin) menurut suatu pendapat 'Illiyyiin adalah nama kitab yang mencatat semua amal kebaikan para malaikat dan orang-orang yang beriman dari kalangan manusia dan jin. Menurut pendapat lain 'Illiyyiin adalah nama sebuah tempat yang terletak di langit yang ketujuh, di bawah Arasy.",[["كَلَّآ","Nay"],["إِنَّ","Indeed"],["كِتَـٰبَ","(the) record"],["ٱلْأَبْرَارِ","(of) the righteous"],["لَفِى","(will be) surely in"],["عِلِّيِّينَ","Illiyin"]]],"5867":["(Tahukah kamu) atau apakah kamu mengetahui (apakah 'Illiyyiin itu?) apakah kitab 'Illiyyiin itu?",[["وَمَآ","And what"],["أَدْرَىٰكَ","can make you know"],["مَا","what"],["عِلِّيُّونَ","(is) Illiyun"]]],"5868":["Yaitu (kitab yang bertulis) kitab yang ada catatannya.",[["كِتَـٰبٌۭ","A book"],["مَّرْقُومٌۭ","written"]]],"5869":["(Yang disaksikan oleh yang didekatkan) yakni malaikat-malaikat yang didekatkan.",[["يَشْهَدُهُ","Witness it"],["ٱلْمُقَرَّبُونَ","those brought near"]]],"5870":["(Sesungguhnya orang-orang yang berbakti itu berada dalam kenikmatan yang berlimpah) yakni surga.",[["إِنَّ","Indeed"],["ٱلْأَبْرَارَ","the righteous"],["لَفِى","(will be) surely in"],["نَعِيمٍ","bliss"]]],"5871":["(Di atas dipan-dipan) atau di atas ranjang-ranjang yang berkelambu (mereka memandang) kenikmatan-kenikmatan yang diberikan kepada mereka.",[["عَلَى","On"],["ٱلْأَرَآئِكِ","thrones"],["يَنظُرُونَ","observing"]]],"5872":["(Kamu dapat mengetahui dari wajah mereka kesenangan hidup mereka yang penuh kenikmatan) yakni wajah-wajah yang cerah penuh dengan kenikmatan hidup.",[["تَعْرِفُ","You will recognize"],["فِى","in"],["وُجُوهِهِمْ","their faces"],["نَضْرَةَ","(the) radiance"],["ٱلنَّعِيمِ","(of) bliss"]]],"5873":["(Mereka diberi minum dari khamar murni) atau khamar yang bersih dari kotoran (yang dilak) tempat-tempatnya dan tidak pernah dibuka selain oleh mereka.",[["يُسْقَوْنَ","They will be given to drink"],["مِن","of"],["رَّحِيقٍۢ","a pure wine"],["مَّخْتُومٍ","sealed"]]],"5874":["(Laknya adalah kesturi) setelah diminum keluar daripadanya bau minyak kesturi (dan untuk meraih yang demikian itu hendaknya orang berlomba-lomba) artinya hendaklah mereka menginginkannya dengan cara bersegera taat kepada Allah swt.",[["خِتَـٰمُهُۥ","Its seal"],["مِسْكٌۭ ۚ","(will be of) musk"],["وَفِى","And for"],["ذَٰلِكَ","that"],["فَلْيَتَنَافَسِ","let aspire"],["ٱلْمُتَنَـٰفِسُونَ","the aspirers"]]],"5875":["(Dan campuran khamar murni itu) yaitu barang yang dicampurkan ke dalamnya (adalah tasnim) makna tasnim ditafsirkan atau dijelaskan oleh firman berikutnya:",[["وَمِزَاجُهُۥ","And its mixture"],["مِن","(is) of"],["تَسْنِيمٍ","Tasneem"]]],"5876":["(Yaitu mata air) dinashabkan oleh lafal Amdaha yang tidak disebutkan (yang minum daripadanya orang-orang yang didekatkan kepada Allah) atau makna lafal Yasyrabu ini mengandung pengertian Yaltadzdzu; artinya yang minum dengan lezatnya adalah orang-orang yang didekatkan kepada Allah dari mata air itu.",[["عَيْنًۭا","A spring"],["يَشْرَبُ","will drink"],["بِهَا","from it"],["ٱلْمُقَرَّبُونَ","those brought near"]]],"5877":["(Sesungguhnya orang-orang yang berdosa) seperti Abu Jahal dan lain-lainnya (adalah mereka terhadap orang-orang yang beriman) seperti Ammar bin Yasir, Bilal bin Rabbah dan lain-lainnya (mereka selalu menertawakannya) dan memperolok-olokkannya.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["أَجْرَمُوا۟","committed crimes"],["كَانُوا۟","used to"],["مِنَ","at"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed"],["يَضْحَكُونَ","laugh"]]],"5878":["(Dan apabila mereka berlalu) yakni orang-orang yang beriman itu (di hadapan orang-orang yang berdosa, maka orang-orang yang berdosa itu saling mengedipkan matanya) di antara sesama mereka mengisyaratkan dengan kedipan dan picingan alis mereka kepada orang-orang mukmin yang lewat di hadapan mereka. Isyarat ini untuk memperolok-olokkan mereka yang lewat itu.",[["وَإِذَا","And when"],["مَرُّوا۟","they passed"],["بِهِمْ","by them"],["يَتَغَامَزُونَ","they winked at one another"]]],"5879":["(Dan apabila orang-orang yang berdosa itu kembali) pulang (kepada kaumnya, mereka kembali dengan gembira) menurut suatu qiraat dibaca Faakihiina bukan Fakihiina; artinya mereka merasa puas karena telah memperolok-olokkan kaum mukmin.",[["وَإِذَا","And when"],["ٱنقَلَبُوٓا۟","they returned"],["إِلَىٰٓ","to"],["أَهْلِهِمُ","their people"],["ٱنقَلَبُوا۟","they would return"],["فَكِهِينَ","jesting"]]],"5880":["(Dan apabila mereka melihatnya) yakni melihat orang-orang yang beriman (mereka mengatakan, \"Sesungguhnya mereka itu benar-benar orang-orang yang sesat\") karena mereka telah beriman kepada Muhammad.",[["وَإِذَا","And when"],["رَأَوْهُمْ","they saw them"],["قَالُوٓا۟","they said"],["إِنَّ","Indeed"],["هَـٰٓؤُلَآءِ","these"],["لَضَآلُّونَ","surely have gone astray"]]],"5881":["Allah swt. berfirman (padahal orang-orang yang berdosa itu tidak dikirim) maksudnya orang-orang kafir itu tidak disuruh (kepada orang-orang yang beriman) atau kaum mukmin (sebagai penjaga) bagi mereka, atau bagi amal perbuatan mereka, sehingga berhak untuk membenarkan mereka.",[["وَمَآ","But not"],["أُرْسِلُوا۟","they had been sent"],["عَلَيْهِمْ","over them"],["حَـٰفِظِينَ","(as) guardians"]]],"5882":["(Maka pada hari ini) yakni hari kiamat (orang-orang yang beriman menertawakan orang-orang kafir.)",[["فَٱلْيَوْمَ","So today"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed "],["مِنَ","at"],["ٱلْكُفَّارِ","the disbelievers"],["يَضْحَكُونَ","they will laugh"]]],"5883":["(Mereka duduk di atas dipan-dipan) di surga (sambil memandang) dari tempat tinggal mereka kepada orang-orang kafir yang sedang diazab; maka orang-orang yang beriman itu menertawakan mereka sebagaimana mereka menertawakannya ketika mereka berada di dunia.",[["عَلَى","On"],["ٱلْأَرَآئِكِ","the thrones"],["يَنظُرُونَ","observing"]]],"5884":["(Apakah telah diberi ganjaran) atau telah diberi pembalasan (orang-orang kafir itu sesuai dengan apa yang dahulu mereka kerjakan?) jawabnya, \"Ya\", atau, \"Tentu saja.\"",[["هَلْ","Have (not)"],["ثُوِّبَ","been rewarded"],["ٱلْكُفَّارُ","the disbelievers"],["مَا","(for) what"],["كَانُوا۟","they used to"],["يَفْعَلُونَ","do"]]],"5885":["(Apabila langit terbelah)",[["إِذَا","When"],["ٱلسَّمَآءُ","the sky"],["ٱنشَقَّتْ","is split asunder"]]],"5886":["(Dan patuh) artinya mendengar dan tunduk mau membelah dirinya (kepada Rabbnya, dan sudah semestinya langit itu patuh) langit itu harus patuh dan taat kepada-Nya.",[["وَأَذِنَتْ","And has listened"],["لِرَبِّهَا","to its Lord"],["وَحُقَّتْ","and was obligated"]]],"5887":["(Dan apabila bumi diperlebar) diperluas sebagaimana kulit yang direntangkan, sehingga lenyaplah semua bangunan dan gunung yang ada pada permukaannya. Dengan kata lain, apabila bumi diratakan.",[["وَإِذَا","And when"],["ٱلْأَرْضُ","the earth"],["مُدَّتْ","is spread"]]],"5888":["(Dan dilemparkan apa yang ada di dalamnya) yakni orang-orang mati yang berada di dalam perutnya dicampakkan ke permukaannya (dan menjadi kosong) artinya tiada sesuatu pun yang tertinggal di dalamnya.",[["وَأَلْقَتْ","And has cast out"],["مَا","what"],["فِيهَا","(is) in it"],["وَتَخَلَّتْ","and becomes empty"]]],"5889":["(Dan patuh) tunduk dan taat dalam hal tersebut (kepada Rabbnya dan sudah semestinya bumi itu patuh) hal tersebut terjadi pada hari kiamat. Jawab dari lafal Idzaa dan lafal-lafal yang di'athafkan kepadanya tidak disebutkan, tetapi pengertiannya diisyaratkan oleh firman selanjutnya, yaitu, \"Semua manusia akan menjumpai amal perbuatannya masing-masing.\"",[["وَأَذِنَتْ","And has listened"],["لِرَبِّهَا","to its Lord"],["وَحُقَّتْ","and was obligated"]]],"5890":["(Hai manusia! Sesungguhnya kamu telah bekerja) telah beramal dengan sekuat tenagamu (hingga) menemui (Rabbmu) yakni mati (dengan sungguh-sungguh, maka pasti kalian akan menemuinya) yakni, menemui amal perbuatanmu yang telah disebutkan tadi pada hari kiamat nanti, baik amal kebaikan atau pun amal keburukan, semuanya pasti kamu jumpai.",[["يَـٰٓأَيُّهَا","O"],["ٱلْإِنسَـٰنُ","mankind"],["إِنَّكَ","Indeed, you"],["كَادِحٌ","(are) laboring"],["إِلَىٰ","to"],["رَبِّكَ","your Lord"],["كَدْحًۭا","(with) exertion"],["فَمُلَـٰقِيهِ","and you (will) meet Him"]]],"5891":["(Adapun orang yang diberikan kitabnya) yakni kitab catatan amalnya (dari sebelah kanannya) dia adalah orang yang beriman.",[["فَأَمَّا","Then as for"],["مَنْ","(him) who"],["أُوتِىَ","is given"],["كِتَـٰبَهُۥ","his record"],["بِيَمِينِهِۦ","in his right (hand)"]]],"5892":["(Maka dia akan diperiksa dengan pemeriksaan yang mudah) yaitu pada hari ditampakkan kepadanya amal perbuatannya, sebagaimana yang telah disebutkan di dalam salah satu hadis sahih yang antara lain dikatakan, \"Barang siapa yang diinterogasi di dalam penghisabannya, niscaya dia bakal binasa atau celaka.\" Kemudian setelah kepada orang mukmin itu ditampakkan amal perbuatannya, lalu Allah memaafkannya.",[["فَسَوْفَ","Then soon"],["يُحَاسَبُ","his account will be taken"],["حِسَابًۭا","an account"],["يَسِيرًۭا","easy"]]],"5893":["(Dan dia akan kembali kepada kaumnya) di dalam surga (dengan gembira) karena mendapatkan ampunan-Nya.",[["وَيَنقَلِبُ","And he will return"],["إِلَىٰٓ","to"],["أَهْلِهِۦ","his people"],["مَسْرُورًۭا","happily"]]],"5894":["(Adapun orang yang diberikan kitabnya dari belakang punggungnya) dia adalah orang kafir; tangan kanannya diikat dengan belenggu dijadikan satu dengan kepala, kemudian tangan kirinya ditekuk ke belakang berada di punggungnya, maka dengan tangan kirinya itulah ia mengambil kitab catatan amalnya.",[["وَأَمَّا","But as for"],["مَنْ","(him) who"],["أُوتِىَ","is given"],["كِتَـٰبَهُۥ","his record"],["وَرَآءَ","behind"],["ظَهْرِهِۦ","his back"]]],"5895":["(Maka dia akan berteriak) yakni sewaktu dia melihat apa yang tercatat di dalam kitab amalnya (\"Celakalah aku\") ia berseru meratapi kebinasaannya, dengan ucapannya, \"Celakalah aku.\"",[["فَسَوْفَ","Then soon"],["يَدْعُوا۟","he will call"],["ثُبُورًۭا","(for) destruction"]]],"5896":["(Dan dia akan masuk ke dalam neraka Sa'iir) yakni neraka yang apinya sangat besar. Menurut suatu qiraat lafal Yashlaa dibaca Yushallaa.",[["وَيَصْلَىٰ","And he will burn"],["سَعِيرًا","(in) a Blaze"]]],"5897":["(Sesungguhnya dia dahulu di kalangan kaumnya) maksudnya kaum kerabatnya sewaktu di dunia (selalu bergembira) yakni sombong karena selalu mengikuti hawa nafsunya.",[["إِنَّهُۥ","Indeed, he"],["كَانَ","had been"],["فِىٓ","among"],["أَهْلِهِۦ","his people"],["مَسْرُورًا","happy"]]],"5898":["(Sesungguhnya dia menyangka bahwa dia) lafal An di sini adalah bentuk Takhfif dari Anna, sedangkan Isimnya tidak disebutkan, lengkapnya Annahuu; artinya bahwasanya dia (sekali-kali tidak akan kembali) tidak akan kembali kepada Rabbnya.",[["إِنَّهُۥ","Indeed, he"],["ظَنَّ","(had) thought"],["أَن","that"],["لَّن","never"],["يَحُورَ","he would return"]]],"5899":["(Yang benar) dia akan dikembalikan kepada-Nya (sesungguhnya Rabbnya selalu melihatnya) artinya mengetahui bahwa dia akan kembali kepada-Nya.",[["بَلَىٰٓ","Yes"],["إِنَّ","Indeed"],["رَبَّهُۥ","his Lord"],["كَانَ","was"],["بِهِۦ","of him"],["بَصِيرًۭا","All-Seer"]]],"5900":["(Maka sesungguhnya aku bersumpah) huruf Laa di sini adalah huruf Zaidah (dengan cahaya merah di waktu senja) yakni dengan nama mega merah yang berada di ufuk barat sesudah matahari terbenam.",[["فَلَآ","But nay"],["أُقْسِمُ","I swear"],["بِٱلشَّفَقِ","by the twilight glow"]]],"5901":["(Dan dengan malam dan apa yang diselubunginya) yakni semua yang ditutupinya termasuk segala jenis binatang dan makhluk lainnya.",[["وَٱلَّيْلِ","And the night"],["وَمَا","and what"],["وَسَقَ","it envelops"]]],"5902":["(Dan dengan bulan apabila jadi purnama) bila bentuknya membulat dan sinarnya tampak penuh, yang demikian itu terjadi di malam-malam yang cerah tak berawan.",[["وَٱلْقَمَرِ","And the moon"],["إِذَا","when"],["ٱتَّسَقَ","it becomes full"]]],"5903":["(Sesungguhnya kalian melalui) hai manusia. Bentuk asal lafal Latarkabunna adalah Latarkabuunanna, kemudian huruf Nun alamat Rafa'nya dibuang karena berturut-turutnya Nun, demikian pula huruf Wau alamat jamaknya, tetapi bukan karena 'illat bertemunya kedua huruf yang disukunkan, sehingga jadilah Latarkabunna (tingkat demi tingkat) fase demi fase; yaitu mulai dari mati lalu dihidupkan kembali, kemudian menyaksikan keadaan-keadaan di hari kiamat.",[["لَتَرْكَبُنَّ","You will surely embark"],["طَبَقًا","(to) stage"],["عَن","from"],["طَبَقٍۢ","stage"]]],"5904":["(Mengapa mereka) yakni orang-orang kafir itu (tidak mau beriman?) artinya apakah gerangan yang mencegah mereka hingga tidak mau beriman. Atau apakah yang menjadi alasan mereka sehingga tidak mau beriman, padahal bukti-bukti yang membimbing mereka untuk beriman sudah ada dan cukup?",[["فَمَا","So what"],["لَهُمْ","(is) for them"],["لَا","not"],["يُؤْمِنُونَ","they believe"]]],"5905":["(Dan) mengapakah mereka (apabila dibacakan kepada mereka Alquran, mereka tidak mau bersujud?) atau mengapa mereka tidak mau tunduk, seumpamanya mereka beriman kepada Alquran, karena mengingat kemukjizatan yang terkandung di dalamnya.",[["وَإِذَا","And when"],["قُرِئَ","is recited"],["عَلَيْهِمُ","to them"],["ٱلْقُرْءَانُ","the Quran"],["لَا","not"],["يَسْجُدُونَ ۩","they prostrate"]]],"5906":["(Bahkan orang-orang kafir itu mendustakan) adanya hari berbangkit dan lain-lainnya.",[["بَلِ","Nay"],["ٱلَّذِينَ","Those who"],["كَفَرُوا۟","disbelieved"],["يُكَذِّبُونَ","deny"]]],"5907":["(Padahal Allah mengetahui apa yang mereka kumpulkan) di dalam catatan amal perbuatan mereka; yaitu berupa kekafiran, kedustaan dan amal-amal buruk lainnya.",[["وَٱللَّهُ","And Allah"],["أَعْلَمُ","(is) most knowing"],["بِمَا","of what"],["يُوعُونَ","they keep within themselves"]]],"5908":["(Maka beri kabar gembiralah mereka) beritakanlah kepada mereka (dengan azab yang pedih) atau siksaan yang menyakitkan.",[["فَبَشِّرْهُم","so give them tidings"],["بِعَذَابٍ","of a punishment"],["أَلِيمٍ","painful"]]],"5909":["(Kecuali) tetapi (orang-orang yang beriman dan mengerjakan amal-amal yang saleh, bagi mereka pahala yang tidak putus-putusnya) yakni pahala mereka tidak akan terputus dan tidak akan dikurangi serta tidak akan disebut-sebutkan sekalipun sangat banyak dan berlimpah ruah untuk selama-lamanya.",[["إِلَّا","Except"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["لَهُمْ","For them"],["أَجْرٌ","(is) a reward"],["غَيْرُ","never"],["مَمْنُونٍۭ","ending"]]],"5910":["(Demi langit yang mempunyai gugusan bintang) yakni bintang-bintang yang dua belas gugusan, sebagaimana yang telah dijelaskan di dalam surah Al-Furqaan.",[["وَٱلسَّمَآءِ","By the sky"],["ذَاتِ","containing"],["ٱلْبُرُوجِ","the constellations"]]],"5911":["(Dan demi hari yang dijanjikan) yaitu hari kiamat.",[["وَٱلْيَوْمِ","And the Day"],["ٱلْمَوْعُودِ","Promised"]]],"5912":["(Dan demi yang menyaksikan) hari Jumat (dan yang disaksikan) yakni hari Arafah. Demikianlah menurut penafsiran hadis tentang tiga perkara tersebut; yang pertama adalah hari yang telah dijanjikan, dan yang kedua hari Jumat menyaksikan amal perbuatan yang dikerjakan pada hari itu, serta yang ketiga hari Arafah disaksikan oleh manusia dan para malaikat. Sedangkan yang menjadi Jawab Qasam kalimat permulaannya tidak disebutkan, yaitu, \"Sesungguhnya.\"",[["وَشَاهِدٍۢ","And (the) witness"],["وَمَشْهُودٍۢ","and what is witnessed"]]],"5913":["(Telah dibinasakan) telah dilaknat (orang-orang yang memiliki Ukhdud) artinya orang-orang yang menggali parit.",[["قُتِلَ","Destroyed were"],["أَصْحَـٰبُ","(the) companions"],["ٱلْأُخْدُودِ","(of) the pit"]]],"5914":["(Yaitu api) lafal An-Naari berkedudukan sebagai Badal Isytimal dari lafal Al-Ukhduud (yang dinyalakan) dengan kayu bakar.",[["ٱلنَّارِ","(Of) the fire"],["ذَاتِ","full"],["ٱلْوَقُودِ","(of) the fuel"]]],"5915":["(Ketika mereka berada di sekitarnya) yaitu berada di sekitar tepi parit-parit itu seraya di atas kursi-kursi (mereka duduk.)",[["إِذْ","When"],["هُمْ","they"],["عَلَيْهَا","by it"],["قُعُودٌۭ","(were) sitting"]]],"5916":["(Sedangkan mereka terhadap apa yang mereka perbuat terhadap orang-orang yang beriman) kepada Allah, menyiksa mereka dengan cara melemparkan mereka ke dalam parit yang penuh dengan api itu, jika mereka tidak mau kembali murtad dari imannya (menyaksikan) artinya hadir menyaksikan penyiksaan itu. Menurut suatu riwayat, bahwasanya Allah menyelamatkan orang-orang yang beriman yang dilemparkan ke dalam parit berapi itu, yaitu dengan mencabut nyawa mereka terlebih dahulu sebelum mereka jatuh ke dalam api. Kemudian api itu keluar dari dalam parit dan membakar orang-orang yang berada di sekitarnya, sehingga mereka yang menyaksikan penyiksaan itu mati terbakar.",[["وَهُمْ","And they"],["عَلَىٰ","over"],["مَا","what"],["يَفْعَلُونَ","they were doing"],["بِٱلْمُؤْمِنِينَ","to the believers"],["شُهُودٌۭ","witnesses"]]],"5917":["(Dan mereka tidak menyiksa orang-orang mukmin itu melainkan karena orang-orang mukmin itu beriman kepada Allah Yang Maha Perkasa) di dalam kerajaan-Nya. (lagi Maha Terpuji) lafal Al-Hamiid bermakna Al-Mahmuud, artinya Maha Terpuji.",[["وَمَا","And not"],["نَقَمُوا۟","they resented"],["مِنْهُمْ","[of] them"],["إِلَّآ","except"],["أَن","that"],["يُؤْمِنُوا۟","they believed"],["بِٱللَّهِ","in Allah"],["ٱلْعَزِيزِ","the All-Mighty"],["ٱلْحَمِيدِ","the Praiseworthy"]]],"5918":["(Yang mempunyai kerajaan langit dan bumi; dan Allah Maha Menyaksikan segala sesuatu) yakni Dia menyaksikan, bahwa tiadalah orang-orang kafir itu ingkar kepada orang-orang yang beriman melainkan karena orang-orang yang beriman itu beriman kepada Allah.",[["ٱلَّذِى","The One Who"],["لَهُۥ","for Him"],["مُلْكُ","(is) the dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["وَٱللَّهُ","and Allah"],["عَلَىٰ","on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["شَهِيدٌ","(is) a Witness"]]],"5919":["(Sesungguhnya orang-orang yang mendatangkan cobaan kepada orang-orang yang mukmin laki-laki dan perempuan) yaitu dengan cara membakar mereka hidup-hidup (kemudian mereka tidak bertobat, maka bagi mereka azab Jahanam) disebabkan kekafiran mereka (dan bagi mereka azab pembakaran) sebagai pembalasan dari pembakaran mereka terhadap orang-orang yang beriman, pembalasan itu kelak akan ditimpakan kepada mereka di akhirat. Tetapi menurut suatu pendapat bahwa azab tersebut terjadi di dunia, umpamanya api tersebut keluar dari paritnya dan langsung mengejar dan membakar mereka, sebagaimana keterangan yang disebutkan di atas.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["فَتَنُوا۟","persecuted"],["ٱلْمُؤْمِنِينَ","the believing men"],["وَٱلْمُؤْمِنَـٰتِ","and the believing women"],["ثُمَّ","then"],["لَمْ","not"],["يَتُوبُوا۟","they repented"],["فَلَهُمْ","then for them"],["عَذَابُ","(is the) punishment"],["جَهَنَّمَ","(of) Hell"],["وَلَهُمْ","and for them"],["عَذَابُ","(is the) punishment"],["ٱلْحَرِيقِ","(of) the Burning Fire"]]],"5920":["(Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal yang saleh, bagi mereka surga yang mengalir di bawahnya sungai-sungai itulah keberuntungan yang besar.)",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","the righteous deeds"],["لَهُمْ","for them"],["جَنَّـٰتٌۭ","(will be) Gardens"],["تَجْرِى","flow"],["مِن","from"],["تَحْتِهَا","underneath it"],["ٱلْأَنْهَـٰرُ ۚ","the rivers"],["ذَٰلِكَ","That"],["ٱلْفَوْزُ","(is) the success"],["ٱلْكَبِيرُ","the great"]]],"5921":["(Sesungguhnya Azab Rabbmu) terhadap orang-orang kafir (benar-benar keras) sesuai dengan kehendak-Nya.",[["إِنَّ","Indeed"],["بَطْشَ","(the) Grip"],["رَبِّكَ","(of) your Lord"],["لَشَدِيدٌ","(is) surely strong"]]],"5922":["(Sesungguhnya Dialah yang memulai) penciptaan makhluk (dan yang mengembalikan) makhluk menjadi hidup kembali, maka tiada sesuatu pun yang dapat menghalang-halangi apa yang dikehendaki-Nya.",[["إِنَّهُۥ","Indeed He"],["هُوَ","He"],["يُبْدِئُ","originates"],["وَيُعِيدُ","and repeats"]]],"5923":["(Dan Dialah Yang Maha Pengampun) kepada orang-orang mukmin yang berbuat dosa (lagi Maha Pengasih) yakni Maha Belas Kasih kepada kekasih-kekasih-Nya dengan memberikan karamah kepada mereka.",[["وَهُوَ","And He"],["ٱلْغَفُورُ","(is) the Oft-Forgiving"],["ٱلْوَدُودُ","the Most Loving"]]],"5924":["(Yang mempunyai Arasy) yakni Yang menciptakan dan Yang memilikinya (lagi Maha Agung) dibaca Rafa' yakni Al-Majiidu, artinya Yang berhak menyandang kesempurnaan sifat-sifat Yang Maha Tinggi.",[["ذُو","Owner (of)"],["ٱلْعَرْشِ","the Throne"],["ٱلْمَجِيدُ","the Glorious"]]],"5925":["(Maha Kuasa berbuat apa yang dikehendaki-Nya) artinya tiada sesuatu pun yang dapat menghalang-halangi kehendak-Nya.",[["فَعَّالٌۭ","Doer"],["لِّمَا","of what"],["يُرِيدُ","He intends"]]],"5926":["(Sudahkah datang kepadamu) hai Muhammad (berita tentang kaum-kaum penentang.)",[["هَلْ","Has"],["أَتَىٰكَ","come to you"],["حَدِيثُ","(the) story"],["ٱلْجُنُودِ","(of) the hosts"]]],"5927":["(Yaitu kaum Fir'aun dan kaum Tsamud) kedua lafal ini menjadi Badal dari lafal Al-Junuud; dan di sini cukup hanya dengan menyebut nama Firaun saja tanpa menyebut bala tentaranya; adapun Tsamud adalah nama suatu kaum. Kisahnya ialah bahwasanya mereka dibinasakan karena kekafiran mereka. Hal ini merupakan peringatan bagi orang-orang yang ingkar kepada Nabi saw. dan Alquran, dimaksud supaya mereka mengambil pelajaran dari kisah tersebut.",[["فِرْعَوْنَ","Firaun"],["وَثَمُودَ","and Thamud"]]],"5928":["(Akan tetapi orang-orang kafir selalu mendustakan) hal-hal yang telah disebutkan tadi.",[["بَلِ","Nay"],["ٱلَّذِينَ","Those who"],["كَفَرُوا۟","disbelieve"],["فِى","(are) in"],["تَكْذِيبٍۢ","denial"]]],"5929":["(Padahal Allah mengepung mereka dari belakang mereka) tiada seseorang pun yang dapat menyelamatkan dan menjaga mereka dari azab-Nya.",[["وَٱللَّهُ","But Allah"],["مِن","from"],["وَرَآئِهِم","behind them"],["مُّحِيطٌۢ","encompasses"]]],"5930":["(Bahkan yang didustakan mereka itu ialah Alquran yang mulia) atau yang agung.",[["بَلْ","Nay"],["هُوَ","It"],["قُرْءَانٌۭ","(is) a Quran"],["مَّجِيدٌۭ","Glorious"]]],"5931":["(Yang dalam Lauh) berada di atas langit yang ketujuh (terpelihara) dari ulah setan-setan dan dari sesuatu perubahan. Panjang Lohmahfuz itu sama dengan panjangnya langit dan bumi, sedangkan lebarnya ialah sama dengan jarak antara timur dan barat; terbuat dari intan yang putih bersih. Demikianlah menurut pendapat yang telah dikemukakan oleh Ibnu Abbas r.a.",[["فِى","In"],["لَوْحٍۢ","a Tablet"],["مَّحْفُوظٍۭ","Guarded"]]],"5932":["(Demi langit dan yang datang pada malam hari) lafal Ath-Thaariq pada asalnya berarti segala sesuatu yang datang pada malam hari, antara lain ialah bintang-bintang, karena bintang-bintang baru muncul bila malam tiba.",[["وَٱلسَّمَآءِ","By the sky"],["وَٱلطَّارِقِ","and the night comer"]]],"5933":["(Tahukah kamu) artinya apakah kamu mengetahui (apakah yang datang pada malam hari itu?) lafal Maa adalah Mubtada sedangkan lafal Ath-Thaariq adalah Khabarnya, kedua lafal tersebut berkedudukan menjadi Maf'ul kedua dari lafal Adraa. Lafal Maa yang kedua juga menjadi Khabar dari lafal Maa yang pertama, di dalamnya terkandung makna yang menjelaskan kedudukan Ath-Thaariq yang agung itu; selanjutnya pengertian Ath-Thaariq dijelaskan oleh firman berikutnya.",[["وَمَآ","And what"],["أَدْرَىٰكَ","can make you know"],["مَا","what"],["ٱلطَّارِقُ","the night comer (is)"]]],"5934":["(Yaitu bintang) yakni bintang Tsurayya, atau semua bintang (yang cahayanya menembus) kegelapan malam. Yang menjadi Jawab Qasam ialah:",[["ٱلنَّجْمُ","(It is) the star"],["ٱلثَّاقِبُ","the piercing"]]],"5935":["(Tidak ada suatu jiwa pun melainkan ada penjaganya) jika dibaca Lamaa tanpa memakai Tasydid, berarti huruf Maa adalah huruf Zaidah, dan In adalah bentuk Takhfif dari Inna sedangkan Isimnya tidak disebutkan, dan huruf Lamnya adalah huruf Fariqah. Artinya sesungguhnya setiap diri itu ada penjaganya. Jika dibaca Lammaa dengan memakai Tasydid, berarti In adalah bermakna Nafi, sedangkan Lammaa bermakna Illaa; artinya tiada suatu jiwa pun melainkan ada penjaganya, yakni penjaga yang terdiri dari malaikat; malaikat penjaga itu bertugas untuk mencatat amal baik dan amal buruknya.",[["إِن","Not"],["كُلُّ","(is) every"],["نَفْسٍۢ","soul"],["لَّمَّا","but"],["عَلَيْهَا","over it"],["حَافِظٌۭ","(is) a protector"]]],"5936":["(Maka hendaklah manusia memperhatikan) dengan perhatian yang dibarengi dengan mempelajarinya (dari apakah dia diciptakan?) artinya berasal dari apakah dia tercipta?",[["فَلْيَنظُرِ","So let see"],["ٱلْإِنسَـٰنُ","man"],["مِمَّ","from what"],["خُلِقَ","he is created"]]],"5937":["(Dia diciptakan dari air yang terpancar) yakni yang dipancarkan oleh laki-laki ke dalam rahim wanita.",[["خُلِقَ","He is created"],["مِن","from"],["مَّآءٍۢ","a water"],["دَافِقٍۢ","ejected"]]],"5938":["(Yang keluar dari antara tulang sulbi) laki-laki (dan tulang dada) perempuan.",[["يَخْرُجُ","Coming forth"],["مِنۢ","from"],["بَيْنِ","between"],["ٱلصُّلْبِ","the backbone"],["وَٱلتَّرَآئِبِ","and the ribs"]]],"5939":["(Sesungguhnya Dia) yakni Allah swt. (untuk mengembalikannya) atau menghidupkan kembali manusia setelah mati (benar-benar kuasa) maka apabila manusia itu benar-benar memperhatikan asal mula kejadiannya, niscaya dia akan menyimpulkan, bahwasanya Yang Maha Kuasa menciptakan demikian, berkuasa pula untuk menghidupkannya kembali.",[["إِنَّهُۥ","Indeed, He"],["عَلَىٰ","to"],["رَجْعِهِۦ","return him"],["لَقَادِرٌۭ","(is) Able"]]],"5940":["(Pada hari ditampakkan) maksudnya, diuji dan dibuka (segala rahasia) yaitu hal-hal yang terkandung di dalam kalbu berupa keyakinan-keyakinan dan niat-niat.",[["يَوْمَ","(The) Day"],["تُبْلَى","will be tested"],["ٱلسَّرَآئِرُ","the secrets"]]],"5941":["(Maka sekali-kali tidak ada bagi manusia itu) yaitu bagi orang yang tidak mempercayai adanya hari berbangkit (suatu kekuatan pun) yang dapat melindunginya dari azab (dan tidak pula seorang penolong pun) yang dapat menolak azab Allah.",[["فَمَا","Then not"],["لَهُۥ","(is) for him"],["مِن","any"],["قُوَّةٍۢ","power"],["وَلَا","and not"],["نَاصِرٍۢ","any helper"]]],"5942":["(Demi langit yang mengandung hujan) hujan dinamakan Ar-Raj'u karena berulang datang pada musimnya.",[["وَٱلسَّمَآءِ","By the sky"],["ذَاتِ","which"],["ٱلرَّجْعِ","returns"]]],"5943":["(Dan demi bumi yang mempunyai tumbuh-tumbuhan) maksudnya retak-retak karena daripadanya keluar tumbuh-tumbuhan.",[["وَٱلْأَرْضِ","And the earth"],["ذَاتِ","which"],["ٱلصَّدْعِ","cracks open"]]],"5944":["(Sesungguhnya Alquran itu) yakni wahyu Alquran (benar-benar firman yang memutuskan) yang memisahkan antara perkara yang hak dan perkara yang batil.",[["إِنَّهُۥ","Indeed, it"],["لَقَوْلٌۭ","(is) surely a Word"],["فَصْلٌۭ","decisive"]]],"5945":["(Dan sekali-kali bukanlah dia senda gurau) atau mainan dan kebatilan.",[["وَمَا","And not"],["هُوَ","it"],["بِٱلْهَزْلِ","(is) for amusement"]]],"5946":["(Sesungguhnya mereka) yakni orang-orang kafir (merencanakan tipu daya yang jahat dengan sebenar-benarnya) yaitu mereka melakukan tipu daya yang jahat terhadap diri Nabi saw.",[["إِنَّهُمْ","Indeed, they"],["يَكِيدُونَ","are plotting"],["كَيْدًۭا","a plot"]]],"5947":["(Dan Aku pun membuat rencana pula dengan sebenar-benarnya) maksudnya, Aku biarkan mereka bersenang-senang sesuka hatinya, tanpa mereka sadari bahwa hal itu merupakan Istidraj dari Aku, yang kelak Aku akan mengazab mereka dengan sepedih-pedihnya.",[["وَأَكِيدُ","But I am planning"],["كَيْدًۭا","a plan"]]],"5948":["(Karena itu beri tangguhlah) hai Muhammad (orang-orang kafir itu, beri tangguhlah mereka) lafal Amhilhum mengukuhkan makna yang terkandung di dalam lafal Famahhil; dianggap baik karena lafalnya berbeda dengan yang pertama, artinya tangguhkanlah mereka itu (barang sebentar) dalam waktu yang singkat. Lafal Ruwaidan adalah mashdar yang mengukuhkan makna 'Amilnya. Ia adalah bentuk Tashghir dari lafal Rawdun atau Arwaadun yang mengandung makna Tarkhiim. Dan Allah swt. benar-benar mengazab orang-orang kafir itu dalam perang Badar. Akan tetapi ayat penangguhan ini dinasakh oleh ayat perang, yakni Allah memerintahkan Nabi-Nya supaya berjihad memerangi mereka.",[["فَمَهِّلِ","So give respite"],["ٱلْكَـٰفِرِينَ","(to) the disbelievers"],["أَمْهِلْهُمْ","Give respite to them "],["رُوَيْدًۢا","little"]]],"5949":["(Sucikanlah nama Rabbmu) maksudnya sucikanlah Dia dari sifat-sifat yang tidak layak bagi-Nya lafal Ismu adalah lafal Za'id (Yang Maha Tinggi) lafal Al-A'laa berkedudukan sebagai kata sifat bagi lafal Rabbika.",[["سَبِّحِ","Glorify"],["ٱسْمَ","(the) name"],["رَبِّكَ","(of) your Lord"],["ٱلْأَعْلَى","the Most High"]]],"5950":["(Yang menciptakan lalu menyempurnakan) ciptaan-Nya, yakni Dia menjadikan makhluk-Nya itu seimbang semua bagian-bagiannya dan tidak pincang atau berbeda-beda.",[["ٱلَّذِى","The One Who"],["خَلَقَ","created"],["فَسَوَّىٰ","then proportioned"]]],"5951":["(Dan Yang menentukan) apa yang dikehendaki-Nya (dan Yang memberi petunjuk) kepada apa yang telah ditentukan-Nya berupa amal kebaikan dan amal keburukan.",[["وَٱلَّذِى","And the One Who"],["قَدَّرَ","measured"],["فَهَدَىٰ","then guided"]]],"5952":["(Dan Yang mengeluarkan rumput-rumputan) atau Yang menumbuhkan rumput-rumputan.",[["وَٱلَّذِىٓ","And the One Who"],["أَخْرَجَ","brings forth"],["ٱلْمَرْعَىٰ","the pasture"]]],"5953":["(Lalu dijadikan-Nya) sesudah rumput-rumputan itu hijau (kering) yaitu menjadi layu dan kering (kehitam-hitaman) kehitam-hitaman karena kering.",[["فَجَعَلَهُۥ","And then makes it"],["غُثَآءً","stubble"],["أَحْوَىٰ","dark"]]],"5954":["(Kami akan membacakan kepadamu) Alquran (maka kamu tidak akan lupa) apa yang kamu bacakan itu.",[["سَنُقْرِئُكَ","We will make you recite"],["فَلَا","so not"],["تَنسَىٰٓ","you will forget"]]],"5955":["(Kecuali kalau Allah menghendaki) kamu melupakannya karena bacaan dan hukumnya telah dinasakh. Sesungguhnya Nabi saw. selalu mengeraskan suara bacaannya mengikuti bacaan malaikat Jibril karena takut lupa. Seolah-olah dikatakan kepadanya, janganlah kamu tergesa-gesa membacanya, karena sesungguhnya kamu tidak akan lupa, karena itu janganlah kamu merepotkan dirimu dengan mengeraskan suaramu sewaktu kamu membacakannya. (Sesungguhnya Dia) yakni Allah swt. (mengetahui yang terang) maksudnya perkataan dan perbuatan yang terang-terangan (dan yang tersembunyi) dari keduanya.",[["إِلَّا","Except"],["مَا","what"],["شَآءَ","wills"],["ٱللَّهُ ۚ","Allah"],["إِنَّهُۥ","Indeed, He"],["يَعْلَمُ","knows"],["ٱلْجَهْرَ","the manifest"],["وَمَا","and what"],["يَخْفَىٰ","is hidden"]]],"5956":["(Dan Kami akan memudahkan kamu untuk menempuh jalan yang mudah) yakni syariat yang mudah, yaitu agama Islam.",[["وَنُيَسِّرُكَ","And We will ease you"],["لِلْيُسْرَىٰ","to the ease"]]],"5957":["(Oleh sebab itu berikanlah peringatan) dengan Alquran (karena peringatan itu bermanfaat) maksudnya memberikan peringatan dengan hal-hal yang telah disebutkan pada firman-Nya, \"Sayadzdzakkaru,\" sekalipun peringatan itu tidak bermanfaat bagi sebagian di antara mereka, tetapi peringatan itu pasti bermanfaat bagi sebagian yang lainnya.",[["فَذَكِّرْ","So remind"],["إِن","if"],["نَّفَعَتِ","benefits"],["ٱلذِّكْرَىٰ","the reminder"]]],"5958":["(Akan mendapat peringatan) dan pelajaran dari peringatan itu (orang yang takut) kepada Allah swt. sebagaimana yang disebutkan dalam ayat yang lain yaitu, firman-Nya, \"Maka beri peringatanlah dengan Alquran orang yang takut kepada ancaman-Ku.\" (Q.S. Qaaf, 45)",[["سَيَذَّكَّرُ","He will pay heed "],["مَن","(one) who"],["يَخْشَىٰ","fears (Allah)"]]],"5959":["(Akan menjauhinya) yakni peringatan itu akan ditinggalkan dan diabaikan begitu saja (orang yang celaka) yakni orang yang kafir.",[["وَيَتَجَنَّبُهَا","And will avoid it"],["ٱلْأَشْقَى","the wretched one"]]],"5960":["(Yaitu orang yang akan memasuki api yang besar) yaitu api neraka; dan api dunia dinamakan api kecil.",[["ٱلَّذِى","The one who"],["يَصْلَى","will burn"],["ٱلنَّارَ","(in) the Fire"],["ٱلْكُبْرَىٰ","[the] great"]]],"5961":["(Kemudian dia tidak mati di dalamnya) hingga ia dapat beristirahat (dan tidak pula hidup) dengan kehidupan yang menyenangkan.",[["ثُمَّ","Then"],["لَا","not"],["يَمُوتُ","he will die"],["فِيهَا","therein"],["وَلَا","and not"],["يَحْيَىٰ","will live"]]],"5962":["(Sesungguhnya beruntunglah) atau mendapat keberuntungan (orang yang membersihkan diri) dengan cara beriman.",[["قَدْ","Certainly"],["أَفْلَحَ","has succeeded"],["مَن","(one) who"],["تَزَكَّىٰ","purifies (himself)"]]],"5963":["(Dan dia ingat nama Rabbnya) seraya mengagungkan-Nya (lalu dia salat) maksudnya, mengerjakan salat lima waktu, hal ini merupakan perkara akhirat; akan tetapi orang-orang kafir Mekah berpaling daripadanya.",[["وَذَكَرَ","And remembers"],["ٱسْمَ","(the) name"],["رَبِّهِۦ","(of) his Lord"],["فَصَلَّىٰ","and prays"]]],"5964":["(Tetapi kamu sekalian lebih memilih) dapat dibaca Tu'tsiruuna dan Yu'tsiruuna (kehidupan duniawi) daripada kehidupan ukhrawi.",[["بَلْ","Nay"],["تُؤْثِرُونَ","You prefer"],["ٱلْحَيَوٰةَ","the life"],["ٱلدُّنْيَا","(of) the world"]]],"5965":["(Sedangkan kehidupan akhirat) yang di dalamnya terdapat surga (adalah lebih baik dan lebih kekal.)",[["وَٱلْـَٔاخِرَةُ","While the Hereafter"],["خَيْرٌۭ","(is) better"],["وَأَبْقَىٰٓ","and everlasting"]]],"5966":["(Sesungguhnya ini) maksudnya keberuntungan orang-orang yang membersihkan dirinya dengan beriman dan bahwa kehidupan akhirat itu lebih baik (benar-benar terdapat dalam kitab-kitab terdahulu) yang diturunkan sebelum Alquran.",[["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَفِى","surely (is) in"],["ٱلصُّحُفِ","the Scriptures"],["ٱلْأُولَىٰ","[the] former"]]],"5967":["(Yaitu Kitab-kitab Ibrahim dan Musa) sepuluh shuhuf bagi Nabi Ibrahim, dan satu shuhuf bagi Nabi Musa, yaitu kitab Taurat.",[["صُحُفِ","(The) Scriptures"],["إِبْرَٰهِيمَ","(of) Ibrahim"],["وَمُوسَىٰ","and Musa"]]],"5968":["(Apakah) telah (datang kepadamu berita hari kiamat) hari kiamat dinamakan hari yang menutupi karena pada hari itu semua makhluk diselimuti oleh kengerian-kengeriannya.",[["هَلْ","Has"],["أَتَىٰكَ","(there) come to you"],["حَدِيثُ","(the) news"],["ٱلْغَـٰشِيَةِ","(of) the Overwhelming"]]],"5969":["(Banyak muka pada hari itu) yang dimaksud dengan ungkapan lafal Wujuuh atau muka adalah orang-orangnya, demikian lafal yang sama sesudahnya nanti (tunduk) terhina.",[["وُجُوهٌۭ","Faces"],["يَوْمَئِذٍ","that Day"],["خَـٰشِعَةٌ","(will be) humbled"]]],"5970":["(Pekerja keras lagi kepayahan) maksudnya dalam keadaan lelah dan payah karena diikat dengan rantai dan belenggu.",[["عَامِلَةٌۭ","Laboring"],["نَّاصِبَةٌۭ","exhausted"]]],"5971":["(Memasuki) dapat dibaca Tashlaa dan Tushlaa, jika dibaca Tushlaa artinya dimasukkan ke dalam (api yang sangat panas.)",[["تَصْلَىٰ","They will burn"],["نَارًا","(in) a Fire"],["حَامِيَةًۭ","intensely hot"]]],"5972":["(Diberi minum dari sumber yang sangat panas) atau dengan air yang sangat panas.",[["تُسْقَىٰ","They will be given to drink"],["مِنْ","from"],["عَيْنٍ","a spring"],["ءَانِيَةٍۢ","boiling"]]],"5973":["(Mereka tiada memperoleh makanan selain dari pohon yang berduri) Dharii' adalah sejenis pohon yang berduri, hewan ternak pun tidak mau memakannya karena duri itu keras lagi kotor.",[["لَّيْسَ","Not is"],["لَهُمْ","for them"],["طَعَامٌ","food"],["إِلَّا","except"],["مِن","from"],["ضَرِيعٍۢ","a bitter thorny plant"]]],"5974":["(Yang tidak menggemukkan dan tidak pula menghilangkan lapar.)",[["لَّا","Not"],["يُسْمِنُ","it nourishes"],["وَلَا","and not"],["يُغْنِى","it avails"],["مِن","from"],["جُوعٍۢ","hunger"]]],"5975":["(Banyak muka pada hari itu berseri-seri) atau tampak cerah dan cantik.",[["وُجُوهٌۭ","Faces"],["يَوْمَئِذٍۢ","that Day"],["نَّاعِمَةٌۭ","(will be) joyful"]]],"5976":["(Karena usahanya) sewaktu di dunia yaitu karena ketaatannya (mereka merasa senang) di alam akhirat, yaitu sewaktu mereka melihat pahalanya.",[["لِّسَعْيِهَا","With their effort"],["رَاضِيَةٌۭ","satisfied"]]],"5977":["(Dalam surga yang tinggi) secara nyata dan dapat mereka rasakan.",[["فِى","In"],["جَنَّةٍ","a garden"],["عَالِيَةٍۢ","elevated"]]],"5978":["(Tidak kamu dengar) dapat dibaca Tasma'u dan Yasma'u, jika Yasma'u artinya tidak dia dengar (di dalamnya perkataan yang tak berguna) tiada seorang yang berkata melantur yang tidak ada gunanya.",[["لَّا","Not"],["تَسْمَعُ","they will hear"],["فِيهَا","therein"],["لَـٰغِيَةًۭ","vain talk"]]],"5979":["(Di dalamnya ada mata air yang mengalir) lafal `Ainun sekalipun bentuknya Mufrad tetapi maknanya jamak.",[["فِيهَا","Therein"],["عَيْنٌۭ","(will be) a spring"],["جَارِيَةٌۭ","flowing"]]],"5980":["(Di dalamnya ada takhta-takhta yang ditinggikan) yaitu tempat kedudukan dan derajatnya ditinggikan.",[["فِيهَا","Therein"],["سُرُرٌۭ","(will be) thrones"],["مَّرْفُوعَةٌۭ","raised high"]]],"5981":["(Dan gelas-gelas) yakni tempat-tempat untuk minum tanpa gagang (yang terletak) di setiap tepi mata air yang disediakan untuk peminum-peminumnya.",[["وَأَكْوَابٌۭ","And cups"],["مَّوْضُوعَةٌۭ","put in place"]]],"5982":["(Dan bantal-bantal) untuk bersandar (yang tersusun) atau dalam keadaan tersusun untuk tempat bersandar.",[["وَنَمَارِقُ","And cushions"],["مَصْفُوفَةٌۭ","lined up"]]],"5983":["(Dan permadani-permadani) yaitu permadani yang empuk lagi tebal (yang terhampar) dalam keadaan terbentang.",[["وَزَرَابِىُّ","And carpets"],["مَبْثُوثَةٌ","spread out"]]],"5984":["(Maka apakah mereka tidak memperhatikan) dengan perhatian yang dibarengi keinginan mengambil pelajaran; yang dimaksud adalah orang-orang kafir Mekah (unta bagaimana dia diciptakan?)",[["أَفَلَا","Then do not"],["يَنظُرُونَ","they look"],["إِلَى","towards"],["ٱلْإِبِلِ","the camels"],["كَيْفَ","how"],["خُلِقَتْ","they are created"]]],"5985":["(Dan langit, bagaimanakah ia ditinggikan?)",[["وَإِلَى","And towards"],["ٱلسَّمَآءِ","the sky"],["كَيْفَ","how"],["رُفِعَتْ","it is raised"]]],"5986":["(Dan gunung-gunung, bagaimana ia dipancangkan?)",[["وَإِلَى","And towards"],["ٱلْجِبَالِ","the mountains"],["كَيْفَ","how"],["نُصِبَتْ","they are fixed"]]],"5987":["(Dan bumi bagaimana ia dihamparkan?) maksudnya dijadikan sehingga terhampar. Melalui hal-hal tersebutlah mereka mengambil kesimpulan tentang kekuasaan Allah swt. dan keesaan-Nya. Pembahasan ini dimulai dengan menyebut unta, karena unta adalah binatang ternak yang paling mereka kenal daripada yang lain-lainnya. Firman Allah \"Suthihat\" jelas menunjukkan bahwa bumi itu rata bentuknya. Pendapat inilah yang dianut oleh para ulama Syara'. Jadi bentuk bumi bukanlah bulat seperti bola sebagaimana yang dikatakan oleh para ahli ilmu konstruksi. Masalah ini sama sekali tidak ada sangkut-pautnya dengan salah satu rukun syariat.",[["وَإِلَى","And towards"],["ٱلْأَرْضِ","the earth"],["كَيْفَ","how"],["سُطِحَتْ","it is spread out"]]],"5988":["(Maka berilah peringatan) berilah mereka peringatan yang mengingatkan mereka kepada nikmat-nikmat Allah dan bukti-bukti yang menunjukkan keesaan-Nya (karena sesungguhnya kamu hanyalah orang yang memberi peringatan.)",[["فَذَكِّرْ","So remind"],["إِنَّمَآ","only"],["أَنتَ","you"],["مُذَكِّرٌۭ","(are) a reminder"]]],"5989":["(Kamu bukanlah orang yang berkuasa atas mereka) menurut suatu qiraat lafal Mushaithirin dibaca Musaithirin yakni dengan memakai huruf Sin bukan Shad, artinya menguasai mereka. Ayat ini diturunkan sebelum ada perintah berjihad.",[["لَّسْتَ","You are not"],["عَلَيْهِم","over them"],["بِمُصَيْطِرٍ","a controller"]]],"5990":["(Kecuali) tetapi (orang yang berpaling) dari keimanan (dan kafir) kepada Alquran, artinya ingkar kepadanya.",[["إِلَّا","But"],["مَن","whoever"],["تَوَلَّىٰ","turns away"],["وَكَفَرَ","and disbelieves"]]],"5991":["(Maka Allah akan mengazabnya dengan azab yang besar) yaitu azab di akhirat dan azab di dunia dengan dibunuh dan ditawan.",[["فَيُعَذِّبُهُ","Then will punish him"],["ٱللَّهُ","Allah"],["ٱلْعَذَابَ","(with) the punishment"],["ٱلْأَكْبَرَ","greatest"]]],"5992":["(Sesungguhnya kepada Kamilah kembali mereka) maksudnya mereka akan kembali kepada-Nya sesudah mati.",[["إِنَّ","Indeed"],["إِلَيْنَآ","to Us"],["إِيَابَهُمْ","(will be) their return"]]],"5993":["(Kemudian sesungguhnya kewajiban Kamilah menghisab mereka) atau memberikan balasan kepada mereka, Kami sama sekali tidak akan membiarkan mereka begitu saja, mereka pasti Kami hisab.",[["ثُمَّ","Then"],["إِنَّ","indeed"],["عَلَيْنَا","upon Us"],["حِسَابَهُم","(is) their account"]]],"5994":["(Demi fajar) yakni fajar yang terbit setiap hari.",[["وَٱلْفَجْرِ","By the dawn"]]],"5995":["(Dan malam yang sepuluh) maksudnya tanggal sepuluh bulan Zulhijah.",[["وَلَيَالٍ","And the nights"],["عَشْرٍۢ","ten"]]],"5996":["(Dan yang genap) atau tidak ganjil (dan yang ganjil) dapat dibaca Al-Watr dan Al-Witr, artinya ganjil.",[["وَٱلشَّفْعِ","And the even"],["وَٱلْوَتْرِ","and the odd"]]],"5997":["(Dan malam bila berlalu) bila datang dan pergi.",[["وَٱلَّيْلِ","And the night"],["إِذَا","when"],["يَسْرِ","it passes"]]],"5998":["(Pada yang demikian itu) yakni sumpah itu (terdapat sumpah bagi orang-orang yang berakal) Jawab dari Qasam tidak disebutkan yakni, sungguh kalian hai orang-orang kafir Mekah akan diazab.",[["هَلْ","Is"],["فِى","in"],["ذَٰلِكَ","that"],["قَسَمٌۭ","(not) an oath"],["لِّذِى","for those"],["حِجْرٍ","who understand"]]],"5999":["(Apakah kamu tidak memperhatikan) artinya tidak mengetahui hai Muhammad (bagaimana Rabbmu berbuat terhadap kaum 'Ad.)",[["أَلَمْ","Did not"],["تَرَ","you see"],["كَيْفَ","how"],["فَعَلَ","dealt"],["رَبُّكَ","your Lord"],["بِعَادٍ","with Aad"]]],"6000":["(Yaitu penduduk Iram) Iram adalah nama kaum 'Ad dahulu; lafal Iram dapat dianggap sebagai 'Athaf Bayan atau Badal tidak menerima Tanwin karena 'Illat 'Alamiyah dan Mu'annats (yang mempunyai tubuh-tubuh yang tinggi) atau mereka adalah orang-orang yang tinggi tubuhnya, tersebutlah yang paling tinggi di antara mereka mencapai empat ratus hasta.",[["إِرَمَ","Iram"],["ذَاتِ","possessors (of)"],["ٱلْعِمَادِ","lofty pillars"]]],"6001":["(Yang belum pernah diciptakan sepertinya di negeri-negeri lain) dalam hal kekuatan dan keperkasaannya.",[["ٱلَّتِى","Which"],["لَمْ","not"],["يُخْلَقْ","had been created"],["مِثْلُهَا","like them"],["فِى","in"],["ٱلْبِلَـٰدِ","the cities"]]],"6002":["(Dan kaum Tsamud yang memotong) yang memahat (batu-batu besar) lafal Ash-Shakhr adalah bentuk jamak dari lafal Shakhrah; kemudian batu-batu besar yang mereka lubangi itu dijadikan sebagai rumah tempat tinggal mereka (di lembah) yakni Wadil Qura namanya.",[["وَثَمُودَ","And Thamud"],["ٱلَّذِينَ","who"],["جَابُوا۟","carved out"],["ٱلصَّخْرَ","the rocks"],["بِٱلْوَادِ","in the valley"]]],"6003":["(Dan Firaun yang mempunyai pasak-pasak) ia dikenal dengan julukan tersebut, bila menyiksa seseorang ia membuat empat pasak, kemudian kedua tangan dan kedua kaki orang yang disiksanya itu diikatkan pada masing-masing pasak.",[["وَفِرْعَوْنَ","And Firaun"],["ذِى","owner of"],["ٱلْأَوْتَادِ","stakes"]]],"6004":["(Yang berbuat sewenang-wenang) maksudnya Firaun dan bala tentaranya berbuat angkara murka (dalam negeri.)",[["ٱلَّذِينَ","Who"],["طَغَوْا۟","transgressed"],["فِى","in"],["ٱلْبِلَـٰدِ","the lands"]]],"6005":["(Lalu mereka berbuat banyak kerusakan dalam negeri itu) dengan melakukan pembunuhan dan kelaliman lainnya.",[["فَأَكْثَرُوا۟","And (made) much"],["فِيهَا","therein"],["ٱلْفَسَادَ","corruption"]]],"6006":["(Karena itu Rabbmu menimpakan kepada mereka cemeti) sejenis (azab.)",[["فَصَبَّ","So poured"],["عَلَيْهِمْ","on them"],["رَبُّكَ","your Lord"],["سَوْطَ","scourge"],["عَذَابٍ","(of) punishment"]]],"6007":["(Sesungguhnya Rabbmu benar-benar mengawasi) semua amal perbuatan hamba-hamba-Nya, maka tiada sesuatu pun yang terlewat dari-Nya di antara amal-amal perbuatan itu, supaya Dia membalasnya kepada mereka.",[["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["لَبِٱلْمِرْصَادِ","(is) surely Ever Watchful"]]],"6008":["(Adapun manusia) yakni orang kafir (apabila dia diuji) dikenakan ujian (oleh Rabbnya lalu dimuliakan-Nya) dengan harta benda dan lain-lainnya (dan diberi-Nya kesenangan, maka dia berkata, \"Rabbku telah memuliakanku.\")",[["فَأَمَّا","And as for"],["ٱلْإِنسَـٰنُ","man"],["إِذَا","when"],["مَا","does"],["ٱبْتَلَىٰهُ","try him"],["رَبُّهُۥ","his Lord"],["فَأَكْرَمَهُۥ","and is generous to him"],["وَنَعَّمَهُۥ","and favors him"],["فَيَقُولُ","he says"],["رَبِّىٓ","My Lord"],["أَكْرَمَنِ","has honored me"]]],"6009":["(Adapun bila Rabbnya mengujinya lalu Dia membatasi) atau menyempitkan (rezekinya, maka dia berkata, \"Rabbku menghinaku.\")",[["وَأَمَّآ","But"],["إِذَا","when"],["مَا","does"],["ٱبْتَلَىٰهُ","He try him"],["فَقَدَرَ","and restricts"],["عَلَيْهِ","for him"],["رِزْقَهُۥ","his provision"],["فَيَقُولُ","then he says"],["رَبِّىٓ","My Lord"],["أَهَـٰنَنِ","(has) humiliated me"]]],"6010":["(Sekali-kali tidak) kalimat ini merupakan hardikan, bahwa perkara yang sebenarnya tidaklah demikian, maksud dimuliakan itu dengan diberi kekayaan, dan dihina itu dengan diberi kemiskinan. Sesungguhnya seseorang itu menjadi mulia karena ketaatannya, dan menjadi terhina karena kemaksiatannya. Orang-orang kafir Mekah tidak memperhatikan hal ini (sebenarnya kalian tidak memuliakan anak yatim) artinya kalian tidak pernah berbuat baik kepada anak-anak yatim, padahal kalian kaya atau kalian tidak memberikan harta waris yang menjadi hak anak-anak yatim.",[["كَلَّا ۖ","Nay"],["بَل","But"],["لَّا","not"],["تُكْرِمُونَ","you honor"],["ٱلْيَتِيمَ","the orphan"]]],"6011":["(Dan kalian tidak mengajak) diri kalian atau orang lain (memberi makan) (orang miskin.)",[["وَلَا","And not"],["تَحَـٰٓضُّونَ","you feel the urge"],["عَلَىٰ","to"],["طَعَامِ","feed"],["ٱلْمِسْكِينِ","the poor"]]],"6012":["(Dan kalian memakan harta pusaka) harta peninggalan (dengan cara mencampur-aduk) tanpa segan-segan lagi, maksudnya kalian mencampur-baurkan harta warisan bagian wanita dan anak-anak dengan bagian kalian; atau kalian mencampur-baurkan harta warisan mereka dengan harta kalian sendiri.",[["وَتَأْكُلُونَ","And you consume"],["ٱلتُّرَاثَ","the inheritance"],["أَكْلًۭا","devouring"],["لَّمًّۭا","altogether"]]],"6013":["(Dan kalian mencintai harta benda dengan kecintaan yang berlebihan) sehingga kalian merasa sayang untuk menafkahkannya di jalan kebaikan. Menurut suatu qiraat pada keempat Fi'il tadi, yaitu Laa Tukrimuuna, Laa Tahaadhdhuuna, Ta'kuluuna, dan Tuhibbuuna, dibaca Laa Yukrimuuna, Laa Yahaadhdhuuna, Ya'kuluuna, dan Yuhibbuuna. Makna ayat-ayat di atas berdasarkan bacaan pertama.",[["وَتُحِبُّونَ","And you love"],["ٱلْمَالَ","wealth"],["حُبًّۭا","(with) love"],["جَمًّۭا","immense"]]],"6014":["(Jangan berbuat demikian) lafal Kallaa ini adalah kalimat cegahan supaya jangan melakukan hal-hal tersebut. (Apabila bumi diguncangkan berturut-turut) artinya secara terus-menerus sehingga hancur musnahlah semua bangunan-bangunan yang ada di permukaannya.",[["كَلَّآ","Nay"],["إِذَا","When"],["دُكَّتِ","is leveled"],["ٱلْأَرْضُ","the earth"],["دَكًّۭا","pounded"],["دَكًّۭا","(and) crushed"]]],"6015":["(Dan datanglah Rabbmu) yakni perintah-Nya (sedangkan malaikat-malaikat) lafal Al-Malak adalah bentuk mufrad dari lafal Al-Malaaikah (berbaris-baris) lafal Shaffan berkedudukan menjadi Hal atau kata keterangan keadaan yakni, berbaris-baris atau membentuk barisan-barisan yang banyak.",[["وَجَآءَ","And comes"],["رَبُّكَ","your Lord"],["وَٱلْمَلَكُ","and the Angels"],["صَفًّۭا","rank"],["صَفًّۭا","(upon) rank"]]],"6016":["(Dan pada hari itu didatangkan neraka Jahanam) ditarik dengan memakai tujuh puluh ribu kendali, pada tiap-tiap kendali dipegang oleh tujuh puluh ribu malaikat, neraka Jahanam terdengar gejolak dan gemuruhnya (pada hari itu) menjadi Badal dari lafal Idzaa dan Jawabnya (ingatlah manusia) maksudnya orang kafir ingat kepada apa yang telah dilalaikannya (akan tetapi tidak berguna lagi mengingat itu baginya) Istifham atau lafal Annaa di sini bermakna Nafi, artinya penyesalannya pada saat itu tidak ada gunanya lagi.",[["وَجِا۟ىٓءَ","And is brought"],["يَوْمَئِذٍۭ","that Day"],["بِجَهَنَّمَ ۚ","Hell"],["يَوْمَئِذٍۢ","That Day"],["يَتَذَكَّرُ","will remember"],["ٱلْإِنسَـٰنُ","man"],["وَأَنَّىٰ","but how"],["لَهُ","(will be) for him"],["ٱلذِّكْرَىٰ","the remembrance"]]],"6017":["(Dia mengatakan) sewaktu ingat akan kesalahan-kesalahannya (\"Alangkah baiknya) huruf Ya di sini bermakna Tanbih (sekiranya aku dahulu mengerjakan) amal kebaikan dan beriman (untuk hidupku ini\") untuk kehidupan yang baik di akhirat, atau sewaktu aku hidup di dunia.",[["يَقُولُ","He will say"],["يَـٰلَيْتَنِى","O I wish"],["قَدَّمْتُ","I had sent forth"],["لِحَيَاتِى","for my life"]]],"6018":["(Maka pada hari itu tiada yang mengazab) dibaca Yu'adzdzibu dengan dikasrahkan huruf Dzalnya (seperti azab-Nya) seperti azab Allah (seseorang pun) artinya Dia tidak menyerahkannya kepada seseorang pun melainkan hanya kepada diri-Nya.",[["فَيَوْمَئِذٍۢ","So that Day"],["لَّا","not"],["يُعَذِّبُ","will punish"],["عَذَابَهُۥٓ","(as) His punishment"],["أَحَدٌۭ","anyone"]]],"6019":["(Dan) demikian pula (tiada yang dapat mengikat) dibaca Laa Yuutsiqu (seperti ikatannya, seseorang pun) menurut suatu qiraat lafal Laa Yu'adzdzibu dan lafal Laa Yuutsiqu dibaca Laa Yu'adzdzabu dan Laa Yuutsaqu dengan demikian maka Dhamir yang dikandung kedua lafal tersebut kembali kepada orang kafir. Lengkapnya, tiada seseorang pun yang diazab seperti azab yang ditimpakan kepada orang kafir, dan tiada seseorang pun yang diikat seperti ikatan yang dibelenggukan kepada orang kafir.",[["وَلَا","And not"],["يُوثِقُ","will bind"],["وَثَاقَهُۥٓ","(as) His binding"],["أَحَدٌۭ","anyone"]]],"6020":["(Hai jiwa yang tenang) atau yang aman, dimaksud adalah jiwa yang beriman.",[["يَـٰٓأَيَّتُهَا","O"],["ٱلنَّفْسُ","soul"],["ٱلْمُطْمَئِنَّةُ","who is satisfied"]]],"6021":["(Kembalilah kepada Rabbmu) perkataan ini diucapkan kepadanya sewaktu ia menjelang mati; yakni kembalilah kamu kepada perintah dan kehendak-Nya (dengan hati yang puas) akan pahala yang kamu terima (lagi diridai) di sisi Allah maksudnya, semua amal perbuatanmu diridai di sisi-Nya. Jiwa yang beriman itu merasa puas dan diridai; kedudukan kedua lafal ini menjadi kata keterangan keadaan; kemudian dikatakan kepadanya pada hari kiamat nanti:",[["ٱرْجِعِىٓ","Return"],["إِلَىٰ","to"],["رَبِّكِ","your Lord"],["رَاضِيَةًۭ","well pleased"],["مَّرْضِيَّةًۭ","and pleasing"]]],"6022":["(\"Maka masuklah ke dalam) jamaah (hamba-hamba-Ku) yang saleh.",[["فَٱدْخُلِى","So enter"],["فِى","among"],["عِبَـٰدِى","My slaves"]]],"6023":["(Dan masuklah ke dalam surga-Ku\") bersama dengan hamba-hamba-Ku yang saleh.",[["وَٱدْخُلِى","And enter"],["جَنَّتِى","My Paradise"]]],"6024":["(Sungguh) huruf Laa di sini adalah huruf Zaidah mengandung makna Taukid (Aku bersumpah dengan kota ini) yakni kota Mekah.",[["لَآ","Nay"],["أُقْسِمُ","I swear"],["بِهَـٰذَا","by this"],["ٱلْبَلَدِ","city"]]],"6025":["(Dan kamu) hai Muhammad (halal) maksudnya dihalalkan bagimu (kota ini) artinya Dia menghalalkannya untukmu melakukan peperangan di dalamnya untuk melawan orang-orang musyrik. Allah memenuhi janji-Nya itu pada waktu penaklukan kota Mekah. Ayat ini merupakan Jumlah Mu'taridhah yang terletak di antara Qasam yang pertama dengan Qasam yang selanjutnya.",[["وَأَنتَ","And you"],["حِلٌّۢ","(are) free (to dwell)"],["بِهَـٰذَا","in this"],["ٱلْبَلَدِ","city"]]],"6026":["(Dan demi bapak) yaitu Nabi Adam (dan anaknya) atau anak cucunya; huruf Maa di sini bermakna Man.",[["وَوَالِدٍۢ","And the begetter"],["وَمَا","and what"],["وَلَدَ","he begot"]]],"6027":["(Sesungguhnya Kami telah menciptakan manusia) semuanya (berada dalam susah payah) yaitu lelah dan susah karena selalu menghadapi musibah-musibah di dunia dan kesengsaraan-kesengsaraan di akhirat.",[["لَقَدْ","Certainly"],["خَلَقْنَا","We have created"],["ٱلْإِنسَـٰنَ","man"],["فِى","(to be) in"],["كَبَدٍ","hardship"]]],"6028":["(Apakah manusia itu menyangka) atau apakah manusia menduga, bahwa dia itu adalah kuat. Yang dimaksud adalah Asyad dari kalangan kaum Quraisy ia terkenal kekuatannya (bahwa) huruf An di sini adalah bentuk Takhfif dari Anna, sedangkan Isimnya tidak disebutkan, lengkapnya Annahuu (sekali-kali tiada seorang pun yang berkuasa atas dirinya?) Allahlah yang berkuasa atas dirinya.",[["أَيَحْسَبُ","Does he think"],["أَن","that"],["لَّن","not"],["يَقْدِرَ","has power"],["عَلَيْهِ","over him"],["أَحَدٌۭ","anyone"]]],"6029":["(Dia mengatakan, \"Aku telah menghabiskan) untuk memusuhi Muhammad (harta yang banyak\") maksudnya banyak mengeluarkan harta untuk memusuhinya.",[["يَقُولُ","He will say"],["أَهْلَكْتُ","I have squandered"],["مَالًۭا","wealth"],["لُّبَدًا","abundant"]]],"6030":["(Apakah dia menyangka bahwa) dirinya (tiada seorang pun yang melihatnya?) artinya melihat apa-apa yang telah dibelanjakannya itu, sehingga ada orang yang mengetahui berapa jumlah harta yang telah dibelanjakannya. Allahlah yang mengetahui berapa jumlah yang telah dibelanjakannya itu, dan jumlah sedemikian itu tidak berarti apa-apa di sisi-Nya, bahkan Dia kelak akan membalas perbuatannya yang buruk dan keji itu.",[["أَيَحْسَبُ","Does he think"],["أَن","that"],["لَّمْ","not"],["يَرَهُۥٓ","sees him"],["أَحَدٌ","anyone"]]],"6031":["(Bukankah Kami telah menjadikan) Istifham atau kata tanya di sini mengandung arti Taqrir (baginya dua buah mata,)",[["أَلَمْ","Have not"],["نَجْعَل","We made"],["لَّهُۥ","for him"],["عَيْنَيْنِ","two eyes"]]],"6032":["(lidah dan dua buah bibir?)",[["وَلِسَانًۭا","And a tongue"],["وَشَفَتَيْنِ","and two lips"]]],"6033":["(Dan Kami telah menunjukkan kepadanya dua jalan) maksudnya Kami telah menjelaskan kepadanya jalan kebaikan dan jalan keburukan.",[["وَهَدَيْنَـٰهُ","And shown him"],["ٱلنَّجْدَيْنِ","the two ways"]]],"6034":["(Maka kenapa ia tidak) atau mengapa ia tidak (menempuh jalan yang sulit?)",[["فَلَا","But not"],["ٱقْتَحَمَ","he has attempted"],["ٱلْعَقَبَةَ","the steep path"]]],"6035":["(Tahukah kamu) maksudnya apakah kamu mengetahui (apakah jalan yang sulit) yang akan ditempuhnya itu? Ungkapan ini mengagungkan kedudukan jalan tersebut. Ayat ini merupakan Jumlah Mu'taridhah atau kalimat sisipan; kemudian dijelaskan oleh ayat berikutnya, yaitu:",[["وَمَآ","And what"],["أَدْرَىٰكَ","can make you know"],["مَا","what"],["ٱلْعَقَبَةُ","the steep path (is)"]]],"6036":["(Melepaskan budak) dari perbudakan, yaitu dengan cara memerdekakannya.",[["فَكُّ","(It is) freeing"],["رَقَبَةٍ","a neck"]]],"6037":["(Atau memberi makan pada hari kelaparan) yakni sewaktu terjadi bencana kelaparan.",[["أَوْ","Or"],["إِطْعَـٰمٌۭ","feeding"],["فِى","in"],["يَوْمٍۢ","a day"],["ذِى","of"],["مَسْغَبَةٍۢ","severe hunger"]]],"6038":["(Kepada anak yatim yang ada hubungan kerabat) atau famili.",[["يَتِيمًۭا","An orphan"],["ذَا","of"],["مَقْرَبَةٍ","near relationship"]]],"6039":["(Atau orang miskin yang sangat fakir) artinya karena amat miskinnya hanya beralaskan tanah. Menurut suatu qiraat kedua Fi'il tersebut diganti menjadi dua Mashdar yang kedua-duanya dirafa'kan. Yang pertama dimudhafkan kepada lafal Raqabatin sedangkan yang kedua ditanwinkan, maka sebelum lafal Al-'Aqabah diperkirakan adanya lafal Iqtihaam. Qiraat ini merupakan penjelasan dari makna ayat-ayat tersebut.",[["أَوْ","Or"],["مِسْكِينًۭا","a needy person"],["ذَا","in"],["مَتْرَبَةٍۢ","misery"]]],"6040":["(Kemudian dia adalah) lafal ayat ini di'athafkan kepada lafal Iqtahama; dan lafal Tsumma menunjukkan makna urutan penyebutan atau Tartiibudz Dzikr. Artinya dia sewaktu menempuh jalan yang sulit itu (termasuk orang-orang yang beriman dan saling berpesan) yakni sebagian di antara mereka berpesan kepada sebagian yang lain (untuk bersabar) di dalam menjalankan amal ketaatan dan menjauhi perbuatan kemaksiatan (dan saling berpesan untuk berkasih sayang) terhadap semua makhluk.",[["ثُمَّ","Then"],["كَانَ","he is"],["مِنَ","of"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَتَوَاصَوْا۟","and enjoin (each other)"],["بِٱلصَّبْرِ","to patience"],["وَتَوَاصَوْا۟","and enjoin (each other)"],["بِٱلْمَرْحَمَةِ","to compassion"]]],"6041":["(Mereka) yaitu orang-orang yang memiliki sifat-sifat demikian itu (adalah golongan kanan.)",[["أُو۟لَـٰٓئِكَ","Those"],["أَصْحَـٰبُ","(are the) companions"],["ٱلْمَيْمَنَةِ","(of) the right (hand)"]]],"6042":["(Dan orang-orang yang kafir kepada ayat-ayat Kami, mereka itu adalah golongan kiri)",[["وَٱلَّذِينَ","But those who"],["كَفَرُوا۟","disbelieve"],["بِـَٔايَـٰتِنَا","in Our Verses"],["هُمْ","they"],["أَصْحَـٰبُ","(are the) companions"],["ٱلْمَشْـَٔمَةِ","(of) the left (hand)"]]],"6043":["(orang-orang kiri itu berada dalam neraka yang ditutup rapat) dapat dibaca Mu'shadah dan Muushadah, artinya neraka yang tertutup rapat.",[["عَلَيْهِمْ","Over them"],["نَارٌۭ","(will be the) Fire"],["مُّؤْصَدَةٌۢ","closed in"]]],"6044":["(Demi matahari dan cahayanya di pagi hari) yaitu sewaktu memancarkan sinarnya di pagi hari.",[["وَٱلشَّمْسِ","By the sun"],["وَضُحَىٰهَا","and its brightness"]]],"6045":["(Dan bulan apabila mengiringinya) apabila muncul mengiringi terbenamnya matahari.",[["وَٱلْقَمَرِ","And the moon"],["إِذَا","when"],["تَلَىٰهَا","it follows it"]]],"6046":["(Dan siang apabila menampilkannya) yaitu menampakkan matahari yang semakin meninggi.",[["وَٱلنَّهَارِ","And the day"],["إِذَا","when"],["جَلَّىٰهَا","it displays it"]]],"6047":["(Dan malam apabila menutupinya) artinya menyelimuti siang dengan kegelapannya. Lafal Idzaa yang ada pada tiga tempat di atas hanya menunjukkan makna Zharaf, sedangkan yang menjadi Amilnya adalah Fi'il dari Qasam.",[["وَٱلَّيْلِ","And the night"],["إِذَا","when"],["يَغْشَىٰهَا","it covers it"]]],"6048":["(Dan langit serta pembinaannya.)",[["وَٱلسَّمَآءِ","And the heaven"],["وَمَا","and (He) Who"],["بَنَىٰهَا","constructed it"]]],"6049":["(Dan bumi serta penghamparannya) yang menghampar.",[["وَٱلْأَرْضِ","And the earth"],["وَمَا","and by (He) Who"],["طَحَىٰهَا","spread it"]]],"6050":["(Dan jiwa) sekalipun bentuk lafalnya Mufrad tetapi makna yang dimaksud adalah Jamak (serta penyempurnaannya) maksudnya kesempurnaan ciptaannya; lafal Maa pada tiga tempat di atas adalah Maa Mashdariyah, atau bermakna Man.",[["وَنَفْسٍۢ","And (the) soul"],["وَمَا","and (He) Who"],["سَوَّىٰهَا","proportioned it"]]],"6051":["(Maka Allah mengilhamkan kepada jiwa itu kefasikan dan ketakwaannya) maksudnya Allah menjelaskan kepadanya jalan kebaikan dan jalan keburukan. Lafal At-Taqwaa letaknya diakhirkan karena demi memelihara keserasian bunyi akhir ayat, sedangkan sebagai Jawab dari Qasam di atas ialah:",[["فَأَلْهَمَهَا","And He inspired it"],["فُجُورَهَا","(to distinguish) its wickedness"],["وَتَقْوَىٰهَا","and its righteousness"]]],"6052":["(Sesungguhnya beruntunglah) pada lafal Qad Aflaha ini sengaja tidak disebutkan huruf Lam Taukidnya karena mengingat panjangnya pembicaraan (orang yang menyucikannya) yakni menyucikan jiwanya dari dosa-dosa.",[["قَدْ","Indeed"],["أَفْلَحَ","he succeeds"],["مَن","who"],["زَكَّىٰهَا","purifies it"]]],"6053":["(Dan sesungguhnya merugilah) atau rugilah (orang yang mengotorinya) yang menodainya dengan perbuatan maksiat. Asalnya lafal Dassaahaa ialah Dassasahaa, kemudian huruf Sin yang kedua diganti menjadi Alif demi untuk meringankan pengucapannya, akhirnya jadilah Dassaahaa.",[["وَقَدْ","And indeed"],["خَابَ","he fails"],["مَن","who"],["دَسَّىٰهَا","buries it"]]],"6054":["(Kaum Tsamud telah mendustakan) rasulnya, yaitu Nabi Saleh (karena mereka melampaui batas) disebabkan tindakan mereka yang melampaui batas.",[["كَذَّبَتْ","Denied"],["ثَمُودُ","Thamud"],["بِطَغْوَىٰهَآ","by their transgression"]]],"6055":["(Ketika bangkit) artinya bersegera (orang yang paling celaka di antara mereka) orang tersebut dikenal dengan nama julukan si pendekar, lalu ia bersegera menyembelih unta Nabi Saleh atas izin mereka.",[["إِذِ","When"],["ٱنۢبَعَثَ","(was) sent forth"],["أَشْقَىٰهَا","(the) most wicked of them"]]],"6056":["(Lalu Rasul Allah berkata kepada mereka) yakni Nabi Saleh (\"Unta betina Allah) maksudnya biarkanlah unta betina Allah ini (dan minumannya\") dan hari bagian minumnya; sesungguhnya bagian minum itu digilirkan antara mereka dan unta; untuk unta sehari dan untuk mereka sehari.",[["فَقَالَ","But said"],["لَهُمْ","to them"],["رَسُولُ","(the) Messenger"],["ٱللَّهِ","(of) Allah"],["نَاقَةَ","(It is the) she-camel"],["ٱللَّهِ","(of) Allah"],["وَسُقْيَـٰهَا","and her drink"]]],"6057":["(Lalu mereka mendustakannya) mendustakan ucapan Nabi Saleh yang mengatakan, bahwa unta itu adalah milik Allah, dan bila mereka melanggarnya niscaya hal itu akan berakibat turunnya azab atas mereka (dan menyembelih unta itu) atau mereka membunuhnya itu, dengan maksud supaya bagian minum itu diperoleh seluruhnya oleh mereka (maka menimpakanlah) atau menurunkanlah (kepada mereka Rabb mereka) azab (disebabkan dosa mereka, lalu Allah meratakan azab) atas mereka, sehingga tidak ada seorang pun dari mereka yang dapat lolos atau menyelamatkan diri dari azab-Nya.",[["فَكَذَّبُوهُ","But they denied him"],["فَعَقَرُوهَا","and they hamstrung her"],["فَدَمْدَمَ","So destroyed"],["عَلَيْهِمْ","them"],["رَبُّهُم","their Lord"],["بِذَنۢبِهِمْ","for their sin"],["فَسَوَّىٰهَا","and leveled them"]]],"6058":["(Dan tiadalah) dapat dibaca Walaa dan Falaa (Allah takut terhadap akibat tindakan-Nya itu) maksudnya akibat azab yang akan terjadi.",[["وَلَا","And not"],["يَخَافُ","He fears"],["عُقْبَـٰهَا","its consequences"]]],"6059":["(Demi malam apabila menutupi) semua apa yang ada di langit dan di bumi dengan kegelapannya.",[["وَٱلَّيْلِ","By the night"],["إِذَا","when"],["يَغْشَىٰ","it covers"]]],"6060":["(Dan siang apabila terang benderang) apabila menampilkan dirinya. Lafal Idzaa yang ada pada dua tempat di atas hanya menunjukkan makna Zharaf atau waktu. Sedangkan yang menjadi Amilnya adalah Fi'il Qasam.",[["وَٱلنَّهَارِ","And the day"],["إِذَا","when"],["تَجَلَّىٰ","it shines in brightness"]]],"6061":["(Dan apa) lafal Maa di sini bermakna Man, yakni manusia; atau dianggap sebagai Maa Mashdariyah (yang Dia telah menciptakannya, yaitu laki-laki dan perempuan) yang dimaksud adalah Adam dan Hawa, demikian pula setiap laki-laki dan perempuan lainnya. Adapun banci/wadam yang tidak dapat diketahui apakah ia sebagai laki-laki atau perempuan di sisi Allah swt., maka jika seseorang yang bersumpah bahwa dia tidak akan berbicara dengan siapa pun baik laki-laki atau perempuan, lalu dia berbicara dengan orang banci, maka dia dianggap telah melanggar sumpahnya itu.",[["وَمَا","And He Who"],["خَلَقَ","created"],["ٱلذَّكَرَ","the male"],["وَٱلْأُنثَىٰٓ","and the female"]]],"6062":["(Sesungguhnya usaha kalian) atau kerja kalian (memang berbeda-beda) beraneka macam; ada orang yang beramal atau bekerja untuk mendapatkan surga, dengan cara menempuh jalan ketaatan; dan ada pula orang yang beramal atau bekerja untuk neraka, dengan cara menempuh jalan kemaksiatan.",[["إِنَّ","Indeed"],["سَعْيَكُمْ","your efforts"],["لَشَتَّىٰ","(are) surely diverse"]]],"6063":["(Adapun orang yang memberikan) menginfakkan hartanya di jalan Allah (dan bertakwa) kepada Allah.",[["فَأَمَّا","Then as for"],["مَنْ","(him) who"],["أَعْطَىٰ","gives"],["وَٱتَّقَىٰ","and fears"]]],"6064":["(Dan membenarkan perkara yang baik) yaitu makna yang terkandung di dalam lafal Laa Ilaaha Illallaah yang artinya tiada Tuhan selain Allah. Dengan kata lain, bahwa infak di jalan Allah yang dilakukannya dan bertakwa kepada-Nya yang dijalankannya itu tiada lain berangkat dari keimanannya kepada kalimat Laa Ilaaha Illallaah.",[["وَصَدَّقَ","And believes"],["بِٱلْحُسْنَىٰ","in the best"]]],"6065":["(Maka Kami kelak akan menyiapkan baginya tempat yang mudah) yaitu surga.",[["فَسَنُيَسِّرُهُۥ","Then We will ease him"],["لِلْيُسْرَىٰ","towards [the] ease"]]],"6066":["(Dan adapun orang yang bakhil) tidak mau menginfakkan hartanya di jalan Allah (dan merasa dirinya cukup) artinya tidak membutuhkan pahala-Nya.",[["وَأَمَّا","But as for"],["مَنۢ","(him) who"],["بَخِلَ","withholds"],["وَٱسْتَغْنَىٰ","and considers himself free from need"]]],"6067":["(Serta mendustakan perkara yang baik.)",[["وَكَذَّبَ","And denies"],["بِٱلْحُسْنَىٰ","the best"]]],"6068":["(Maka kelak Kami akan menyiapkan baginya) menyediakan baginya (tempat yang sukar) yaitu neraka.",[["فَسَنُيَسِّرُهُۥ","Then We will ease him"],["لِلْعُسْرَىٰ","towards [the] difficulty"]]],"6069":["(Dan tiadalah) huruf Maa di sini bermakna Nafi yakni tidaklah (berguna bagi dirinya harta miliknya apabila ia telah terjerumus) ke dalam neraka.",[["وَمَا","And not"],["يُغْنِى","will avail"],["عَنْهُ","him"],["مَالُهُۥٓ","his wealth"],["إِذَا","when"],["تَرَدَّىٰٓ","he falls"]]],"6070":["(Sesungguhnya kewajiban Kamilah memberi petunjuk) untuk membedakan antara jalan hidayah dan jalan kesesatan; dimaksud supaya ia mengerjakan perintah Kami dengan menempuh jalan yang pertama, dan ia Kami larang dari menempuh jalan yang kedua.",[["إِنَّ","Indeed"],["عَلَيْنَا","upon Us"],["لَلْهُدَىٰ","(is) the guidance"]]],"6071":["(Dan sesungguhnya kepunyaan Kamilah akhirat dan dunia) maka barang siapa yang mencari keduanya tanpa meminta kepada Kami berarti dia telah sesat jalan.",[["وَإِنَّ","And indeed"],["لَنَا","for Us"],["لَلْـَٔاخِرَةَ","(is) the Hereafter"],["وَٱلْأُولَىٰ","and the first (life)"]]],"6072":["(Maka Kami memperingatkan kalian) maksudnya Kami pertakuti kalian hai penduduk Mekah (dengan neraka yang menyala-nyala) asal kata Talazhzhaa adalah Tatalazhzhaa, kemudian salah satu di antara kedua huruf Ta dibuang, sehingga jadilah Talazhzhaa. Akan tetapi ada juga suatu qiraat yang membaca sesuai dengan huruf asalnya.",[["فَأَنذَرْتُكُمْ","So I warn you"],["نَارًۭا","(of) a Fire"],["تَلَظَّىٰ","blazing"]]],"6073":["(Tidak ada yang masuk ke dalamnya) atau memasukinya (kecuali orang yang celaka) sekalipun lafal Al-Asyqaa ini menunjukkan arti yang paling celaka, akan tetapi makna yang dimaksud ialah orang yang celaka.",[["لَا","Not"],["يَصْلَىٰهَآ","will burn (in) it"],["إِلَّا","except"],["ٱلْأَشْقَى","the most wretched"]]],"6074":["(Yang mendustakan) Nabi saw. (dan berpaling) dari iman. Pengecualian yang terdapat pada ayat sebelum ayat ini merupakan takwil dari makna yang terkandung di dalam ayat lainnya yaitu, firman-Nya, \"dan Dia mengampuni segala dosa yang selain dari (syirik) itu, bagi siapa yang dikehendaki-Nya.\" (Q.S. An-Nisa, 48) Dengan demikian berarti makna yang dimaksud dengan masuk neraka pada ayat 15 tadi adalah masuk untuk selama-lamanya, yakni untuk menjadi penghuni yang abadi.",[["ٱلَّذِى","The one who"],["كَذَّبَ","denied"],["وَتَوَلَّىٰ","and turned away"]]],"6075":["(Dan kelak akan dijauhkan dari neraka itu) dihindarkan daripadanya (orang yang bertakwa) demikian pula lafal Al-Atqaa, sekalipun menunjukkan makna Tafdhil, tetapi makna yang dimaksud adalah At-Taqiyyu, yakni orang yang bertakwa.",[["وَسَيُجَنَّبُهَا","But will be removed from it"],["ٱلْأَتْقَى","the righteous"]]],"6076":["(Yang menafkahkan hartanya untuk membersihkannya) untuk membersihkannya di sisi Allah swt. seumpamanya dia mengeluarkannya bukan karena ria atau pamer dan gengsi, maka setelah itu harta yang dimilikinya menjadi bersih di sisi-Nya nanti. Ayat ini diturunkan berkenaan dengan Abu Bakar Ash-Shiddiq r.a. yaitu sewaktu ia membeli Bilal yang sedang disiksa oleh majikannya karena beriman. Setelah membelinya lalu langsung memerdekakannya. Pada saat itu juga orang-orang kafir mengatakan, bahwa tiada lain Abu Bakar melakukan hal tersebut karena ia telah berutang jasa kepadanya. Maka pada saat itu turunlah ayat ini.",[["ٱلَّذِى","The one who"],["يُؤْتِى","gives"],["مَالَهُۥ","his wealth"],["يَتَزَكَّىٰ","(to) purify himself"]]],"6077":["(Padahal tidak ada seseorang pun memberikan suatu nikmat kepadanya yang harus dibalasnya,)",[["وَمَا","And not"],["لِأَحَدٍ","for anyone"],["عِندَهُۥ","with him"],["مِن","any"],["نِّعْمَةٍۢ","favor"],["تُجْزَىٰٓ","to be recompensed"]]],"6078":["(melainkan) tetapi hanya semata-mata (karena mencari keridaan Rabbnya Yang Maha Tinggi) artinya dia memberikan hartanya itu hanya karena mengharapkan pahala Allah.",[["إِلَّا","Except"],["ٱبْتِغَآءَ","seeking"],["وَجْهِ","(the) Countenance"],["رَبِّهِ","(of) his Lord"],["ٱلْأَعْلَىٰ","the Most High"]]],"6079":["(Dan kelak Dia benar-benar mendapat kepuasan) dari pahala pemberiannya itu di surga nanti. Makna ayat ini mencakup pula setiap orang yang mengerjakan amal perbuatan seperti yang telah dilakukan oleh Abu Bakar r.a. Kelak dia akan dijauhkan dari neraka dan mendapatkan pahala yang berlimpah.",[["وَلَسَوْفَ","And soon, surely"],["يَرْضَىٰ","he will be pleased"]]],"6080":["(Demi waktu Dhuha) yakni waktu matahari sepenggalah naik, yaitu di awal siang hari; atau makna yang dimaksud ialah siang hari seluruhnya.",[["وَٱلضُّحَىٰ","By the morning brightness"]]],"6081":["(Dan demi malam apabila telah sunyi) telah tenang, atau telah menutupi dengan kegelapannya.",[["وَٱلَّيْلِ","And the night"],["إِذَا","when"],["سَجَىٰ","it covers with darkness"]]],"6082":["(Tiada meninggalkan kamu) tiada membiarkan kamu sendirian, hai Muhammad (Rabbmu, dan tiada pula Dia benci kepadamu) atau tidak senang kepadamu. Ayat ini diturunkan setelah selang beberapa waktu yaitu lima belas hari wahyu tidak turun-turun kepadanya, kemudian orang-orang kafir mengatakan, sesungguhnya Rabb Muhammad telah meninggalkannya dan membencinya.",[["مَا","Not"],["وَدَّعَكَ","has forsaken you"],["رَبُّكَ","your Lord"],["وَمَا","and not"],["قَلَىٰ","He is displeased"]]],"6083":["(Dan sesungguhnya akhir itu lebih baik bagimu) maksudnya kehidupan di akhirat itu lebih baik bagimu, karena di dalamnya terdapat kemuliaan-kemuliaan bagimu (dari permulaan) dari kehidupan duniawi.",[["وَلَلْـَٔاخِرَةُ","And surely the Hereafter"],["خَيْرٌۭ","(is) better"],["لَّكَ","for you"],["مِنَ","than"],["ٱلْأُولَىٰ","the first"]]],"6084":["(Dan kelak Rabbmu pasti memberimu) di akhirat berupa kebaikan-kebaikan yang berlimpah ruah (lalu kamu menjadi puas) dengan pemberian itu. Maka Rasulullah saw. bersabda, \"Kalau begitu mana mungkin aku puas, sedangkan seseorang di antara umatku masih berada di neraka.\" Sampai di sini selesailah Jawab Qasam, yaitu dengan kedua kalimat yang dinisbatkan sesudah dua kalimat yang dinafikan.",[["وَلَسَوْفَ","And soon"],["يُعْطِيكَ","will give you"],["رَبُّكَ","your Lord"],["فَتَرْضَىٰٓ","then you will be satisfied"]]],"6085":["(Bukankah Dia mendapatimu) Istifham atau kata tanya di sini mengandung makna Taqrir atau menetapkan (sebagai seorang yatim) karena ayahmu telah mati meninggalkan kamu sebelum kamu dilahirkan, atau sesudahnya (lalu Dia melindungimu) yaitu dengan cara menyerahkan dirimu ke asuhan pamanmu Abu Thalib.",[["أَلَمْ","Did not"],["يَجِدْكَ","He find you"],["يَتِيمًۭا","an orphan"],["فَـَٔاوَىٰ","and give shelter"]]],"6086":["(Dan Dia mendapatimu sebagai seorang yang bingung) mengenai syariat yang harus kamu jalankan (lalu Dia memberi petunjuk) Dia menunjukimu kepadanya.",[["وَوَجَدَكَ","And He found you"],["ضَآلًّۭا","lost"],["فَهَدَىٰ","so He guided"]]],"6087":["(Dan Dia mendapatimu sebagai seorang yang kekurangan) atau orang yang fakir (lalu Dia memberikan kecukupan) kepadamu dengan pemberian yang kamu merasa puas dengannya, yaitu dari ganimah dan dari lain-lainnya. Di dalam sebuah hadis disebutkan, \"Tiadalah kaya itu karena banyaknya harta, tetapi kaya itu adalah kaya jiwa.\"",[["وَوَجَدَكَ","And He found you"],["عَآئِلًۭا","in need"],["فَأَغْنَىٰ","so He made self-sufficient"]]],"6088":["(Adapun terhadap anak yatim maka janganlah kamu berlaku sewenang-wenang) dengan cara mengambil hartanya atau lain-lainnya yang menjadi milik anak yatim.",[["فَأَمَّا","So as for"],["ٱلْيَتِيمَ","the orphan"],["فَلَا","then (do) not"],["تَقْهَرْ","oppress"]]],"6089":["(Dan terhadap orang yang minta-minta maka janganlah kamu menghardiknya) membentaknya karena dia miskin.",[["وَأَمَّا","And as for"],["ٱلسَّآئِلَ","one who asks"],["فَلَا","then (do) not"],["تَنْهَرْ","repel"]]],"6090":["(Dan terhadap nikmat Rabbmu) yang dilimpahkan kepadamu, yaitu berupa kenabian dan nikmat-nikmat lainnya (maka hendaklah kamu menyebut-nyebutnya) yakni mengungkapkannya dengan cara mensyukurinya. Di dalam beberapa Fi'il pada surah ini Dhamir yang kembali kepada Rasulullah saw. tidak disebutkan karena demi memelihara Fawashil atau bunyi huruf di akhir ayat. Seperti lafal Qalaa asalnya Qalaaka; lafal Fa-aawaa asalnya Fa-aawaaka; lafal Fahadaa asalnya Fahadaaka; dan lafal Fa-aghnaa asalnya Fa-aghnaaka",[["وَأَمَّا","But as for"],["بِنِعْمَةِ","(the) Favor"],["رَبِّكَ","(of) your Lord"],["فَحَدِّثْ","narrate"]]],"6091":["(Bukankah Kami telah melapangkan) Istifham atau kata tanya di sini mengandung makna Taqrir atau menetapkan, yakni Kami telah melapangkan (untukmu) hai Muhammad (dadamu?) dengan kenabian dan lain-lainnya.",[["أَلَمْ","Have not"],["نَشْرَحْ","We expanded"],["لَكَ","for you"],["صَدْرَكَ","your breast"]]],"6092":["(Dan Kami telah menghilangkan) telah melenyapkan (darimu dosamu.)",[["وَوَضَعْنَا","And We removed"],["عَنكَ","from you"],["وِزْرَكَ","your burden"]]],"6093":["(Yang memberatkan) yang memayahkan (punggungmu) ayat ini maknanya sama dengan ayat lainnya yaitu, firman-Nya, \".... supaya Allah memberi ampunan kepadamu terhadap dosamu yang telah lalu...\" (Q.S. Al-Fath: 2)",[["ٱلَّذِىٓ","Which"],["أَنقَضَ","weighed upon"],["ظَهْرَكَ","your back"]]],"6094":["(Dan Kami tinggikan bagimu sebutanmu) yakni sebutan namamu sebagai contohnya ialah namamu disebutkan bersama-sama dengan nama-Ku di dalam azan, iqamah, tasyahhud, khotbah dan lain sebagainya.",[["وَرَفَعْنَا","And We raised high"],["لَكَ","for you"],["ذِكْرَكَ","your reputation"]]],"6095":["(Karena sesungguhnya sesudah kesulitan itu) atau kesukaran itu (ada kelapangan) yakni kemudahan.",[["فَإِنَّ","So indeed"],["مَعَ","with"],["ٱلْعُسْرِ","the hardship"],["يُسْرًا","(is) ease"]]],"6096":["(Sesungguhnya sesudah kesulitan itu ada kelapangan) Nabi saw. banyak sekali mengalami kesulitan dan hambatan dari orang-orang kafir, kemudian beliau mendapatkan kelapangan dan kemudahan, yaitu setelah beliau mengalami kemenangan atas mereka.",[["إِنَّ","Indeed"],["مَعَ","with"],["ٱلْعُسْرِ","the hardship"],["يُسْرًۭا","(is) ease"]]],"6097":["(Maka apabila kamu telah selesai) dari salat (bersungguh-sungguhlah kamu) di dalam berdoa.",[["فَإِذَا","So when"],["فَرَغْتَ","you have finished"],["فَٱنصَبْ","then labor hard"]]],"6098":["(Dan hanya kepada Rabbmulah hendaknya kamu berharap) atau meminta dengan merendahkan diri.",[["وَإِلَىٰ","And to"],["رَبِّكَ","your Lord"],["فَٱرْغَب","turn your attention"]]],"6099":["(Demi Tin dan Zaitun) keduanya adalah nama buah, atau dapat juga keduanya diartikan nama dua buah gunung yang menumbuhkan kedua buah tersebut.",[["وَٱلتِّينِ","By the fig"],["وَٱلزَّيْتُونِ","and the olive"]]],"6100":["(Dan demi bukit Sinai) nama sebuah bukit tempat sewaktu Allah swt. berfirman kepada Nabi Musa. Arti lafal Siiniina ialah yang diberkahi atau yang baik karena memiliki banyak pohon yang menghasilkan buah.",[["وَطُورِ","And (the) Mount"],["سِينِينَ","Sinai"]]],"6101":["(Dan demi kota ini yang aman) yaitu kota Mekah, dinamakan kota aman karena orang-orang yang tinggal di dalamnya merasa aman, baik pada zaman jahiliah maupun di zaman Islam.",[["وَهَـٰذَا","And this"],["ٱلْبَلَدِ","[the] city"],["ٱلْأَمِينِ","[the] secure"]]],"6102":["(Sesungguhnya Kami telah menciptakan manusia) artinya semua manusia (dalam bentuk yang sebaik-baiknya) artinya baik bentuk atau pun penampilannya amatlah baik.",[["لَقَدْ","Indeed"],["خَلَقْنَا","We created"],["ٱلْإِنسَـٰنَ","man"],["فِىٓ","in"],["أَحْسَنِ","(the) best"],["تَقْوِيمٍۢ","mould"]]],"6103":["(Kemudian Kami kembalikan dia) maksudnya sebagian di antara mereka (ke tempat yang serendah-rendahnya) ungkapan ini merupakan kata kiasan bagi masa tua, karena jika usia telah lanjut kekuatan pun sudah mulai melemah dan pikun. Dengan demikian ia akan berkurang dalam beramal, berbeda dengan sewaktu masih muda; sekalipun demikian dalam hal mendapat pahala ia akan mendapat imbalan yang sama sebagaimana sewaktu ia beramal di kala masih muda, hal ini diungkapkan dalam firman selanjutnya, yaitu:",[["ثُمَّ","Then"],["رَدَدْنَـٰهُ","We returned him"],["أَسْفَلَ","(to the) lowest"],["سَـٰفِلِينَ","(of the) low"]]],"6104":["(Kecuali) melainkan (orang-orang yang beriman dan mengerjakan amal saleh; maka bagi mereka pahala yang tiada putus-putusnya) atau pahala yang tak pernah terputus. Di dalam sebuah hadis telah disebutkan, bahwa apabila orang mukmin mencapai usia tua hingga ia tidak mampu lagi untuk mengerjakan amal kebaikan, maka dituliskan baginya pahala amal kebaikan yang biasa ia kerjakan di masa mudanya dahulu.",[["إِلَّا","Except"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["فَلَهُمْ","then for them"],["أَجْرٌ","(is a) reward"],["غَيْرُ","never"],["مَمْنُونٍۢ","ending"]]],"6105":["(Maka apakah yang menyebabkan kamu mendustakan) hai orang kafir (sesudah itu) yakni sesudah hal-hal yang telah disebutkan tadi, yaitu mengenai penciptaan manusia dalam bentuk yang sebaik-baiknya, kemudian dijadikan-Nya tua dan pikun, yang hal ini menunjukkan kepada kekuasaan-Nya untuk membangkitkan makhluk hidup kembali (hari pembalasan) yang terlebih dahulu diawali dengan hari kebangkitan lalu perhitungan amal perbuatan. Maksudnya apakah gerangan yang mendorongmu mendustakan hal tersebut? Tentu saja tidak ada yang mendorongnya untuk mendustakan hal tersebut selain dirinya sendiri.",[["فَمَا","Then what"],["يُكَذِّبُكَ","causes you to deny"],["بَعْدُ","after (this)"],["بِٱلدِّينِ","the judgment"]]],"6106":["(Bukankah Allah hakim yang seadil-adilnya?) artinya Dia adalah hakim yang paling adil di antara hakim-hakim yang adil lainnya, dan keputusan-Nya berdasarkan sifat tersebut. Di dalam sebuah hadis disebutkan, \"Barang siapa membaca surah At-Tiin hingga akhir surah, maka hendaknya sesudah itu ia menjawab, 'Balaa Wa Anaa 'Alaa Dzaalika Minasy Syaahidiina/tentu saja kami termasuk orang-orang yang menyaksikan akan hal tersebut.'\"",[["أَلَيْسَ","Is not"],["ٱللَّهُ","Allah"],["بِأَحْكَمِ","(the) Most Just"],["ٱلْحَـٰكِمِينَ","(of) the Judges"]]],"6107":["(Bacalah) maksudnya mulailah membaca dan memulainya (dengan menyebut nama Rabbmu yang menciptakan) semua makhluk.",[["ٱقْرَأْ","Read"],["بِٱسْمِ","in (the) name"],["رَبِّكَ","(of) your Lord"],["ٱلَّذِى","the One Who"],["خَلَقَ","created "]]],"6108":["(Dia telah menciptakan manusia) atau jenis manusia (dari 'alaq) lafal 'Alaq bentuk jamak dari lafal 'Alaqah, artinya segumpal darah yang kental.",[["خَلَقَ","He created"],["ٱلْإِنسَـٰنَ","man"],["مِنْ","from"],["عَلَقٍ","a clinging substance"]]],"6109":["(Bacalah) lafal ayat ini mengukuhkan makna lafal pertama yang sama (dan Rabbmulah Yang Paling Pemurah) artinya tiada seorang pun yang dapat menandingi kemurahan-Nya. Lafal ayat ini sebagai Haal dari Dhamir yang terkandung di dalam lafal Iqra'.",[["ٱقْرَأْ","Read"],["وَرَبُّكَ","and your Lord"],["ٱلْأَكْرَمُ","(is) the Most Generous"]]],"6110":["(Yang mengajar) manusia menulis (dengan qalam) orang pertama yang menulis dengan memakai qalam atau pena ialah Nabi Idris a.s.",[["ٱلَّذِى","The One Who"],["عَلَّمَ","taught"],["بِٱلْقَلَمِ","by the pen"]]],"6111":["(Dia mengajarkan kepada manusia) atau jenis manusia (apa yang tidak diketahuinya) yaitu sebelum Dia mengajarkan kepadanya hidayah, menulis dan berkreasi serta hal-hal lainnya.",[["عَلَّمَ","Taught"],["ٱلْإِنسَـٰنَ","man"],["مَا","what"],["لَمْ","not"],["يَعْلَمْ","he knew"]]],"6112":["(Ketahuilah) artinya memang benar (sesungguhnya manusia benar-benar melampaui batas)",[["كَلَّآ","Nay"],["إِنَّ","Indeed"],["ٱلْإِنسَـٰنَ","man"],["لَيَطْغَىٰٓ","surely transgresses"]]],"6113":["(karena dia melihat dirinya) sendiri (serba cukup) dengan harta benda yang dimilikinya; ayat ini diturunkan berkenaan dengan sikap Abu Jahal. Dan lafal Ra-aa tidak membutuhkan Maf'ul kedua; dan lafal An Ra-aahu berkedudukan sebagai Maf'ul Lah.",[["أَن","That"],["رَّءَاهُ","he sees himself"],["ٱسْتَغْنَىٰٓ","self-sufficient"]]],"6114":["(Sesungguhnya hanya kepada Rabbmulah) hai Manusia (tempat kembali) yakni kembali kalian nanti, karena itu Dia kelak akan memberi balasan kepada orang yang melampaui batas sesuai dengan dosa-dosa yang telah dilakukannya. Di dalam ungkapan ini terkandung ancaman dan peringatan buat orang yang berlaku melampaui batas.",[["إِنَّ","Indeed"],["إِلَىٰ","to"],["رَبِّكَ","your Lord"],["ٱلرُّجْعَىٰٓ","(is) the return"]]],"6115":["(Bagaimana pendapatmu) lafal Ara-ayta dan dua lafal lainnya yang sama nanti mengandung makna Ta'ajjub (tentang orang yang melarang) yang dimaksud adalah Abu Jahal.",[["أَرَءَيْتَ","Have you seen"],["ٱلَّذِى","the one who"],["يَنْهَىٰ","forbids"]]],"6116":["(Seorang hamba) yang dimaksud adalah Nabi Muhammad saw. (ketika dia mengerjakan salat.)",[["عَبْدًا","A slave"],["إِذَا","when"],["صَلَّىٰٓ","he prays"]]],"6117":["(Bagaimana pendapatmu jika orang yang dilarang itu) (berada di atas kebenaran)",[["أَرَءَيْتَ","Have you seen"],["إِن","if"],["كَانَ","he is"],["عَلَى","upon"],["ٱلْهُدَىٰٓ","[the] guidance"]]],"6118":["(Atau) huruf Au di sini menunjukkan makna Taqsim (dia menyuruh bertakwa.)",[["أَوْ","Or"],["أَمَرَ","he enjoins"],["بِٱلتَّقْوَىٰٓ","[of the] righteousness"]]],"6119":["(Bagaimana pendapatmu jika orang yang melarang itu mendustakannya) yakni mendustakan Nabi saw. (dan berpaling) dari iman?",[["أَرَءَيْتَ","Have you seen"],["إِن","if"],["كَذَّبَ","he denies"],["وَتَوَلَّىٰٓ","and turns away"]]],"6120":["(Tidakkah dia mengetahui bahwa sesungguhnya Allah melihat) apa yang dilakukannya itu; artinya Dia mengetahuinya, karena itu Dia kelak akan memberi balasan kepadanya dengan balasan yang setimpal. Maka sudah sepatutnya kamu hai orang yang diajak berbicara untuk merasa heran terhadap orang yang melarang itu, karena ia melarang Nabi melakukan salat, padahal orang yang dilarangnya itu berada dalam jalan hidayah dan memerintahkan untuk bertakwa. Yang amat mengherankan lagi ialah bahwa yang melarangnya itu mendustakannya dan berpaling dari iman.",[["أَلَمْ","Does not"],["يَعْلَم","he know"],["بِأَنَّ","that"],["ٱللَّهَ","Allah"],["يَرَىٰ","sees"]]],"6121":["(Sekali-kali tidaklah demikian) kalimat ini mengandung makna hardikan dan cegahan baginya (sungguh jika) huruf Lam di sini menunjukkan makna qasam atau sumpah (dia tidak berhenti) dari kekafiran yang dilakukannya itu (niscaya Kami akan tarik ubun-ubunnya) atau Kami akan seret dia masuk neraka dengan cara ditarik ubun-ubunnya.",[["كَلَّا","Nay"],["لَئِن","If"],["لَّمْ","not"],["يَنتَهِ","he desists"],["لَنَسْفَعًۢا","surely We will drag him"],["بِٱلنَّاصِيَةِ","by the forelock"]]],"6122":["(Yaitu ubun-ubun) lafal Naashiyatan adalah isim Nakirah yang berkedudukan menjadi Badal dari isim Ma'rifat yaitu lafal An-Naashiyah pada ayat sebelumnya (orang yang mendustakan lagi durhaka) makna yang dimaksud adalah pelakunya; dia disifati demikian secara Majaz.",[["نَاصِيَةٍۢ","A forelock"],["كَـٰذِبَةٍ","lying"],["خَاطِئَةٍۢ","sinful"]]],"6123":["(Maka biarlah dia memanggil golongannya) yakni teman-teman senadinya; Nadi adalah sebuah majelis tempat mereka memusyawarahkan sesuatu perkara. Sesungguhnya orang yang melarang itu mengatakan kepada Nabi saw. sewaktu dia mencegahnya dari melakukan salat, \"Sesungguhnya aku telah mengetahui bahwa tiada seseorang pun di Mekah ini yang lebih banyak teman senadinya daripada aku. Sesungguhnya jika kamu mau meninggalkan salat, aku benar-benar akan memberikan kepadamu, kuda-kuda yang tak berpelana dan laki-laki pelayan sepenuh lembah ini.\"",[["فَلْيَدْعُ","Then let him call"],["نَادِيَهُۥ","his associates"]]],"6124":["(Kelak Kami akan memanggil malaikat Zabaniyah) mereka adalah malaikat-malaikat yang terkenal sangat bengis lagi kejam, untuk membinasakannya, sebagaimana yang telah disebutkan di dalam salah satu hadis, yaitu, \"Seandainya dia benar-benar memanggil golongan senadinya, niscaya dia akan diazab oleh malaikat Zabaniyah secara terang-terangan.\"",[["سَنَدْعُ","We will call"],["ٱلزَّبَانِيَةَ","the Angels of Hell"]]],"6125":["(Sekali-kali tidaklah demikian) kalimat ini mengandung hardikan dan cegahan baginya (janganlah kamu patuhi dia) hai Muhammad untuk meninggalkan salat (dan sujudlah) maksudnya salatlah demi karena Allah (dan mendekatlah) kepada-Nya dengan melalui amal ketaatan.",[["كَلَّا","Nay"],["لَا","(Do) not"],["تُطِعْهُ","obey him"],["وَٱسْجُدْ","But prostrate"],["وَٱقْتَرِب ۩","and draw near (to Allah)"]]],"6126":["(Sesungguhnya Kami telah menurunkannya) yaitu menurunkan Alquran seluruhnya secara sekali turun dari lohmahfuz hingga ke langit yang paling bawah (pada malam kemuliaan) yaitu malam Lailatulkadar, malam yang penuh dengan kemuliaan dan kebesaran.",[["إِنَّآ","Indeed, We"],["أَنزَلْنَـٰهُ","revealed it"],["فِى","in"],["لَيْلَةِ","(the) Night"],["ٱلْقَدْرِ","(of) Power"]]],"6127":["(Dan tahukah kamu) Hai Muhammad (apakah malam kemuliaan itu?) ungkapan ini sebagai pernyataan takjub atas keagungan yang terdapat pada Lailatulkadar.",[["وَمَآ","And what"],["أَدْرَىٰكَ","can make you know"],["مَا","what"],["لَيْلَةُ","(the) Night"],["ٱلْقَدْرِ","(of) Power (is)"]]],"6128":["(Malam kemuliaan itu lebih baik daripada seribu bulan) yang tidak ada malam lailatulkadarnya; beramal saleh pada malam itu pahalanya jauh lebih besar dan lebih baik daripada beramal saleh yang dilakukan selama seribu bulan yang tidak mengandung malam lailatulkadar.",[["لَيْلَةُ","(The) Night"],["ٱلْقَدْرِ","(of) Power"],["خَيْرٌۭ","(is) better"],["مِّنْ","than"],["أَلْفِ","a thousand"],["شَهْرٍۢ","month(s)"]]],"6129":["(Turunlah malaikat-malaikat) bentuk asal dari lafal Tanazzalu adalah Tatanazzalu, kemudian salah satu huruf Ta-nya dibuang, sehingga jadilah Tanazzalu (dan Ar-Ruh) yakni malaikat Jibril (di malam itu) artinya pada malam kemuliaan/lailatulkadar itu (dengan izin Rabbnya) dengan perintah dari-Nya (untuk mengatur segala urusan) atau untuk menjalankan ketetapan Allah buat tahun itu hingga tahun berikutnya, hal ini terjadi pada malam kemuliaan itu. Huruf Min di sini bermakna Sababiyah atau sama artinya dengan huruf Ba; yakni mereka turun dengan seizin Rabbnya dengan membawa segala urusan yang telah menjadi ketetapan-Nya untuk tahun itu hingga tahun berikutnya.",[["تَنَزَّلُ","Descend"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["وَٱلرُّوحُ","and the Spirit"],["فِيهَا","therein"],["بِإِذْنِ","by (the) permission"],["رَبِّهِم","(of) their Lord"],["مِّن","for"],["كُلِّ","every"],["أَمْرٍۢ","affair"]]],"6130":["(Malam itu penuh dengan kesejahteraan) lafal ayat ini sebagai Khabar Muqaddam atau Khabar yang didahulukan, sedangkan Mubtadanya ialah (sampai terbit fajar) dapat dibaca Mathla'al Fajri dan Mathla'il Fajri, artinya hingga waktu fajar. Malam itu dinamakan sebagai malam yang penuh dengan kesejahteraan, karena para malaikat banyak mengucapkan salam, yaitu setiap kali melewati seorang mukmin baik laki-laki maupun perempuan mereka selalu mengucapkan salam kepadanya.",[["سَلَـٰمٌ","Peace"],["هِىَ","it (is)"],["حَتَّىٰ","until"],["مَطْلَعِ","(the) emergence"],["ٱلْفَجْرِ","(of) the dawn"]]],"6131":["(Tiadalah orang-orang yang kafir dari) huruf Min di sini mengandung makna penjelasan (kalangan ahlulkitab dan orang-orang musyrik) orang-orang musyrik artinya orang-orang yang menyembah berhala; lafal Musyrikiina di'athafkan kepada lafal Ahlilkitaabi (mau meninggalkan) agamanya; lafal Munfakkiina sebagai Khabar dari lafal Yakun; artinya mereka akan tetap memegang agama yang mereka peluk (sebelum datang kepada mereka) artinya sampai datang kepada mereka (bukti yang nyata) berupa hujah yang jelas, yang dimaksud adalah Nabi Muhammad saw.",[["لَمْ","Not"],["يَكُنِ","were"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["مِنْ","from"],["أَهْلِ","(the) People"],["ٱلْكِتَـٰبِ","of the Book"],["وَٱلْمُشْرِكِينَ","and the polytheists"],["مُنفَكِّينَ","to be abandoned"],["حَتَّىٰ","until"],["تَأْتِيَهُمُ","(there) comes to them"],["ٱلْبَيِّنَةُ","the clear evidence"]]],"6132":["(Yaitu seorang rasul dari Allah) lafal ayat ini menjadi Badal dari lafal Al-Bayyinah, yang dimaksud adalah Nabi Muhammad saw. (yang membacakan lembaran-lembaran yang disucikan) dari segala bentuk kebatilan.",[["رَسُولٌۭ","A Messenger"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["يَتْلُوا۟","reciting"],["صُحُفًۭا","pages"],["مُّطَهَّرَةًۭ","purified"]]],"6133":["(Di dalamnya terdapat kitab-kitab) maksudnya hukum-hukum yang tertulis (yang lurus) artinya hukum-hukum yang lurus. Dia akan membacakan apa yang dikandungnya, yaitu Alquran; di antara mereka ada orang-orang yang beriman kepadanya dan ada pula orang-orang yang kafir kepadanya.",[["فِيهَا","Wherein"],["كُتُبٌۭ","(are) writings"],["قَيِّمَةٌۭ","correct"]]],"6134":["(Dan tidaklah berpecah belah orang-orang yang didatangkan Alkitab) kepada mereka sehubungan dengan masalah iman kepada Nabi Muhammad saw. (melainkan sesudah datang kepada mereka bukti yang nyata) yaitu setelah datang kepada mereka Nabi Muhammad saw., atau Alquran yang dibawa olehnya sebagai mukjizat baginya. Sebelum kedatangan Nabi Muhammad saw. mereka adalah orang-orang yang sepakat untuk beriman kepadanya/Nabi Muhammad tetapi setelah Nabi Muhammad saw. datang kepada mereka, tiba-tiba mereka mengingkarinya, terutama orang-orang yang dengki dari kalangan mereka.",[["وَمَا","And not"],["تَفَرَّقَ","became divided"],["ٱلَّذِينَ","those who"],["أُوتُوا۟","were given"],["ٱلْكِتَـٰبَ","the Book"],["إِلَّا","until"],["مِنۢ","from"],["بَعْدِ","after"],["مَا","what"],["جَآءَتْهُمُ","came (to) them"],["ٱلْبَيِّنَةُ","(of) the clear evidence"]]],"6135":["(Padahal mereka tidak disuruh) di dalam kitab-kitab mereka yaitu Taurat dan Injil (kecuali menyembah Allah) kecuali supaya menyembah Allah, pada asalnya adalah An Ya'budullaaha, lalu huruf An dibuang dan ditambahkan huruf Lam sehingga jadilah Liya'budullaaha (dengan memurnikan ketaatan kepada-Nya dalam beragama) artinya membersihkannya dari kemusyrikan (dengan lurus) maksudnya berpegang teguh pada agama Nabi Ibrahim dan agama Nabi Muhammad bila telah datang nanti. Maka mengapa sewaktu ia datang mereka menjadi jadi ingkar kepadanya (dan supaya mereka mendirikan salat dan menunaikan zakat; dan yang demikian itulah agama) atau tuntunan (yang mustaqim) yang lurus.",[["وَمَآ","And not"],["أُمِرُوٓا۟","they were commanded"],["إِلَّا","except"],["لِيَعْبُدُوا۟","to worship"],["ٱللَّهَ","Allah"],["مُخْلِصِينَ","(being) sincere"],["لَهُ","to Him"],["ٱلدِّينَ","(in) the religion"],["حُنَفَآءَ","upright"],["وَيُقِيمُوا۟","and to establish"],["ٱلصَّلَوٰةَ","the prayer"],["وَيُؤْتُوا۟","and to give"],["ٱلزَّكَوٰةَ ۚ","the zakah"],["وَذَٰلِكَ","And that"],["دِينُ","(is the) religion"],["ٱلْقَيِّمَةِ","the correct"]]],"6136":["(Sesungguhnya orang-orang kafir dari ahli kitab dan orang-orang musyrik -dimasukkan- ke dalam neraka Jahanam; mereka kekal di dalamnya) lafal Khaalidiina menjadi Haal atau kata keterangan keadaan dari lafal yang tidak disebutkan; lengkapnya mereka telah dipastikan oleh Allah swt. untuk menjadi penghuni tetap di dalam neraka Jahanam untuk selama-lamanya. (Mereka itu adalah seburuk-buruk makhluk.)",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["مِنْ","from"],["أَهْلِ","(the) People"],["ٱلْكِتَـٰبِ","(of) the Book"],["وَٱلْمُشْرِكِينَ","and the polytheists"],["فِى","(will be) in"],["نَارِ","(the) Fire"],["جَهَنَّمَ","(of) Hell"],["خَـٰلِدِينَ","abiding eternally"],["فِيهَآ ۚ","therein"],["أُو۟لَـٰٓئِكَ","Those "],["هُمْ","they"],["شَرُّ","(are the) worst"],["ٱلْبَرِيَّةِ","(of) the creatures"]]],"6137":["(Sesungguhnya orang-orang yang beriman dan mengerjakan amal saleh mereka itu adalah sebaik-baik makhluk) artinya makhluk yang paling baik.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["أُو۟لَـٰٓئِكَ","those "],["هُمْ","they"],["خَيْرُ","(are the) best"],["ٱلْبَرِيَّةِ","(of) the creatures"]]],"6138":["(Balasan mereka di sisi Rabb mereka ialah surga 'Adn) sebagai tempat tinggal tetap mereka (yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya selama-lamanya. Allah rida terhadap mereka) karena ketaatan mereka kepada-Nya (dan mereka pun rida kepada-Nya) yakni merasa puas akan pahala-Nya. (Yang demikian itu adalah balasan bagi orang yang takut kepada Rabbnya) maksudnya takut kepada siksaan-Nya, yang karena itu lalu ia berhenti dari mendurhakai-Nya.",[["جَزَآؤُهُمْ","Their reward"],["عِندَ","(is) with"],["رَبِّهِمْ","their Lord "],["جَنَّـٰتُ","Gardens"],["عَدْنٍۢ","(of) Eternity"],["تَجْرِى","flow"],["مِن","from"],["تَحْتِهَا","underneath them"],["ٱلْأَنْهَـٰرُ","the rivers"],["خَـٰلِدِينَ","will abide"],["فِيهَآ","therein"],["أَبَدًۭا ۖ","forever"],["رَّضِىَ","(will be) pleased"],["ٱللَّهُ","Allah"],["عَنْهُمْ","with them"],["وَرَضُوا۟","and they (will be) pleased"],["عَنْهُ ۚ","with Him"],["ذَٰلِكَ","That"],["لِمَنْ","(is) for whoever"],["خَشِىَ","feared"],["رَبَّهُۥ","his Lord"]]],"6139":["(Apabila bumi diguncangkan) yaitu mengalami gempa di saat hari kiamat tiba (dengan guncangannya) yang amat dahsyat sesuai dengan bentuknya yang besar.",[["إِذَا","When"],["زُلْزِلَتِ","is shaken"],["ٱلْأَرْضُ","the earth"],["زِلْزَالَهَا","(with) its earthquake"]]],"6140":["(Dan bumi telah mengeluarkan beban-beban beratnya) berupa semua perbendaharaan yang dikandungnya termasuk orang-orang mati, kemudian semuanya itu dicampakkan ke permukaannya.",[["وَأَخْرَجَتِ","And brings forth"],["ٱلْأَرْضُ","the earth"],["أَثْقَالَهَا","its burdens"]]],"6141":["(Dan manusia bertanya) yakni orang yang ingkar kepada adanya hari berbangkit (\"Mengapa bumi jadi begini?\") ia mengatakan demikian dengan nada ingkar kepada kenyataan yang sedang mereka alami ketika itu, yaitu keadaan menjelang hari kiamat.",[["وَقَالَ","And says"],["ٱلْإِنسَـٰنُ","man"],["مَا","What"],["لَهَا","(is) with it"]]],"6142":["(Pada hari itu) menjadi Badal dari lafal Idzaa berikut Jawabnya (bumi menceritakan beritanya) yaitu menceritakan semua amal perbuatan yang telah dilakukan di atas permukaannya, amal baik dan amal buruk.",[["يَوْمَئِذٍۢ","That Day"],["تُحَدِّثُ","it will report"],["أَخْبَارَهَا","its news"]]],"6143":["(Karena sesungguhnya) hal itu terjadi disebabkan karena (Rabbmu telah memerintahkan kepadanya) yang demikian itu. Di dalam sebuah hadis disebutkan, \"Setiap hamba laki-laki dan perempuan menyaksikan (pada hari itu) semua amal perbuatan yang telah dilakukannya di muka bumi.\"",[["بِأَنَّ","Because"],["رَبَّكَ","your Lord"],["أَوْحَىٰ","inspired"],["لَهَا","[to] it"]]],"6144":["(Pada hari itu manusia keluar) maksudnya mereka berangkat meninggalkan tempat penghisaban (dalam keadaan yang bermacam-macam) yakni terpisah-pisah; ada yang mengambil jalan ke kanan yaitu menuju ke surga dan ada yang mengambil jalan ke kiri yaitu menuju ke neraka (supaya diperlihatkan kepada mereka pekerjaan mereka) maksudnya balasan amal perbuatan mereka, berupa surga atau neraka.",[["يَوْمَئِذٍۢ","That Day"],["يَصْدُرُ","will proceed"],["ٱلنَّاسُ","the mankind"],["أَشْتَاتًۭا","(in) scattered groups"],["لِّيُرَوْا۟","to be shown"],["أَعْمَـٰلَهُمْ","their deeds"]]],"6145":["(Maka barang siapa yang mengerjakan seberat zarah) atau seberat semut yang paling kecil (kebaikan, niscaya dia akan melihatnya) melihat pahalanya.",[["فَمَن","So whoever"],["يَعْمَلْ","does"],["مِثْقَالَ","(equal to the) weight"],["ذَرَّةٍ","(of) an atom"],["خَيْرًۭا","good"],["يَرَهُۥ","will see it"]]],"6146":["(Dan barang siapa yang mengerjakan kejahatan seberat zarah pun, niscaya dia akan melihatnya pula) artinya dia pasti akan merasakan balasannya.",[["وَمَن","And whoever"],["يَعْمَلْ","does"],["مِثْقَالَ","(equal to the) weight"],["ذَرَّةٍۢ","(of) an atom"],["شَرًّۭا","evil"],["يَرَهُۥ","will see it"]]],"6147":["(Demi yang berlari kencang) di dalam perang, yaitu kuda yang lari dengan kencangnya di dalam peperangan (dengan terengah-engah) lafal Adh-Dhabhu artinya suara napas kuda sewaktu berlari kencang.",[["وَٱلْعَـٰدِيَـٰتِ","By the racers"],["ضَبْحًۭا","panting"]]],"6148":["(Dan demi yang mencetuskan api) maksudnya kuda yang memercikkan api (dengan pukulan) teracak kakinya apabila ia berlari di tanah yang banyak batunya pada malam hari.",[["فَٱلْمُورِيَـٰتِ","And the producers of sparks"],["قَدْحًۭا","striking"]]],"6149":["(Dan demi yang menyerang dengan tiba-tiba di waktu pagi) yaitu kuda yang menyerang musuh di waktu pagi, karena pengendaranya melakukan penyerbuan di waktu tersebut.",[["فَٱلْمُغِيرَٰتِ","And the chargers"],["صُبْحًۭا","(at) dawn"]]],"6150":["(Maka ia menerbangkan) atau mengepulkan (di waktu itu) di waktu tersebut, atau di tempat ia berlari (debu) karena gerakannya yang sangat keras.",[["فَأَثَرْنَ","Then raise"],["بِهِۦ","thereby"],["نَقْعًۭا","dust"]]],"6151":["(Dan menyerbu dalam kepulan debu ke tengah-tengah) artinya dengan membawa kepulan debu (kumpulan musuh) yang diserangnya; maksudnya kuda-kuda tersebut berada di tengah-tengah musuh dalam keadaan menyerang. Lafal Fawasathna yang kedudukannya sebagai Fi'il di'athafkan kepada Isim, karena mengingat bahwa semua Isim yang di'athafkan kepadanya mengandung makna Fi'il pula. Yakni demi yang berlari kencang, lalu mencetuskan api, lalu menerbangkan debu.",[["فَوَسَطْنَ","Then penetrate (in the) center"],["بِهِۦ","thereby"],["جَمْعًا","collectively"]]],"6152":["(Sesungguhnya manusia itu) yang dimaksud adalah manusia yang kafir (sangat ingkar kepada Rabbnya) artinya ia mengingkari semua nikmat-Nya yang telah dilimpahkan kepadanya.",[["إِنَّ","Indeed"],["ٱلْإِنسَـٰنَ","mankind"],["لِرَبِّهِۦ","to his Lord"],["لَكَنُودٌۭ","(is) surely ungrateful"]]],"6153":["(Dan sesungguhnya manusia itu terhadap hal tersebut) terhadap keingkarannya (menyaksikan sendiri) atau dia menyaksikan bahwa dirinya telah berbuat ingkar.",[["وَإِنَّهُۥ","And indeed, he"],["عَلَىٰ","on"],["ذَٰلِكَ","that"],["لَشَهِيدٌۭ","surely (is) a witness"]]],"6154":["(Dan sesungguhnya karena cintanya kepada kebaikan) maksudnya cinta atas harta benda (dia sangat bakhil) artinya lantaran sangat mencintai harta, jadilah ia seorang yang amat bakhil atau kikir.",[["وَإِنَّهُۥ","And indeed he"],["لِحُبِّ","in (the) love"],["ٱلْخَيْرِ","(of) wealth"],["لَشَدِيدٌ","(is) surely intense"]]],"6155":["(Maka apakah dia tidak mengetahui apabila dibangkitkan) dibangunkan dan dikeluarkan (apa yang ada dalam kubur) yakni orang-orang mati yang dikubur di dalamnya.",[["۞ أَفَلَا","But does not"],["يَعْلَمُ","he know"],["إِذَا","when"],["بُعْثِرَ","will be scattered"],["مَا","what"],["فِى","(is) in"],["ٱلْقُبُورِ","the graves"]]],"6156":["(Dan dilahirkan) atau ditampakkan dan dikeluarkan (apa yang ada dalam dada) maksudnya, apa yang tersimpan di dalam kalbu berupa kekafiran dan keimanan.",[["وَحُصِّلَ","And is made apparent"],["مَا","what"],["فِى","(is) in"],["ٱلصُّدُورِ","the breasts"]]],"6157":["(Sesungguhnya Rabb mereka pada hari itu Maha Mengetahui keadaan mereka) karena itu Dia akan memberikan balasan kepada mereka atas kekafiran mereka. Di sini Dhamir diulangi penyebutannya dalam bentuk jamak, hal ini tiada lain karena memandang segi makna yang dikandung lafal Al-Insaan. Jumlah ayat ini menunjukkan pengertian Maf'ul bagi lafal Ya'lamu; artinya sesungguhnya Kami akan memberikan balasan kepadanya pada saat itu. Berta'alluqnya lafal Khabiirun kepada lafal Yaumaidzin memberikan pengertian, bahwa hari itu adalah hari pembalasan, karena sesungguhnya Allah selama-lamanya Maha Mengetahui.",[["إِنَّ","Indeed"],["رَبَّهُم","their Lord"],["بِهِمْ","about them"],["يَوْمَئِذٍۢ","that Day"],["لَّخَبِيرٌۢ","(is) surely All-Aware"]]],"6158":["(Hari kiamat) dinamakan Al-Qaari'ah karena kengerian-kengerian yang terjadi di dalamnya sangat menggentarkan kalbu.",[["ٱلْقَارِعَةُ","The Striking Calamity"]]],"6159":["(Apakah hari kiamat itu?) ungkapan ini menggambarkan tentang kengeriannya; ayat yang pertama dan ayat yang kedua merupakan Mubtada dan Khabarnya.",[["مَا","What"],["ٱلْقَارِعَةُ","(is) the Striking Calamity"]]],"6160":["(Tahukah kamu) atau apakah kamu tahu (apakah hari kiamat itu?) ungkapan ayat ini menambah kengerian yang terdapat di hari kiamat. Lafal Maa yang pertama adalah Mubtada sedangkan lafal sesudahnya yaitu lafal Adraaka merupakan Khabarnya; dan Maa yang kedua berikut Khabarnya berkedudukan sebagai Maf'ul kedua dari lafal Adraa.",[["وَمَآ","And what"],["أَدْرَىٰكَ","will make you know"],["مَا","what"],["ٱلْقَارِعَةُ","(is) the Striking Calamity"]]],"6161":["(Pada hari itu) dinashabkan oleh lafal yang disimpulkan dari pengertian yang terkandung di dalam lafal Al-Qaari'ah yakni lafal Taqra'u, artinya pada hari yang menggentarkan itu (manusia adalah seperti anai-anai yang dihambur-hamburkan) atau seakan-akan belalang-belalang yang dihambur-hamburkan; sebagian di antaranya terbang beriring-iringan dengan yang lainnya secara semrawut. Demikian itu karena mereka dalam keadaan kebingungan, hal ini terus berlangsung hingga mereka dipanggil untuk menjalani perhitungan amal perbuatan.",[["يَوْمَ","(The) Day"],["يَكُونُ","will be"],["ٱلنَّاسُ","the mankind"],["كَٱلْفَرَاشِ","like moths"],["ٱلْمَبْثُوثِ","scattered"]]],"6162":["(Dan gunung-gunung adalah seperti bulu yang dihambur-hamburkan) atau bagaikan wool yang terhambur-hamburkan, karena ringannya, sehingga jatuh kembali rata dengan tanah.",[["وَتَكُونُ","And will be"],["ٱلْجِبَالُ","the mountains"],["كَٱلْعِهْنِ","like wool"],["ٱلْمَنفُوشِ","fluffed up"]]],"6163":["(Dan adapun orang yang berat timbangannya) artinya amal kebaikannya lebih berat daripada amal keburukannya.",[["فَأَمَّا","Then as for"],["مَن","(him) whose"],["ثَقُلَتْ","(are) heavy"],["مَوَٰزِينُهُۥ","his scales"]]],"6164":["(Maka dia berada dalam kehidupan yang memuaskan) yaitu berada di dalam surga; atau dengan kata lain kehidupan yang diterimanya itu sangat memuaskannya.",[["فَهُوَ","Then he"],["فِى","(will be) in"],["عِيشَةٍۢ","a life"],["رَّاضِيَةٍۢ","pleasant"]]],"6165":["(Dan adapun orang yang ringan timbangannya) artinya amal keburukannya lebih berat daripada amal kebaikannya.",[["وَأَمَّا","But as for"],["مَنْ","(him) whose"],["خَفَّتْ","(are) light"],["مَوَٰزِينُهُۥ","his scales"]]],"6166":["(Maka tempat kembalinya) yaitu tempat tinggalnya (adalah neraka Haawiyah.)",[["فَأُمُّهُۥ","His abode"],["هَاوِيَةٌۭ","(will be the) Pit"]]],"6167":["(Dan tahukah kamu, apakah Haawiyah itu?) atau apakah neraka Haawiyah itu?",[["وَمَآ","And what"],["أَدْرَىٰكَ","will make you know"],["مَا","what"],["هِيَهْ","it is"]]],"6168":["Neraka Haawiyah itu adalah (api yang sangat panas) yang panasnya luar biasa; huruf Ha yang terdapat pada lafal Hiyah adalah Ha Sakat, baik dalam keadaan Washal ataupun Waqaf tetap dibaca. Tetapi menurut suatu qiraat tidak dibaca bila dalam keadaan Washal.",[["نَارٌ","A Fire"],["حَامِيَةٌۢ","intensely hot"]]],"6169":["(Telah membuat kalian lalai) atau telah melalaikan kalian dari taat kepada Allah (bermegah-megahan) yaitu saling bangga-membanggakan harta, anak-anak dan pembantu-pembantu.",[["أَلْهَىٰكُمُ","Diverts you"],["ٱلتَّكَاثُرُ","the competition to increase"]]],"6170":["(Sampai kalian masuk ke dalam kubur) hingga kalian mati dikubur di dalam tanah; atau hingga kalian menghitung-hitung banyaknya orang yang telah mati.",[["حَتَّىٰ","Until"],["زُرْتُمُ","you visit"],["ٱلْمَقَابِرَ","the graves"]]],"6171":["(Janganlah begitu) kalimat ini mengandung hardikan dan cegahan (kelak kalian akan mengetahui.)",[["كَلَّا","Nay"],["سَوْفَ","Soon"],["تَعْلَمُونَ","you will know"]]],"6172":["(Dan janganlah begitu, kelak kalian akan mengetahui) akibat buruk dari perbuatan kalian itu di kala kalian menjelang kematian, kemudian sewaktu kalian telah berada di dalam kubur.",[["ثُمَّ","Then"],["كَلَّا","nay"],["سَوْفَ","Soon"],["تَعْلَمُونَ","you will know"]]],"6173":["(Janganlah begitu) sesungguhnya (jika kalian mengetahui dengan pengetahuan yang yakin) tentang akibat perbuatan kalian itu, niscaya kalian tidak akan lalai taat kepada Allah.",[["كَلَّا","Nay"],["لَوْ","If"],["تَعْلَمُونَ","you know"],["عِلْمَ","(with) a knowledge"],["ٱلْيَقِينِ","(of) certainty"]]],"6174":["(Niscaya kalian benar-benar akan melihat neraka Jahim) Jawab Qasamnya tidak disebutkan, yaitu niscaya kalian tidak akan sibuk dengan bermegah-megahan yang melalaikan kalian dari taat kepada Allah. Lafal Latarawunna pada asalnya adalah Latarawunanna, kemudian Lam Fi'il dan 'Ain Fi'ilnya dibuang, kemudian harakatnya diberikan kepada Wau, sehingga jadilah Latarawunna.",[["لَتَرَوُنَّ","Surely you will see"],["ٱلْجَحِيمَ","the Hellfire"]]],"6175":["(Dan sesungguhnya kalian benar-benar akan melihatnya) kalimat ayat ini mengukuhkan makna ayat sebelumnya (dengan pengetahuan yang yakin) lafal 'Ainal Yaqiin adalah Mashdar; demikian itu karena lafal Ra-aa dan lafal 'Aayana mempunyai arti yang sama.",[["ثُمَّ","Then"],["لَتَرَوُنَّهَا","surely you will see it"],["عَيْنَ","(with the) eye"],["ٱلْيَقِينِ","(of) certainty"]]],"6176":["(Kemudian kalian pasti akan ditanyai) lafal Latus-alunna dibuang daripadanya Nun alamat Rafa' karena berturut-turutnya huruf Nun, dibuang pula daripadanya Wawu dhamir jamak, tetapi bukan karena 'Illat atau sebab bertemunya kedua huruf yang disukunkan; bentuk asal daripada Latus-alunna adalah Latus-aluunanna (pada hari itu) yakni di hari kalian melihat neraka Jahim (tentang kenikmatan) yang kalian peroleh semasa di dunia, yaitu berupa kesehatan, waktu luang, keamanan, makanan, minuman dan nikmat-nikmat lainnya. Artinya dipergunakan untuk apakah kenikmatan itu?",[["ثُمَّ","Then"],["لَتُسْـَٔلُنَّ","surely you will be asked"],["يَوْمَئِذٍ","that Day"],["عَنِ","about"],["ٱلنَّعِيمِ","the pleasures"]]],"6177":["(Demi masa) atau zaman atau waktu yang dimulai dari tergelincirnya matahari hingga terbenamnya; maksudnya adalah waktu salat Asar.",[["وَٱلْعَصْرِ","By the time"]]],"6178":["(Sesungguhnya manusia itu) yang dimaksud adalah jenis manusia (benar-benar berada dalam kerugian) di dalam perniagaannya.",[["إِنَّ","Indeed"],["ٱلْإِنسَـٰنَ","mankind"],["لَفِى","(is) surely, in"],["خُسْرٍ","loss"]]],"6179":["(Kecuali orang-orang yang beriman dan mengerjakan amal saleh) mereka tidak termasuk orang-orang yang merugi di dalam perniagaannya (dan nasihat-menasihati) artinya sebagian di antara mereka menasihati sebagian yang lainnya (supaya menaati kebenaran) yaitu iman (dan nasihat-menasihati dengan kesabaran) yaitu di dalam menjalankan amal ketaatan dan menjauhi kemaksiatan.",[["إِلَّا","Except"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["وَتَوَاصَوْا۟","and enjoin (each other)"],["بِٱلْحَقِّ","to the truth"],["وَتَوَاصَوْا۟","and enjoin (each other)"],["بِٱلصَّبْرِ","to [the] patience"]]],"6180":["(Kecelakaanlah) lafal Al-Wail ini adalah kalimat kutukan, atau nama sebuah lembah di neraka Jahanam (bagi setiap pengumpat lagi pencela) artinya yang banyak mengumpat dan banyak mencela. Ayat ini diturunkan berkenaan dengan orang-orang yang suka mengumpat Nabi saw. dan orang-orang mukmin, seperti Umaiyah bin Khalaf, Walid bin Mughirah dan lain-lainnya.",[["وَيْلٌۭ","Woe"],["لِّكُلِّ","to every"],["هُمَزَةٍۢ","slanderer"],["لُّمَزَةٍ","backbiter"]]],"6181":["(Yang mengumpulkan) dapat dibaca Jama'a dan Jamma'a (harta dan menghitung-hitungnya) dan menjadikannya sebagai bekal untuk menghadapi bencana dan malapetaka.",[["ٱلَّذِى","The one who"],["جَمَعَ","collects"],["مَالًۭا","wealth"],["وَعَدَّدَهُۥ","and counts it"]]],"6182":["(Dia menduga) karena kebodohannya (bahwa hartanya itu dapat mengekalkannya) dapat menjadikannya hidup kekal dan tidak mati.",[["يَحْسَبُ","Thinking"],["أَنَّ","that"],["مَالَهُۥٓ","his wealth"],["أَخْلَدَهُۥ","will make him immortal"]]],"6183":["(Sekali-kali tidak!) kalimat ini mengandung makna sanggahan. (Sesungguhnya dia benar-benar akan dilemparkan) menjadi Jawab Qasam dari lafal yang tidak disebutkan; artinya sesungguhnya dia benar-benar akan dicampakkan (ke dalam Huthamah) dan segala sesuatu yang dimasukkan ke dalamnya pasti hancur berkeping-keping.",[["كَلَّا ۖ","Nay"],["لَيُنۢبَذَنَّ","Surely he will be thrown"],["فِى","in"],["ٱلْحُطَمَةِ","the Crusher"]]],"6184":["(Dan tahukah kamu) atau apakah kamu mengetahui (apa Huthamah itu?)",[["وَمَآ","And what"],["أَدْرَىٰكَ","will make you know"],["مَا","what"],["ٱلْحُطَمَةُ","the Crusher (is)"]]],"6185":["(Yaitu api -yang disediakan- Allah yang dinyalakan) yang dinyalakan dengan besarnya.",[["نَارُ","A Fire"],["ٱللَّهِ","Allah"],["ٱلْمُوقَدَةُ","kindled"]]],"6186":["(Yang naik) maksudnya panasnya naik membakar (sampai ke hati) lalu membakarnya; rasa sakit yang diakibatkan api neraka jauh lebih memedihkan daripada api lainnya, karena api neraka sangat lembut dan dapat memasuki pori-pori, lalu membakar hati.",[["ٱلَّتِى","Which"],["تَطَّلِعُ","mounts up"],["عَلَى","to"],["ٱلْأَفْـِٔدَةِ","the hearts"]]],"6187":["(Sesungguhnya api itu atas mereka) di dalam ayat ini Dhamir dijamakkan karena memandang dari segi makna (ditutup rapat-rapat) dapat dibaca Mu`shadah dan Muushadah; artinya mereka dibakar dengan api itu dalam keadaan ditutup rapat.",[["إِنَّهَا","Indeed, it"],["عَلَيْهِم","(will be) upon them"],["مُّؤْصَدَةٌۭ","closed over"]]],"6188":["(Pada tiang-tiang) dapat dibaca 'Amadin dan 'Umudin (yang panjang) lafal ini menjadi sifat dari lafal sebelumnya; dengan demikian maka api itu berada dalam tiang-tiang tersebut.",[["فِى","In"],["عَمَدٍۢ","columns"],["مُّمَدَّدَةٍۭ","extended"]]],"6189":["(Apakah kamu tidak memperhatikan) Istifham atau kata tanya di sini mengandung makna takjub; artinya sepatutnya kamu merasa takjub (bagaimana Rabbmu telah bertindak terhadap tentara bergajah) orang yang mempunyai gajah itu bernama Mahmud yang disertai oleh teman-temannya, yaitu raja negeri Yaman yang bernama Abrahah berikut tentaranya. Dia telah membangun sebuah gereja di Shan'a dengan tujuan supaya orang-orang berpaling dari menziarahi Mekah dan tidak menziarahinya lagi. Pada suatu hari ada seseorang lelaki dari Kinanah telah membuat kejadian di gereja tersebut, ia melumuri bagian gereja yang dijadikan kiblat dengan kotoran unta dengan maksud menghinanya. Abrahah bersumpah untuk menghancurkan Kakbah. Lalu ia datang ke Mekah bersama tentaranya, beserta gajah-gajah milik Mahmud tadi. Ketika mereka mulai bergerak hendak menghancurkan Kakbah, Allah mengirimkan kepada mereka apa yang dikisahkan-Nya melalui firman selanjutnya yaitu:",[["أَلَمْ","Have not"],["تَرَ","you seen"],["كَيْفَ","how"],["فَعَلَ","dealt"],["رَبُّكَ","your Lord"],["بِأَصْحَـٰبِ","with (the) Companions"],["ٱلْفِيلِ","(of the) Elephant"]]],"6190":["(Bukankah Dia menjadikan) telah menjadikan (tipu daya mereka itu) dalam rangka menghancurkan Kakbah (sia-sia) maksudnya hanya menjerumuskan mereka ke dalam kerugian dan kebinasaan.",[["أَلَمْ","Did not"],["يَجْعَلْ","He make"],["كَيْدَهُمْ","their plan"],["فِى","go"],["تَضْلِيلٍۢ","astray"]]],"6191":["(Dan Dia mengirimkan kepada mereka burung yang berbondong-bondong) atau yang bergelombang secara berturut-turut. Menurut suatu pendapat bahwa lafal Abaabiil ini tidak ada bentuk Mufradnya, sama halnya dengan lafal Asaathiir. Menurut pendapat yang lain bahwa bentuk tunggalnya adalah Abuul atau Ibaal atau Ibbiil yang wazannya sama dengan 'Ajuul, Miftaah dan Sikkiin.",[["وَأَرْسَلَ","And He sent"],["عَلَيْهِمْ","against them"],["طَيْرًا","birds"],["أَبَابِيلَ","(in) flocks"]]],"6192":["(Yang melempar mereka dengan batu berasal dari tanah yang terbakar) yakni tanah liat yang dibakar.",[["تَرْمِيهِم","Striking them"],["بِحِجَارَةٍۢ","with stones"],["مِّن","of"],["سِجِّيلٍۢ","baked clay"]]],"6193":["(Lalu Dia menjadikan mereka seperti daun-daun yang dimakan) atau bagaikan daun tanaman yang dimakan oleh ternak, kemudian diinjak-injak dan dicabik-cabiknya. Allah telah membinasakan setiap orang dari mereka dengan batu yang padanya telah tertulis nama orang yang dikenainya. Setiap batu bentuknya lebih besar sedikit daripada biji 'adasah dan agak kecil daripada biji kacang Humsh; batu itu dapat menembus topi baja tentara yang berjalan kaki dan gajah yang dibawanya, kemudian batu itu jatuh ke tanah setelah menembus badan mereka. Hal tersebut terjadi pada tahun kelahiran Nabi saw.",[["فَجَعَلَهُمْ","Then He made them"],["كَعَصْفٍۢ","like straw"],["مَّأْكُولٍۭ","eaten up"]]],"6194":["(Karena kebiasaan orang-orang Quraisy.)",[["لِإِيلَـٰفِ","For (the) familiarity"],["قُرَيْشٍ","(of the) Quraish"]]],"6195":["(Yaitu kebiasaan mereka) lafal ini mengukuhkan makna lafal sebelumnya (bepergian pada musim dingin) ke negeri Yaman (dan musim panas) ke negeri Syam dalam setiap tahunnya; mereka bepergian dengan tujuan untuk berniaga yang keuntungannya mereka gunakan untuk keperluan hidup mereka di Mekah dan untuk berkhidmat kepada Baitullah yang merupakan kebanggaan mereka; mereka yang melakukan demikian adalah anak-anak An-Nadhr bin Kinanah.",[["إِۦلَـٰفِهِمْ","Their familiarity"],["رِحْلَةَ","(with the) journey"],["ٱلشِّتَآءِ","(of) winter"],["وَٱلصَّيْفِ","and summer"]]],"6196":["(Maka hendaklah mereka menyembah) lafal ini menjadi ta'alluq atau tempat bergantung bagi lafal Li-iilaafi; sedangkan huruf Fa adalah huruf Zaidah (Rabb rumah ini.)",[["فَلْيَعْبُدُوا۟","So let them worship"],["رَبَّ","(the) Lord"],["هَـٰذَا","(of) this"],["ٱلْبَيْتِ","House"]]],"6197":["(Yang telah memberi makanan kepada mereka untuk menghilangkan lapar) agar mereka tidak kelaparan (dan mengamankan mereka dari ketakutan) artinya supaya mereka tidak merasa takut lagi. Sesungguhnya mereka sering mengalami kelaparan, karena di Mekah tidak terdapat lahan pertanian, sebagaimana mereka pun pernah dicekam oleh rasa takut, yaitu ketika tentara bergajah datang kepada mereka dengan maksud untuk menghancurkan Kakbah.",[["ٱلَّذِىٓ","The One Who"],["أَطْعَمَهُم","feeds them"],["مِّن","[from]"],["جُوعٍۢ","(against) hunger"],["وَءَامَنَهُم","and gives them security"],["مِّنْ","from"],["خَوْفٍۭ","fear"]]],"6198":["(Tahukah kamu orang yang mendustakan hari pembalasan?) atau adanya hari hisab dan hari pembalasan amal perbuatan. Maksudnya apakah kamu mengetahui orang itu? Jika kamu belum mengetahui:",[["أَرَءَيْتَ","Have you seen"],["ٱلَّذِى","the one who"],["يُكَذِّبُ","denies"],["بِٱلدِّينِ","the Judgment"]]],"6199":["(Maka dia itulah) sesudah huruf Fa ditetapkan adanya lafal Huwa, artinya maka dia itulah (orang yang menghardik anak yatim) yakni menolaknya dengan keras dan tidak mau memberikan hak yang seharusnya ia terima.",[["فَذَٰلِكَ","Then that"],["ٱلَّذِى","(is) the one who"],["يَدُعُّ","repulses"],["ٱلْيَتِيمَ","the orphan"]]],"6200":["(Dan tidak menganjurkan) dirinya atau orang lain (memberi makan orang miskin) ayat ini diturunkan berkenaan dengan orang yang bersikap demikian, yaitu Al-'Ash bin Wail atau Walid bin Mughirah.",[["وَلَا","And (does) not"],["يَحُضُّ","feel the urge"],["عَلَىٰ","to"],["طَعَامِ","feed"],["ٱلْمِسْكِينِ","the poor"]]],"6201":["(Maka kecelakaanlah bagi orang-orang yang salat.)",[["فَوَيْلٌۭ","So woe"],["لِّلْمُصَلِّينَ","to those who pray"]]],"6202":["(Yaitu orang-orang yang lalai dari salatnya) artinya mengakhirkan salat dari waktunya.",[["ٱلَّذِينَ","Those who"],["هُمْ","[they]"],["عَن","about"],["صَلَاتِهِمْ","their prayers"],["سَاهُونَ","(are) neglectful"]]],"6203":["(orang-orang yang berbuat ria) di dalam salatnya atau dalam hal-hal lainnya.",[["ٱلَّذِينَ","Those who"],["هُمْ","[they]"],["يُرَآءُونَ","make show"]]],"6204":["(Dan enggan menolong dengan barang yang berguna) artinya tidak mau meminjamkan barang-barang miliknya yang diperlukan orang lain; apalagi memberikannya, seperti jarum, kapak, kuali, mangkok dan sebagainya.",[["وَيَمْنَعُونَ","And they deny"],["ٱلْمَاعُونَ","[the] small kindnesses"]]],"6205":["(Sesungguhnya Kami telah memberikan kepadamu) hai Muhammad (Al-Kautsar) merupakan sebuah sungai di surga dan telaga milik Nabi saw. kelak akan menjadi tempat minum bagi umatnya. Al-Kautsar juga berarti kebaikan yang banyak, yaitu berupa kenabian, Alquran, syafaat dan lain sebagainya.",[["إِنَّآ","Indeed, We"],["أَعْطَيْنَـٰكَ","We have given you"],["ٱلْكَوْثَرَ","Al-Kauthar"]]],"6206":["(Maka dirikanlah salat karena Rabbmu) yaitu salat Hari Raya Kurban (dan berkurbanlah) untuk manasik hajimu.",[["فَصَلِّ","So pray"],["لِرَبِّكَ","to your Lord"],["وَٱنْحَرْ","and sacrifice"]]],"6207":["(Sesungguhnya orang-orang yang membenci kamu) yakni orang-orang yang tidak menyukai kamu (dialah yang terputus) terputus dari semua kebaikan; atau putus keturunannya. Ayat ini diturunkan berkenaan dengan orang yang bersikap demikian, dia adalah 'Ash bin Wail, sewaktu Nabi saw. ditinggal wafat putranya yang bernama Qasim, lalu 'Ash menjuluki Nabi sebagai Abtar yakni orang yang terputus keturunannya.",[["إِنَّ","Indeed"],["شَانِئَكَ","your enemy "],["هُوَ","he (is)"],["ٱلْأَبْتَرُ","the one cut off"]]],"6208":["(Katakanlah, \"Hai orang-orang kafir!)",[["قُلْ","Say"],["يَـٰٓأَيُّهَا","O"],["ٱلْكَـٰفِرُونَ","disbelievers"]]],"6209":["(Aku tidak akan menyembah) maksudnya sekarang aku tidak akan menyembah (apa yang kalian sembah) yakni berhala-berhala yang kalian sembah itu.",[["لَآ","Not"],["أَعْبُدُ","I worship"],["مَا","what"],["تَعْبُدُونَ","you worship"]]],"6210":["(Dan kalian bukan penyembah) dalam waktu sekarang (Tuhan yang aku sembah) yaitu Allah swt. semata.",[["وَلَآ","And not"],["أَنتُمْ","you"],["عَـٰبِدُونَ","(are) worshippers"],["مَآ","(of) what"],["أَعْبُدُ","I worship"]]],"6211":["(Dan aku tidak mau menyembah) di masa mendatang (apa yang kalian sembah.)",[["وَلَآ","And not"],["أَنَا۠","I am"],["عَابِدٌۭ","a worshipper"],["مَّا","(of) what"],["عَبَدتُّمْ","you worship"]]],"6212":["(Dan kalian tidak mau pula menyembah) di masa mendatang (Tuhan yang aku sembah) Allah swt. telah mengetahui melalui ilmu-Nya, bahwasanya mereka di masa mendatang pun tidak akan mau beriman. Disebutkannya lafal Maa dengan maksud Allah adalah hanya meninjau dari segi Muqabalahnya. Dengan kata lain, bahwa Maa yang pertama tidaklah sama dengan Maa yang kedua.",[["وَلَآ","And not"],["أَنتُمْ","you"],["عَـٰبِدُونَ","(are) worshippers"],["مَآ","(of) what"],["أَعْبُدُ","I worship"]]],"6213":["(Untuk kalianlah agama kalian) yaitu agama kemusyrikan (dan untukkulah agamaku\") yakni agama Islam. Ayat ini diturunkan sebelum Nabi saw. diperintahkan untuk memerangi mereka. Ya Idhafah yang terdapat pada lafal ini tidak disebutkan oleh ahli qiraat sab'ah, baik dalam keadaan Waqaf atau pun Washal. Akan tetapi Imam Ya'qub menyebutkannya dalam kedua kondisi tersebut.",[["لَكُمْ","For you"],["دِينُكُمْ","(is) your religion"],["وَلِىَ","and for me"],["دِينِ","(is) my religion"]]],"6214":["(Apabila telah datang pertolongan Allah) kepada Nabi-Nya atas musuh-musuhnya (dan kemenangan) yakni kemenangan atas kota Mekah.",[["إِذَا","When"],["جَآءَ","comes"],["نَصْرُ","(the) Help"],["ٱللَّهِ","(of) Allah"],["وَٱلْفَتْحُ","and the Victory"]]],"6215":["(Dan kamu lihat manusia masuk agama Allah) yaitu agama Islam (dengan berbondong-bondong) atau secara berkelompok, yang pada sebelumnya hanya secara satu persatu. Hal tersebut terjadi sesudah kemenangan atas kota Mekah, lalu orang-orang Arab dari semua kawasan datang kepada Nabi saw. dalam keadaan taat untuk masuk Islam.",[["وَرَأَيْتَ","And you see"],["ٱلنَّاسَ","the people"],["يَدْخُلُونَ","entering"],["فِى","into"],["دِينِ","(the) religion"],["ٱللَّهِ","(of) Allah"],["أَفْوَاجًۭا","(in) multitudes"]]],"6216":["(Maka bertasbihlah dengan memuji Rabbmu) artinya bertasbihlah seraya memuji-Nya (dan mohonlah ampun kepada-Nya. Sesungguhnya Dia adalah Maha Penerima tobat) sesungguhnya Nabi saw. sesudah surah ini diturunkan, beliau selalu memperbanyak bacaan: Subhaanallaah Wa Bihamdihi, Astaghfirullaaha Wa Atuubu Ilaihi, yang artinya: \"Maha Suci Allah dengan segala pujian-Nya, aku memohon ampun kepada Allah dan bertobat kepada-Nya.\" Dengan turunnya surah ini dapat diketahui bahwa saat ajalnya telah dekat. Peristiwa penaklukan kota Mekah itu terjadi pada bulan Ramadan tahun delapan Hijriah, dan beliau wafat pada bulan Rabiulawal, tahun sepuluh Hijriah.",[["فَسَبِّحْ","Then glorify"],["بِحَمْدِ","with (the) praises"],["رَبِّكَ","(of) your Lord"],["وَٱسْتَغْفِرْهُ ۚ","and ask His forgiveness"],["إِنَّهُۥ","Indeed, He"],["كَانَ","is"],["تَوَّابًۢا","Oft-Returning"]]],"6217":["(Binasalah) atau merugilah (kedua tangan Abu Lahab) maksudnya diri Abu Lahab; di sini diungkapkan dengan memakai kata-kata kedua tangan sebagai ungkapan Majaz, karena sesungguhnya kebanyakan pekerjaan yang dilakukan oleh manusia itu dikerjakan dengan kedua tangannya; Jumlah kalimat ini mengandung makna doa (dan sesungguhnya dia binasa) artinya dia benar-benar merugi. Kalimat ayat ini adalah kalimat berita; perihalnya sama dengan perkataan mereka: Ahlakahullaahu Waqad Halaka, yang artinya: \"Semoga Allah membinasakannya; dan sungguh dia benar-benar binasa.\" Ketika Nabi saw. menakut-nakutinya dengan azab, ia berkata, \"Jika apa yang telah dikatakan oleh anak saudaraku itu benar, maka sesungguhnya aku akan menebus diriku dari azab itu dengan harta benda dan anak-anakku.\" Lalu turunlah ayat selanjutnya, yaitu:",[["تَبَّتْ","Perish"],["يَدَآ","(the) hands"],["أَبِى","(of) Abu"],["لَهَبٍۢ","Lahab"],["وَتَبَّ","and perish he"]]],"6218":["(Tidaklah berfaedah kepadanya harta benda dan apa yang ia usahakan) maksudnya apa yang telah diusahakannya itu, yakni anak-anaknya. Lafal Aghnaa di sini bermakna Yughnii, artinya tidak akan berfaedah kepadanya harta dan anak-anaknya.",[["مَآ","Not"],["أَغْنَىٰ","(will) avail"],["عَنْهُ","him"],["مَالُهُۥ","his wealth"],["وَمَا","and what"],["كَسَبَ","he earned"]]],"6219":["(Kelak dia akan masuk ke dalam api yang bergejolak) yang besar nyalanya; kata-kata ini pun dijadikan pula sebagai julukan namanya, karena ia mempunyai muka yang berbinar-binar memancarkan sinar merah api.",[["سَيَصْلَىٰ","He will be burnt"],["نَارًۭا","(in) a Fire"],["ذَاتَ","of"],["لَهَبٍۢ","Blazing Flames"]]],"6220":["(Dan begitu pula istrinya) lafal ini di'athafkan kepada Dhamir yang terkandung di dalam lafal Yashlaa, hal ini diperbolehkan karena di antara keduanya terdapat pemisah, yaitu Maf'ul dan sifatnya; yang dimaksud adalah Umu Jamil (pembawa) dapat dibaca Hammalaatun dan Hammaalatan (kayu bakar) yaitu duri dan kayu Sa'dan yang banyak durinya, kemudian kayu dan duri itu ia taruh di tengah jalan tempat Nabi saw. lewat.",[["وَٱمْرَأَتُهُۥ","And his wife"],["حَمَّالَةَ","(the) carrier"],["ٱلْحَطَبِ","(of) firewood"]]],"6221":["(Yang di lehernya) atau pada lehernya (ada tali dari sabut) yakni pintalan dari sabut; Jumlah ayat ini berkedudukan menjadi Haal atau kata keterangan dari lafal Hammaalatal Hathab yang merupakan sifat dari istri Abu Lahab. Atau kalimat ayat ini dapat dianggap sebagai Khabar dari Mubtada yang tidak disebutkan.",[["فِى","In"],["جِيدِهَا","her neck"],["حَبْلٌۭ","(will be) a rope"],["مِّن","of"],["مَّسَدٍۭ","palm-fiber"]]],"6222":["(Katakanlah, \"Dialah Allah Yang Maha Esa\") lafal Allah adalah Khabar dari lafal Huwa, sedangkan lafal Ahadun adalah Badal dari lafal Allah, atau Khabar kedua dari lafal Huwa.",[["قُلْ","Say"],["هُوَ","He"],["ٱللَّهُ","(is) Allah"],["أَحَدٌ","the One"]]],"6223":["(Allah adalah Tuhan yang bergantung kepada-Nya segala sesuatu) lafal ayat ini terdiri dari Mubtada dan Khabar; artinya Dia adalah Tuhan yang bergantung kepada-Nya segala sesuatu untuk selama-lamanya.",[["ٱللَّهُ","Allah"],["ٱلصَّمَدُ","the Eternal, the Absolute"]]],"6224":["(Dia tiada beranak) karena tiada yang menyamai-Nya (dan tiada pula diperanakkan) karena mustahil hal ini terjadi bagi-Nya.",[["لَمْ","Not"],["يَلِدْ","He begets"],["وَلَمْ","and not"],["يُولَدْ","He is begotten"]]],"6225":["(Dan tidak ada seorang pun yang setara dengan Dia) atau yang sebanding dengan-Nya, lafal Lahu berta'alluq kepada lafal Kufuwan. Lafal Lahu ini didahulukan karena dialah yang menjadi subjek penafian; kemudian lafal Ahadun diakhirkan letaknya padahal ia sebagai isim dari lafal Yakun, sedangkan Khabar yang seharusnya berada di akhir mendahuluinya; demikian itu karena demi menjaga Fashilah atau kesamaan bunyi pada akhir ayat.",[["وَلَمْ","And not"],["يَكُن","is"],["لَّهُۥ","for Him"],["كُفُوًا","equivalent"],["أَحَدٌۢ","any [one]"]]],"6226":["(Katakanlah, \"Aku berlindung kepada Rabb Yang menguasai falaq) atau waktu subuh.",[["قُلْ","Say"],["أَعُوذُ","I seek refuge"],["بِرَبِّ","in (the) Lord"],["ٱلْفَلَقِ","(of) the dawn"]]],"6227":["(Dari kejahatan apa yang telah diciptakan-Nya) yaitu dari kejahatan makhluk hidup yang berakal dan yang tidak berakal; serta dari kejahatan benda mati seperti racun dan lain sebagainya.",[["مِن","From"],["شَرِّ","(the) evil"],["مَا","(of) what"],["خَلَقَ","He created"]]],"6228":["(Dan dari kejahatan malam apabila telah gelap gulita) artinya dari kejahatan malam hari apabila telah gelap, dan dari kejahatan waktu purnama apabila telah terbenam.",[["وَمِن","And from"],["شَرِّ","(the) evil"],["غَاسِقٍ","(of) darkness"],["إِذَا","when"],["وَقَبَ","it spreads"]]],"6229":["(Dan dari kejahatan wanita-wanita tukang sihir yang menghembus) yaitu tukang-tukang sihir wanita yang menghembuskan sihirnya (pada buhul-buhul) yang dibuat pada pintalan, kemudian pintalan yang berbuhul itu ditiup dengan memakai mantera-mantera tanpa ludah. Zamakhsyari mengatakan, sebagaimana yang telah dilakukan oleh anak-anak perempuan Lubaid yang telah disebutkan di atas tadi.",[["وَمِن","And from"],["شَرِّ","(the) evil"],["ٱلنَّفَّـٰثَـٰتِ","(of) the blowers"],["فِى","in"],["ٱلْعُقَدِ","the knots"]]],"6230":["(Dan dari kejahatan orang yang dengki apabila ia dengki) atau apabila ia menampakkan kedengkiannya lalu berusaha atas kedengkian yang dipendamnya itu, sebagaimana yang telah dikerjakan oleh Lubaid si Yahudi tadi; dia termasuk orang-orang yang dengki terhadap Nabi saw. Ketiga jenis kejahatan yang disebutkan sesudah lafal Maa Khalaq, padahal semuanya itu telah terkandung di dalam maknanya, hal ini tiada lain mengingat kejahatan yang ditimbulkan oleh ketiga perkara tersebut sangat parah.",[["وَمِن","And from"],["شَرِّ","(the) evil"],["حَاسِدٍ","(of) an envier"],["إِذَا","when"],["حَسَدَ","he envies"]]],"6231":["(Katakanlah, \"Aku berlindung kepada Rabb manusia) Yang menciptakan dan Yang memiliki mereka; di sini manusia disebutkan secara khusus sebagai penghormatan buat mereka; dan sekaligus untuk menyesuaikan dengan pengertian Isti'adzah dari kejahatan yang menggoda hati mereka.",[["قُلْ","Say"],["أَعُوذُ","I seek refuge"],["بِرَبِّ","in (the) Lord"],["ٱلنَّاسِ","(of) mankind"]]],"6232":["(Raja manusia.)",[["مَلِكِ","(The) King"],["ٱلنَّاسِ","(of) mankind"]]],"6233":["(Sesembahan manusia) kedua ayat tersebut berkedudukan sebagai Badal atau sifat, atau 'Athaf Bayan, kemudian Mudhaf Ilaih. Lafal An-Naas disebutkan di dalam kedua ayat ini, dimaksud untuk menambah jelas makna.",[["إِلَـٰهِ","(The) God"],["ٱلنَّاسِ","(of) mankind"]]],"6234":["(Dari kejahatan bisikan) setan; setan dinamakan bisikan karena kebanyakan godaan yang dilancarkannya itu melalui bisikan (yang biasa bersembunyi) karena setan itu suka bersembunyi dan meninggalkan hati manusia bila hati manusia ingat kepada Allah.",[["مِن","From"],["شَرِّ","(the) evil"],["ٱلْوَسْوَاسِ","(of) the whisperer"],["ٱلْخَنَّاسِ","the one who withdraws"]]],"6235":["(Yang membisikkan kejahatan ke dalam dada manusia) ke dalam kalbu manusia di kala mereka lalai mengingat Allah.",[["ٱلَّذِى","The one who"],["يُوَسْوِسُ","whispers"],["فِى","in"],["صُدُورِ","(the) breasts"],["ٱلنَّاسِ","(of) mankind"]]],"6236":["(Dari jin dan manusia\") lafal ayat ini menjelaskan pengertian setan yang menggoda itu, yaitu terdiri dari jenis jin dan manusia, sebagaimana yang dijelaskan dalam ayat lainnya, yaitu melalui firman-Nya, \"yaitu setan-setan dari jenis manusia dan dari jenis jin.\" (Q.S. Al-An'am, 112) Atau lafal Minal Jinnati menjadi Bayan dari lafal Al-Waswaasil Khannaas, sedangkan lafal An-Naas di'athafkan kepada lafal Al-Waswaas. Tetapi pada garis besarnya telah mencakup kejahatan yang dilakukan oleh Lubaid dan anak-anak perempuannya yang telah disebutkan tadi. Pendapat pertama yang mengatakan bahwa di antara yang menggoda hati manusia adalah manusia di samping setan, pendapat tersebut disanggah dengan suatu kenyataan, bahwa yang dapat menggoda hati manusia hanyalah bangsa jin atau setan saja. Sanggahan ini dapat dibantah pula, bahwasanya manusia pun dapat pula menggoda manusia lainnya, yaitu dengan cara yang sesuai dengan keadaan dan kondisi mereka sebagai manusia. Godaan tersebut melalui lahiriah, kemudian merasuk ke dalam kalbu dan menjadi mantap di dalamnya, yaitu melalui cara yang dapat menjurus ke arah itu. --- Wallahu A'lam - Akhirnya hanya Allah sajalah Yang Maha Mengetahui.",[["مِنَ","From"],["ٱلْجِنَّةِ","the jinn"],["وَٱلنَّاسِ","and men"]]]});